def _long_leave_last_col():
    return re.sub(r"\d", "", gspread.utils.rowcol_to_a1(1, len(LONG_LEAVE_HEADERS)))


def _get_long_leave_worksheet():
    client = get_gspread_client()
    if not client:
        return None
    ss = client.open_by_key(SHEET_DU_PHONG_ID)
    ws = _get_or_create_worksheet(
        ss, LONG_LEAVE_WORKSHEET, rows=2000, cols=len(LONG_LEAVE_HEADERS)
    )
    if int(getattr(ws, "col_count", 0) or 0) < len(LONG_LEAVE_HEADERS):
        _gs_call_with_backoff(ws.resize, cols=len(LONG_LEAVE_HEADERS))
    header = _gs_call_with_backoff(ws.row_values, 1)
    if header[:len(LONG_LEAVE_HEADERS)] != LONG_LEAVE_HEADERS:
        gspread_update_range(
            ws,
            f"A1:{_long_leave_last_col()}1",
            [LONG_LEAVE_HEADERS]
        )
    return ws


@st.cache_data(ttl=60, show_spinner=False)
def load_long_leave_requests():
    try:
        ws = _get_long_leave_worksheet()
        if ws is None:
            return pd.DataFrame(columns=LONG_LEAVE_HEADERS + ["__row"])
        vals = _gs_call_with_backoff(ws.get_all_values)
        rows = []
        for ridx, row in enumerate(vals[1:], start=2):
            rr = list(row[:len(LONG_LEAVE_HEADERS)]) + [""] * max(
                0, len(LONG_LEAVE_HEADERS) - len(row)
            )
            if any(str(v).strip() for v in rr):
                rec = dict(zip(LONG_LEAVE_HEADERS, rr[:len(LONG_LEAVE_HEADERS)]))
                rec["__row"] = ridx
                rows.append(rec)
        return pd.DataFrame(rows) if rows else pd.DataFrame(
            columns=LONG_LEAVE_HEADERS + ["__row"]
        )
    except Exception:
        return pd.DataFrame(columns=LONG_LEAVE_HEADERS + ["__row"])


def _clear_long_leave_cache():
    try:
        load_long_leave_requests.clear()
    except Exception:
        pass
    try:
        download_long_leave_document.clear()
    except Exception:
        pass


def _long_leave_request_id(employee_name):
    raw = (
        f"{normalize_login_name(employee_name)}|"
        f"{datetime.now(VN_TZ).isoformat()}|{secrets.token_hex(4)}"
    )
    return "LL-" + hashlib.sha1(raw.encode("utf-8")).hexdigest()[:12].upper()


def append_long_leave_request(
    employee_name, role, start_date, end_date, reason, detail,
    status, source, updated_by, email_cc=""
):
    try:
        ws = _get_long_leave_worksheet()
        if ws is None:
            return False, "Không kết nối được Google Sheets.", ""
        now = datetime.now(VN_TZ)
        req_id = _long_leave_request_id(employee_name)
        row = [
            req_id, str(employee_name).strip(), str(role).strip().lower(),
            start_date.strftime("%d/%m/%Y"), end_date.strftime("%d/%m/%Y"),
            str(reason).strip(), str(detail).strip(), str(status).strip(), "",
            now.strftime("%d/%m/%Y"), now.strftime("%H:%M:%S"),
            "", "", "", str(source).strip(), str(updated_by).strip(),
            now.strftime("%d/%m/%Y %H:%M:%S"),
            "", "", "", "", str(email_cc or "").strip(),
        ]
        _gs_call_with_backoff(ws.append_row, row, value_input_option="USER_ENTERED")
        _clear_long_leave_cache()
        return True, "Đã lưu yêu cầu nghỉ dài hạn.", req_id
    except Exception as e:
        return False, f"Lỗi lưu yêu cầu nghỉ dài hạn: {e}", ""


def update_long_leave_row(row_idx, updates, updated_by):
    try:
        ws = _get_long_leave_worksheet()
        if ws is None:
            return False, "Không kết nối được Google Sheets."
        vals = _gs_call_with_backoff(ws.row_values, int(row_idx))
        row = list(vals[:len(LONG_LEAVE_HEADERS)]) + [""] * max(
            0, len(LONG_LEAVE_HEADERS) - len(vals)
        )
        cmap = {name: i for i, name in enumerate(LONG_LEAVE_HEADERS)}
        for k, v in (updates or {}).items():
            if k in cmap:
                row[cmap[k]] = v
        now = datetime.now(VN_TZ)
        row[cmap["Người cập nhật"]] = str(updated_by).strip()
        row[cmap["Cập nhật lúc"]] = now.strftime("%d/%m/%Y %H:%M:%S")
        gspread_update_range(
            ws,
            f"A{int(row_idx)}:{_long_leave_last_col()}{int(row_idx)}",
            [row]
        )
        _clear_long_leave_cache()
        return True, "Đã cập nhật yêu cầu nghỉ dài hạn."
    except Exception as e:
        return False, f"Lỗi cập nhật yêu cầu: {e}"


def delete_long_leave_row(row_idx):
    try:
        ws = _get_long_leave_worksheet()
        if ws is None:
            return False, "Không kết nối được Google Sheets."
        _gs_call_with_backoff(ws.delete_rows, int(row_idx))
        _clear_long_leave_cache()
        return True, "Đã xóa bản ghi nghỉ dài hạn."
    except Exception as e:
        return False, f"Lỗi xóa bản ghi: {e}"


def _long_leave_role_cc_emails():
    """Email CC của tất cả tài khoản quanly / letan / leader có email hợp lệ."""
    try:
        creds = load_credentials_fresh_for_email()
        if not isinstance(creds, pd.DataFrame) or creds.empty:
            return []
        if "Phân quyền" not in creds.columns or "Email" not in creds.columns:
            return []
        d = creds[
            creds["Phân quyền"].astype(str).str.strip().str.lower()
            .isin({"quanly", "letan", "leader"})
        ].copy()
        if "Trạng thái làm việc" in d.columns:
            d = d[
                ~d["Trạng thái làm việc"].astype(str).str.strip()
                .eq(EMPLOYMENT_STATUS_LEFT)
            ]
        emails = []
        for value in d["Email"].astype(str).tolist():
            value = value.strip()
            if value and "@" in value:
                emails.append(value)
        return sorted(set(emails))
    except Exception:
        return []


def _long_leave_employee_email(employee_name):
    try:
        return latest_email_from_credentials(
            load_credentials_fresh_for_email(), employee_name
        )
    except Exception:
        return ""


def _parse_long_leave_documents(value):
    try:
        parsed = json.loads(str(value or "").strip() or "[]")
        return parsed if isinstance(parsed, list) else []
    except Exception:
        return []


def _google_drive_bearer_token():
    client = get_gspread_client()
    if client is None:
        raise RuntimeError("Không kết nối được Google.")
    creds = getattr(client, "auth", None)
    if creds is None:
        raise RuntimeError("Không lấy được Google credentials.")
    from google.auth.transport.requests import Request as GoogleAuthRequest
    if (
        not getattr(creds, "valid", False)
        or getattr(creds, "expired", False)
        or not getattr(creds, "token", None)
    ):
        creds.refresh(GoogleAuthRequest())
    token = str(getattr(creds, "token", "") or "").strip()
    if not token:
        raise RuntimeError("Google token rỗng.")
    return token


def _long_leave_drive_folder_id():
    env = str(os.getenv("LONG_LEAVE_DRIVE_FOLDER_ID", "") or "").strip()
    if env:
        return env
    try:
        return str(st.secrets.get("LONG_LEAVE_DRIVE_FOLDER_ID", "") or "").strip()
    except Exception:
        return ""


def upload_long_leave_document(uploaded_file, request_id, uploaded_by):
    if uploaded_file is None:
        return False, "Không có file.", None
    try:
        token = _google_drive_bearer_token()
        data = uploaded_file.getvalue()
        mime = str(
            getattr(uploaded_file, "type", "") or "application/octet-stream"
        )
        original_name = os.path.basename(
            str(getattr(uploaded_file, "name", "tai_lieu") or "tai_lieu")
        )
        headers = {
            "Authorization": f"Bearer {token}",
            "Content-Type": mime,
        }
        r = requests.post(
            "https://www.googleapis.com/upload/drive/v3/files"
            "?uploadType=media&supportsAllDrives=true",
            headers=headers,
            data=data,
            timeout=90,
        )
        if not r.ok:
            raise RuntimeError(
                f"Drive upload HTTP {r.status_code}: {r.text[:300]}"
            )
        file_id = str((r.json() or {}).get("id", "")).strip()
        if not file_id:
            raise RuntimeError("Drive không trả file_id.")

        safe_req = re.sub(r"[^A-Za-z0-9_-]+", "_", str(request_id))
        meta = {
            "name": f"{safe_req}__{original_name}",
            "description": (
                f"VERA SPA - Tài liệu nghỉ dài hạn {request_id} - "
                f"tải bởi {uploaded_by}"
            ),
            "appProperties": {
                "vera_request_id": str(request_id),
                "vera_uploaded_by": str(uploaded_by),
            },
        }
        folder_id = _long_leave_drive_folder_id()
        patch_url = (
            f"https://www.googleapis.com/drive/v3/files/{file_id}"
            "?supportsAllDrives=true"
        )
        if folder_id:
            patch_url += f"&addParents={folder_id}"
        requests.patch(
            patch_url,
            headers={
                "Authorization": f"Bearer {token}",
                "Content-Type": "application/json",
            },
            json=meta,
            timeout=60,
        )
        record = {
            "id": file_id,
            "name": original_name,
            "mime": mime,
            "size": len(data),
            "uploaded_at": datetime.now(VN_TZ).strftime("%d/%m/%Y %H:%M:%S"),
            "uploaded_by": str(uploaded_by),
        }
        return True, f"Đã tải {original_name}.", record
    except Exception as e:
        return False, f"Lỗi tải tài liệu: {e}", None


@st.cache_data(ttl=300, show_spinner=False)
def download_long_leave_document(file_id):
    token = _google_drive_bearer_token()
    r = requests.get(
        f"https://www.googleapis.com/drive/v3/files/{file_id}"
        "?alt=media&supportsAllDrives=true",
        headers={"Authorization": f"Bearer {token}"},
        timeout=90,
    )
    if not r.ok:
        raise RuntimeError(f"Không tải được tài liệu: HTTP {r.status_code}")
    return r.content


def attach_documents_to_long_leave_request(request_id, uploaded_files, uploaded_by):
    files = [f for f in (uploaded_files or []) if f is not None]
    if not files:
        return True, "Không có tài liệu mới.", []
    df = load_long_leave_requests()
    if df.empty:
        return False, "Không tìm thấy yêu cầu để gắn tài liệu.", []
    hit = df[df["ID"].astype(str).str.strip().eq(str(request_id).strip())]
    if hit.empty:
        return False, "Không tìm thấy mã yêu cầu.", []
    row = hit.iloc[0]
    row_idx = int(row.get("__row", 0) or 0)
    existing = _parse_long_leave_documents(row.get("Tài liệu JSON", ""))
    added, errors = [], []
    for f in files:
        ok, msg, record = upload_long_leave_document(f, request_id, uploaded_by)
        if ok and record:
            added.append(record)
        else:
            errors.append(msg)
    if added:
        ok_up, msg_up = update_long_leave_row(
            row_idx,
            {
                "Tài liệu JSON": json.dumps(existing + added, ensure_ascii=False),
                "Nhắc tải tài liệu": "",
                "Ngày nhắc": "",
                "Người nhắc": "",
            },
            uploaded_by,
        )
        if not ok_up:
            return False, msg_up, added
    if errors:
        return bool(added), " | ".join(errors), added
    return True, f"Đã tải {len(added)} tài liệu.", added


def send_long_leave_request_email(
    employee_name, role, start_date, end_date, reason, detail, request_id,
    attachments=None, cc_emails=None
):
    sender_email, sender_password = get_smtp_sender_credentials()
    if not sender_email or not sender_password:
        return False, "Chưa cấu hình SMTP."
    try:
        cc_list = sorted(set(
            [e for e in (cc_emails or _long_leave_role_cc_emails()) if e and "@" in e]
        ))
        cc_list = [
            e for e in cc_list
            if normalize_login_name(e) != normalize_login_name(LONG_LEAVE_ADMIN_EMAIL)
        ]
        subject = (
            f"[VERA SPA] Đơn xin nghỉ dài hạn - {employee_name} - "
            f"{start_date.strftime('%d/%m/%Y')} đến {end_date.strftime('%d/%m/%Y')}"
        )
        safe_detail = html.escape(str(detail or "")).replace("\n", "<br>")
        body = f"""
        <html><body style='font-family:Arial,sans-serif'>
        <h3>Đơn xin nghỉ dài hạn</h3>
        <p><b>Mã yêu cầu:</b> {html.escape(str(request_id))}</p>
        <p><b>Nhân viên:</b> {html.escape(str(employee_name))}</p>
        <p><b>Vai trò:</b> {html.escape(str(role))}</p>
        <p><b>Thời gian:</b> {start_date.strftime('%d/%m/%Y')} - {end_date.strftime('%d/%m/%Y')}</p>
        <p><b>Lý do:</b> {html.escape(str(reason))}</p>
        <p><b>Chi tiết:</b><br>{safe_detail}</p>
        <p>Yêu cầu đang chờ Admin duyệt trên hệ thống VERA SPA.</p>
        <p>Email này được CC tới Quản lý, Lễ tân và Leader có email trong hồ sơ.</p>
        </body></html>
        """
        msg = MIMEMultipart()
        msg["From"] = f"Vera Spa <{sender_email}>"
        msg["To"] = LONG_LEAVE_ADMIN_EMAIL
        if cc_list:
            msg["Cc"] = ", ".join(cc_list)
        msg["Subject"] = subject
        msg.attach(MIMEText(body, "html"))
        for f in (attachments or []):
            try:
                part = MIMEApplication(f.getvalue(), Name=os.path.basename(f.name))
                part["Content-Disposition"] = (
                    f'attachment; filename="{os.path.basename(f.name)}"'
                )
                msg.attach(part)
            except Exception:
                pass
        server = smtplib.SMTP("smtp.gmail.com", 587)
        server.starttls()
        server.login(sender_email, sender_password)
        server.send_message(
            msg,
            from_addr=sender_email,
            to_addrs=[LONG_LEAVE_ADMIN_EMAIL] + cc_list,
        )
        server.quit()
        return True, (
            "Đã gửi email tới Admin"
            + (f" và CC {len(cc_list)} email Quản lý/Lễ tân/Leader." if cc_list else ".")
        )
    except Exception as e:
        return False, f"Lỗi gửi email: {e}"


def send_long_leave_document_reminder(employee_name, request_id, end_date):
    to_email = _long_leave_employee_email(employee_name)
    if not to_email:
        return False, "Nhân viên chưa có Email trong hồ sơ."
    sender_email, sender_password = get_smtp_sender_credentials()
    if not sender_email or not sender_password:
        return False, "Chưa cấu hình SMTP."
    try:
        msg = MIMEMultipart()
        msg["From"] = f"Vera Spa <{sender_email}>"
        msg["To"] = to_email
        msg["Subject"] = f"[VERA SPA] Nhắc tải tài liệu nghỉ dài hạn - {employee_name}"
        msg.attach(MIMEText(
            f"""
            <html><body style='font-family:Arial,sans-serif'>
            <p>Chào <b>{html.escape(str(employee_name))}</b>,</p>
            <p>VERA SPA nhắc bạn tải tài liệu liên quan cho đơn nghỉ dài hạn
            <b>{html.escape(str(request_id))}</b>.</p>
            <p>Ngày kết thúc nghỉ: <b>{html.escape(str(end_date))}</b>.</p>
            <p>Bạn có thể tải tài liệu tại trang <b>Lịch nghỉ dài hạn</b>,
            kể cả sau khi thời gian nghỉ đã kết thúc.</p>
            </body></html>
            """,
            "html"
        ))
        server = smtplib.SMTP("smtp.gmail.com", 587)
        server.starttls()
        server.login(sender_email, sender_password)
        server.send_message(msg)
        server.quit()
        return True, "Đã gửi email nhắc tải tài liệu."
    except Exception as e:
        return False, f"Lỗi gửi nhắc nhở: {e}"


def long_leave_active_records(df=None):
    d = df.copy() if isinstance(df, pd.DataFrame) else load_long_leave_requests()
    if d.empty:
        return d
    return d[d["Trạng thái"].astype(str).str.strip().eq(LONG_LEAVE_APPROVED)].copy()


def pending_long_leave_count():
    d = load_long_leave_requests()
    if d.empty:
        return 0
    return int(
        d["Trạng thái"].astype(str).str.strip().eq(LONG_LEAVE_PENDING).sum()
    )


LONG_LEAVE_REQUEST_PAUSE_KEY = "long_leave_request_pause_v905"


@st.cache_data(ttl=15, show_spinner=False)
def load_long_leave_request_pause():
    default = {
        "enabled": False,
        "message": "Admin đang tạm dừng nhận đơn nghỉ dài hạn.",
        "updated_by": "",
        "updated_at": "",
    }
    try:
        ws, err = _ensure_ui_theme_storage()
        if err or ws is None:
            return default.copy()
        vals = _gs_call_with_backoff(ws.get_all_values)
        for row in vals[1:]:
            if row and str(row[0]).strip() == LONG_LEAVE_REQUEST_PAUSE_KEY:
                try:
                    raw = json.loads(row[1]) if len(row) > 1 and str(row[1]).strip() else {}
                except Exception:
                    raw = {}
                out = default.copy()
                if isinstance(raw, dict):
                    out["enabled"] = bool(raw.get("enabled", False))
                    out["message"] = str(raw.get("message", default["message"]) or default["message"]).strip()
                    out["updated_by"] = str(raw.get("updated_by", "") or "").strip()
                    out["updated_at"] = str(raw.get("updated_at", "") or "").strip()
                return out
        return default.copy()
    except Exception:
        return default.copy()


def save_long_leave_request_pause(enabled, username, message=""):
    try:
        ws, err = _ensure_ui_theme_storage()
        if err or ws is None:
            return False, err or "Không mở được sheet cấu hình."
        vals = _gs_call_with_backoff(ws.get_all_values)
        row_idx = None
        for idx, row in enumerate(vals[1:], start=2):
            if row and str(row[0]).strip() == LONG_LEAVE_REQUEST_PAUSE_KEY:
                row_idx = idx
                break
        now = datetime.now(VN_TZ).strftime("%d/%m/%Y %H:%M:%S")
        payload = {
            "enabled": bool(enabled),
            "message": str(message or "Admin đang tạm dừng nhận đơn nghỉ dài hạn.").strip(),
            "updated_by": str(username or "").strip(),
            "updated_at": now,
        }
        row = [
            LONG_LEAVE_REQUEST_PAUSE_KEY,
            json.dumps(payload, ensure_ascii=False),
            now,
            str(username or "").strip(),
        ]
        if row_idx:
            gspread_update_range(ws, f"A{row_idx}:D{row_idx}", [row])
        else:
            _gs_call_with_backoff(ws.append_row, row, value_input_option="USER_ENTERED")
        try:
            load_long_leave_request_pause.clear()
        except Exception:
            pass
        return True, "Đã cập nhật trạng thái nhận đơn nghỉ dài hạn."
    except Exception as e:
        return False, f"Lỗi cập nhật trạng thái nhận đơn: {e}"


def count_employee_long_leave_requests_in_month(employee_name, ref_date=None):
    """Đếm số đơn do chính nhân viên gửi trong tháng của Ngày gửi."""
    ref_date = ref_date or get_vn_today()
    d = load_long_leave_requests()
    if not isinstance(d, pd.DataFrame) or d.empty:
        return 0
    emp_key = normalize_login_name(employee_name)
    work = d[
        d["Tên nhân viên"].astype(str).apply(normalize_login_name).eq(emp_key)
    ].copy()
    if "Nguồn" in work.columns:
        work = work[
            work["Nguồn"].astype(str).str.contains("Nhân viên gửi yêu cầu", case=False, na=False)
        ]
    if work.empty:
        return 0
    parsed = work["Ngày gửi"].apply(_parse_vn_date)
    return int(sum(
        1 for dt in parsed
        if dt is not None and dt.year == ref_date.year and dt.month == ref_date.month
    ))


def _long_leave_rejected_for_notifications(limit=5):
    d = load_long_leave_requests()
    if not isinstance(d, pd.DataFrame) or d.empty:
        return pd.DataFrame()
    out = d[d["Trạng thái"].astype(str).str.strip().eq(LONG_LEAVE_REJECTED)].copy()
    if "__row" in out.columns:
        out = out.sort_values("__row", ascending=False)
    return out.head(max(1, int(limit)))


def reconcile_long_leave_employment_statuses():
    """
    Đồng bộ trạng thái làm việc theo ngày thực tế:
    - Đã duyệt và hôm nay nằm trong khoảng nghỉ -> Tạm thời nghỉ việc.
    - Đã duyệt và đã qua ngày kết thúc -> Đang làm việc + chuyển đơn thành Đã kết thúc.
    Chạy khi app có lượt thực thi, không cần người dùng thao tác tại trang này.
    """
    try:
        d = load_long_leave_requests()
        if not isinstance(d, pd.DataFrame) or d.empty:
            return
        today = get_vn_today()
        approved = d[d["Trạng thái"].astype(str).str.strip().eq(LONG_LEAVE_APPROVED)].copy()
        if approved.empty:
            return

        creds = load_credentials_recent()
        if not isinstance(creds, pd.DataFrame):
            creds = pd.DataFrame()

        for _, row in approved.iterrows():
            start_d = _parse_vn_date(row.get("Từ ngày", ""))
            end_d = _parse_vn_date(row.get("Đến ngày", ""))
            emp = str(row.get("Tên nhân viên", "")).strip()
            if not emp or start_d is None or end_d is None:
                continue

            current_status = ""
            if not creds.empty and "Tên nhân viên" in creds.columns:
                hit = creds[
                    creds["Tên nhân viên"].astype(str).apply(normalize_login_name)
                    .eq(normalize_login_name(emp))
                ]
                if not hit.empty:
                    current_status = str(hit.iloc[-1].get("Trạng thái làm việc", "")).strip()

            if start_d <= today <= end_d:
                if current_status != EMPLOYMENT_STATUS_TEMP:
                    set_employee_employment_status(emp, EMPLOYMENT_STATUS_TEMP, "SYSTEM")
            elif today > end_d:
                if current_status == EMPLOYMENT_STATUS_TEMP:
                    set_employee_employment_status(emp, EMPLOYMENT_STATUS_ACTIVE, "SYSTEM")
                try:
                    update_long_leave_row(
                        int(row.get("__row", 0)),
                        {"Trạng thái": LONG_LEAVE_ENDED},
                        "SYSTEM",
                    )
                except Exception:
                    pass
    except Exception:
        pass


# V92.6.24: thời hạn đăng ký/hủy không còn hard-code; đọc từ LoaiNghi cột I/J.
DEFAULT_LEAVE_PAGE = "📅 Đăng ký nghỉ phép"
DEFAULT_LEAVE_PAGE_SLUG = "dang-ky-thong-ke-nghi-phep"


# ==========================================================
# V87.5 - RERUN GIỮ NGUYÊN TRANG HIỆN TẠI
# Mọi thao tác nội bộ (Lưu/Sửa/Xóa/Tạm hoãn/Cập nhật...) khi rerun
# phải quay lại đúng trang MENU đang mở, không rơi về trang mặc định.
# ==========================================================
def rerun_current_view():
    # V92.5: mọi rerun nội bộ phải giữ remember_token để Refresh/F5 không mất phiên.
    try:
        _remember = str(st.session_state.get("vera_remember_token", "") or "").strip()
        if (
            st.session_state.get("logged_in")
            and _remember
            and str(st.query_params.get("remember_token", "") or "").strip() != _remember
        ):
            st.query_params["remember_token"] = _remember
    except Exception:
        pass

    try:
        _current_page = str(st.session_state.get("app_page", "") or "")
        _page_slugs = globals().get("PAGE_SLUGS", {}) or {}
        if _current_page and _current_page in _page_slugs:
            _slug = str(_page_slugs.get(_current_page, "") or "").strip()
            if _slug and str(st.query_params.get("page", "") or "").strip() != _slug:
                st.query_params["page"] = _slug
    except Exception:
        pass

    # Gọi trực tiếp API Streamlit để tránh bị thay thế đệ quy khi chuẩn hóa code.
    getattr(st, "rerun")()


def _set_default_page_after_login(role):
    """Lễ tân/Quản lý/Nhân viên luôn mở trang Đăng ký nghỉ phép sau đăng nhập."""
    role_norm = str(role or '').strip().lower()
    if role_norm in {"letan", "quanly", "nhanvien", "leader"}:
        st.session_state.app_page = DEFAULT_LEAVE_PAGE
        try:
            st.query_params["page"] = DEFAULT_LEAVE_PAGE_SLUG
        except Exception:
            pass

def _parse_birthday_date(value):
    """Đọc ngày sinh từ dd/mm/yyyy, dd-mm-yyyy, serial Excel; chấp nhận cả dd/mm."""
    parsed = _parse_vn_date(value)
    if parsed is not None:
        return parsed
    text = str(value or '').strip()
    if not text:
        return None
    for fmt in ('%d/%m', '%d-%m'):
        try:
            tmp = datetime.strptime(text, fmt)
            return date(2000, tmp.month, tmp.day)
        except Exception:
            pass
    return None

def get_month_birthdays(credentials_df, month=None):
    """Danh sách sinh nhật trong tháng của nhanvien/letan/locker, sắp theo ngày sinh."""
    if credentials_df is None or credentials_df.empty:
        return []
    month = int(month or get_vn_today().month)
    rows = []
    for _, r in credentials_df.iterrows():
        role = str(r.get('Phân quyền', '')).strip().lower()
        if role not in BIRTHDAY_EMPLOYEE_ROLES:
            continue
        dob = _parse_birthday_date(r.get('Ngày sinh', ''))
        if dob is None or dob.month != month:
            continue
        system_name = str(r.get('Tên nhân viên', '')).strip()
        full_name = str(r.get('Họ và tên đầy đủ', '')).strip()
        display_name = full_name or system_name
        if not display_name:
            continue
        rows.append({
            'Tên nhân viên': system_name,
            'Họ và tên': display_name,
            'Ngày sinh': f"{dob.day:02d}/{dob.month:02d}",
            'Ngày': dob.day,
            'Vai trò': role,
        })
    rows.sort(key=lambda x: (x['Ngày'], normalize_login_name(x['Họ và tên'])))
    return rows

def _get_birthday_notice_worksheet():
    client = get_gspread_client()
    if not client:
        return None
    ss = client.open_by_key(SHEET_MAT_KHAU_ID)
    ws = _get_or_create_worksheet(ss, BIRTHDAY_NOTICE_WORKSHEET, rows=1000, cols=6)
    header = _gs_call_with_backoff(ws.row_values, 1)
    wanted = ["Tài khoản", "Ngày", "Số lần đăng nhập", "Tạm tắt hôm nay"]
    if header[:4] != wanted:
        gspread_update_range(ws, 'A1:D1', [wanted])
    return ws

def register_birthday_notice_login(username):
    """Tăng bộ đếm đúng 1 lần cho một lần đăng nhập; trả về (count, muted)."""
    today_key = get_vn_today().isoformat()
    user_key = normalize_login_name(username)
    try:
        ws = _get_birthday_notice_worksheet()
        if ws is None:
            return 1, False
        vals = _gs_call_with_backoff(ws.get_all_values)
        found_row = None
        count = 0
        muted = False
        for idx, row in enumerate(vals[1:], start=2):
            if len(row) < 2:
                continue
            if normalize_login_name(row[0]) == user_key and str(row[1]).strip() == today_key:
                found_row = idx
                try:
                    count = int(float(str(row[2]).strip() or '0')) if len(row) > 2 else 0
                except Exception:
                    count = 0
                muted = str(row[3]).strip().casefold() in {'1','true','yes','x','tat','tắt'} if len(row) > 3 else False
                break
        count += 1
        if found_row:
            gspread_update_range(ws, f'C{found_row}', [[count]])
        else:
            _gs_call_with_backoff(ws.append_row, [str(username), today_key, count, ''], value_input_option='USER_ENTERED')
        return count, muted
    except Exception:
        # Nếu Google Sheets tạm lỗi, vẫn cho hiện thông báo trong phiên hiện tại.
        return 1, False

def mute_birthday_notice_today(username):
    """Tạm tắt thông báo sinh nhật cho tài khoản hiện tại đến hết ngày hôm nay."""
    today_key = get_vn_today().isoformat()
    user_key = normalize_login_name(username)
    try:
        ws = _get_birthday_notice_worksheet()
        if ws is None:
            return False, "Không kết nối được Google Sheets."
        vals = _gs_call_with_backoff(ws.get_all_values)
        found_row = None
        count = 0
        for idx, row in enumerate(vals[1:], start=2):
            if len(row) >= 2 and normalize_login_name(row[0]) == user_key and str(row[1]).strip() == today_key:
                found_row = idx
                try:
                    count = int(float(str(row[2]).strip() or '0')) if len(row) > 2 else 0
                except Exception:
                    count = 0
                break
        if found_row:
            gspread_update_range(ws, f'D{found_row}', [["1"]])
        else:
            _gs_call_with_backoff(ws.append_row, [str(username), today_key, max(1, count), '1'], value_input_option='USER_ENTERED')
        return True, "Đã tạm tắt thông báo sinh nhật đến hết hôm nay."
    except Exception as e:
        return False, f"Không thể tạm tắt thông báo: {e}"

def render_birthday_login_notice(credentials_df):
    """Hiện thông báo trong ngày 1-5, tối đa ở 3 lần đăng nhập đầu mỗi ngày."""
    role = str(st.session_state.get('current_role', '')).strip().lower()
    if role not in BIRTHDAY_VIEWER_ROLES:
        st.session_state.birthday_login_event = False
        return
    today = get_vn_today()
    if today.day not in BIRTHDAY_NOTICE_DAYS:
        st.session_state.birthday_login_event = False
        return
    birthdays = get_month_birthdays(credentials_df, today.month)
    if not birthdays:
        st.session_state.birthday_login_event = False
        return
    # Chỉ tăng số lần khi đây thực sự là một phiên vừa đăng nhập.
    if st.session_state.get('birthday_login_event', False):
        count, muted = register_birthday_notice_login(st.session_state.get('current_user', ''))
        st.session_state.birthday_notice_count_today = count
        st.session_state.birthday_notice_muted_today = muted
        st.session_state.birthday_login_event = False
    count = int(st.session_state.get('birthday_notice_count_today', 999) or 999)
    muted = bool(st.session_state.get('birthday_notice_muted_today', False))
    if muted or count > BIRTHDAY_NOTICE_MAX_LOGINS_PER_DAY:
        return

    role_labels = {'nhanvien': 'Nhân viên', 'leader': 'Leader', 'letan': 'Lễ tân', 'locker': 'Locker'}
    lines = []
    for b in birthdays:
        role_label = role_labels.get(b['Vai trò'], b['Vai trò'])
        lines.append(f"🎂 **{b['Họ và tên']}** — {b['Ngày sinh']} — {role_label}")
    st.info("🎉 **SINH NHẬT TRONG THÁNG %02d**\n\n%s" % (today.month, "\n\n".join(lines)))
    c_notice, c_mute = st.columns([4, 1])
    with c_notice:
        st.caption(f"Thông báo này xuất hiện trong ngày 01–05 và tối đa ở 3 lần đăng nhập đầu mỗi ngày. Hôm nay: lần {count}/3.")
    with c_mute:
        if st.button("🔕 Tạm tắt hôm nay", use_container_width=True, key=f"mute_birthday_{today.isoformat()}"):
            ok, msg = mute_birthday_notice_today(st.session_state.get('current_user', ''))
            if ok:
                st.session_state.birthday_notice_muted_today = True
                st.toast(msg)
                rerun_current_view()
            else:
                st.error(msg)

def render_manual_birthday_check(credentials_df, key_prefix="birthday_manual"):
    """Nút chủ động xem sinh nhật tháng hiện tại, dùng cho mọi vai trò."""
    today = get_vn_today()
