def _shift_display_label(name, start_time="", end_time=""):
    name = str(name or "").strip()
    start_time = str(start_time or "").strip()
    end_time = str(end_time or "").strip()
    if start_time and end_time:
        return f"{name} ({start_time} - {end_time})"
    return name


def _get_shift_config_worksheet():
    client = get_gspread_client()
    if not client:
        return None
    ss = client.open_by_key(SHEET_MAT_KHAU_ID)
    ws = _get_or_create_worksheet(
        ss, SHIFT_CONFIG_WORKSHEET, rows=500, cols=max(12, len(SHIFT_CONFIG_HEADERS))
    )
    if int(getattr(ws, "col_count", 0) or 0) < len(SHIFT_CONFIG_HEADERS):
        try:
            _gs_call_with_backoff(ws.resize, cols=max(12, len(SHIFT_CONFIG_HEADERS)))
        except Exception:
            pass

    vals = _gs_call_with_backoff(ws.get_all_values)
    if not vals:
        gspread_update_range(ws, "A1:K1", [SHIFT_CONFIG_HEADERS])
        defaults = [
            ["SHIFT001", "Ca 1", "10:00", "23:00", "", "1", "Đang dùng", "Nhân viên + Leader", "1", "90", "10"],
            ["SHIFT002", "Ca 2", "13:00", "00:00", "", "2", "Đang dùng", "Nhân viên + Leader", "1", "90", "10"],
            ["SHIFT003", "Cố định Ca 1", "", "", "Không đổi", "3", "Đang dùng", "Nhân viên + Leader", "1", "90", "10"],
            ["SHIFT004", "Cố định Ca 2", "", "", "Không đổi", "4", "Đang dùng", "Nhân viên + Leader", "1", "90", "10"],
        ]
        for row in defaults:
            _gs_call_with_backoff(ws.append_row, row, value_input_option="USER_ENTERED")
    else:
        # Nâng sheet cũ: giữ dữ liệu hiện tại, thêm header Bộ phận ở H.
        header = list(vals[0])
        if header[:len(SHIFT_CONFIG_HEADERS)] != SHIFT_CONFIG_HEADERS:
            gspread_update_range(ws, "A1:K1", [SHIFT_CONFIG_HEADERS])

        # Nâng dữ liệu ca cũ:
        # H = Bộ phận; I = Bật/Tắt nghỉ giữa ca; J = Duration.
        if len(vals) > 1:
            for ridx, row in enumerate(vals[1:], start=2):
                if not row or not str(row[1] if len(row) > 1 else "").strip():
                    continue
                dept = str(row[7]).strip() if len(row) > 7 else ""
                if not dept:
                    dept = "Nhân viên + Leader"
                    gspread_update_range(ws, f"H{ridx}:H{ridx}", [[dept]])

                break_enabled = str(row[8]).strip() if len(row) > 8 else ""
                break_duration = str(row[9]).strip() if len(row) > 9 else ""
                dep_default = SHIFT_BREAK_DEFAULTS.get(
                    dept, {"enabled": False, "duration_minutes": 60}
                )
                if break_enabled == "":
                    gspread_update_range(
                        ws, f"I{ridx}:I{ridx}",
                        [["1" if dep_default.get("enabled", False) else "0"]]
                    )
                if break_duration == "":
                    gspread_update_range(
                        ws, f"J{ridx}:J{ridx}",
                        [[str(int(dep_default.get("duration_minutes", 60)))]]
                    )

                # V92.6.13: K = khoảng gom các lần FaceID gần nhau thành 1 cụm.
                faceid_cluster = str(row[10]).strip() if len(row) > 10 else ""
                if faceid_cluster == "":
                    gspread_update_range(
                        ws, f"K{ridx}:K{ridx}", [["10"]]
                    )
    return ws


@st.cache_data(ttl=300, show_spinner=False)
def load_shift_definitions():
    """
    V92.6.11:
    - Nếu đọc được worksheet nhưng không còn ca nào -> trả DataFrame rỗng.
    - KHÔNG tự dựng lại SHIFT001..SHIFT004 sau khi Admin đã xóa.
    - Chỉ dùng fallback mặc định khi thực sự không đọc được Google Sheet.
    """
    columns = [
        "ID", "Tên ca", "Giờ bắt đầu", "Giờ kết thúc", "Ghi chú",
        "Thứ tự", "Trạng thái", "Bộ phận",
        "Áp dụng nghỉ giữa ca", "Duration nghỉ giữa ca (phút)",
        "Khoảng gom FaceID (phút)", "__row",
    ]
    rows = []
    loaded_ok = False

    try:
        ws = _get_shift_config_worksheet()
        if ws is None:
            raise RuntimeError("Không mở được sheet cấu hình ca.")

        vals = _gs_call_with_backoff(ws.get_all_values)
        loaded_ok = True

        for ridx, row in enumerate(vals[1:], start=2):
            rr = list(row[:11]) + [""] * max(0, 11 - len(row))

            # Dòng không có ID và tên ca -> bỏ qua hoàn toàn.
            if not str(rr[0]).strip() and not str(rr[1]).strip():
                continue
            if not str(rr[1]).strip():
                continue

            try:
                order = int(float(rr[5])) if str(rr[5]).strip() else 999
            except Exception:
                order = 999

            dept = str(rr[7]).strip() or "Nhân viên + Leader"
            if dept not in SHIFT_DEPARTMENT_ORDER:
                dept = "Nhân viên + Leader"

            _break_enabled_raw = str(rr[8]).strip().lower()
            _break_enabled = _break_enabled_raw in {
                "1", "true", "yes", "on", "có", "co", "bật", "bat"
            }

            try:
                _break_duration = max(1, min(600, int(float(rr[9]))))
            except Exception:
                _break_duration = int(
                    SHIFT_BREAK_DEFAULTS.get(
                        dept, {"duration_minutes": 60}
                    ).get("duration_minutes", 60)
                )

            try:
                _faceid_cluster_minutes = max(
                    1, min(60, int(float(rr[10] or 10)))
                )
            except Exception:
                _faceid_cluster_minutes = 10

            rows.append({
                "ID": str(rr[0]).strip(),
                "Tên ca": str(rr[1]).strip(),
                "Giờ bắt đầu": str(rr[2]).strip(),
                "Giờ kết thúc": str(rr[3]).strip(),
                "Ghi chú": str(rr[4]).strip(),
                "Thứ tự": order,
                "Trạng thái": str(rr[6]).strip() or "Đang dùng",
                "Bộ phận": dept,
                "Áp dụng nghỉ giữa ca": bool(_break_enabled),
                "Duration nghỉ giữa ca (phút)": int(_break_duration),
                "Khoảng gom FaceID (phút)": int(_faceid_cluster_minutes),
                "__row": ridx,
            })

    except Exception:
        loaded_ok = False

    if rows:
        return pd.DataFrame(rows, columns=columns).sort_values(
            ["Bộ phận", "Thứ tự", "Tên ca"],
            kind="stable",
        ).reset_index(drop=True)

    if loaded_ok:
        # Worksheet tồn tại và đã đọc thành công nhưng không còn ca:
        # trả rỗng, không được tự tạo lại ca mặc định.
        return pd.DataFrame(columns=columns)

    # Chỉ fallback khi Google Sheet thực sự không đọc được.
    fallback_rows = [
        {
            "ID": "SHIFT001", "Tên ca": "Ca 1",
            "Giờ bắt đầu": "10:00", "Giờ kết thúc": "23:00",
            "Ghi chú": "", "Thứ tự": 1, "Trạng thái": "Đang dùng",
            "Bộ phận": "Nhân viên + Leader",
            "Áp dụng nghỉ giữa ca": True,
            "Duration nghỉ giữa ca (phút)": 90,
            "Khoảng gom FaceID (phút)": 10,
            "__row": 0,
        },
        {
            "ID": "SHIFT002", "Tên ca": "Ca 2",
            "Giờ bắt đầu": "13:00", "Giờ kết thúc": "00:00",
            "Ghi chú": "", "Thứ tự": 2, "Trạng thái": "Đang dùng",
            "Bộ phận": "Nhân viên + Leader",
            "Áp dụng nghỉ giữa ca": True,
            "Duration nghỉ giữa ca (phút)": 90,
            "Khoảng gom FaceID (phút)": 10,
            "__row": 0,
        },
        {
            "ID": "SHIFT003", "Tên ca": "Cố định Ca 1",
            "Giờ bắt đầu": "", "Giờ kết thúc": "",
            "Ghi chú": "Không đổi", "Thứ tự": 3, "Trạng thái": "Đang dùng",
            "Bộ phận": "Nhân viên + Leader",
            "Áp dụng nghỉ giữa ca": True,
            "Duration nghỉ giữa ca (phút)": 90,
            "Khoảng gom FaceID (phút)": 10,
            "__row": 0,
        },
        {
            "ID": "SHIFT004", "Tên ca": "Cố định Ca 2",
            "Giờ bắt đầu": "", "Giờ kết thúc": "",
            "Ghi chú": "Không đổi", "Thứ tự": 4, "Trạng thái": "Đang dùng",
            "Bộ phận": "Nhân viên + Leader",
            "Áp dụng nghỉ giữa ca": True,
            "Duration nghỉ giữa ca (phút)": 90,
            "Khoảng gom FaceID (phút)": 10,
            "__row": 0,
        },
    ]
    return pd.DataFrame(fallback_rows, columns=columns)



def get_shift_options(department=None):
    """Danh mục ca riêng từng bộ phận."""
    d = load_shift_definitions()
    opts = []
    if isinstance(d, pd.DataFrame) and not d.empty:
        active = d[d["Trạng thái"].astype(str).str.strip().str.lower().ne("đã xóa")].copy()
        if department:
            active = active[active["Bộ phận"].astype(str).eq(str(department))].copy()
        for _, r in active.iterrows():
            label = _shift_display_label(
                r.get("Tên ca",""), r.get("Giờ bắt đầu",""), r.get("Giờ kết thúc","")
            )
            if (
                str(r.get("Ghi chú","")).strip().lower() == "không đổi"
                and "không đổi" not in label.lower()
            ):
                label = f"{label} (Không đổi)"
            if label and label not in opts:
                opts.append(label)

    # V92.6.11: nếu cấu hình đã đọc thành công và Admin xóa hết ca,
    # trả danh sách rỗng; không tự hồi sinh SHIFT001..SHIFT004.
    return opts


def get_shift_options_for_role(role):
    return get_shift_options(_shift_department_label(role))


def get_shift_options_all():
    """Union danh mục ca cho Export/template cũ."""
    out = []
    for dep in SHIFT_DEPARTMENT_ORDER:
        for item in get_shift_options(dep):
            if item not in out:
                out.append(item)
    return out or list(SHIFT_OPTIONS)



def _replace_shift_assignment(old_label, new_label):
    """Đổi tên ca trong cột O của Sheet tài khoản để không mất phân ca hiện tại."""
    old_label = str(old_label or "").strip()
    new_label = str(new_label or "").strip()
    if not old_label or old_label == new_label:
        return True, ""
    try:
        client = get_gspread_client()
        sheet = client.open_by_key(SHEET_MAT_KHAU_ID).get_worksheet(0)
        vals = _gs_call_with_backoff(sheet.get_all_values)
        out = []
        changed = 0
        for row in vals[1:]:
            current = row[14] if len(row) > 14 else ""
            if str(current).strip() == old_label:
                current = new_label
                changed += 1
            out.append([current])
        if out:
            gspread_update_range(sheet, f"O2:O{len(out)+1}", out, value_input_option="USER_ENTERED")
        return True, f"Đã cập nhật {changed} nhân viên đang dùng ca này."
    except Exception as e:
        return False, f"Lỗi cập nhật phân ca hiện tại: {e}"


def save_shift_definition(
    shift_id, name, start_time, end_time, note, order, username,
    department="Nhân viên + Leader",
    break_enabled=False,
    break_duration_minutes=60,
    new_shift_id=None,
    faceid_cluster_minutes=10,
):
    name = str(name or "").strip()
    department = str(department or "").strip()
    if department not in SHIFT_DEPARTMENT_ORDER:
        return False, "Bộ phận không hợp lệ."
    if not name:
        return False, "Tên ca không được để trống."
    try:
        ws = _get_shift_config_worksheet()
        if ws is None:
            return False, "Không mở được sheet cấu hình ca."
        defs = load_shift_definitions()
        shift_id = str(shift_id or "").strip()
        requested_shift_id = str(
            new_shift_id if new_shift_id is not None else shift_id
        ).strip()

        # Tạo mới mà chưa nhập ID -> hệ thống tự sinh.
        if not shift_id and not requested_shift_id:
            requested_shift_id = (
                "SHIFT-" + datetime.now(VN_TZ).strftime("%Y%m%d%H%M%S%f")
            )

        # ID chỉ cho phép chữ, số, "-", "_", "." để tránh lỗi khi dùng làm key.
        if not requested_shift_id:
            return False, "ID ca không được để trống."
        if not re.fullmatch(r"[A-Za-z0-9._-]+", requested_shift_id):
            return False, (
                "ID ca chỉ được dùng chữ, số và các ký tự . _ - "
                "(không dùng khoảng trắng/ký tự đặc biệt)."
            )

        # Không cho trùng ID với một CA ĐANG DÙNG khác.
        # Các dòng lịch sử "Đã xóa" không được khóa ID nữa.
        if isinstance(defs, pd.DataFrame) and not defs.empty:
            _active_defs_for_id = defs[
                defs["Trạng thái"].astype(str).str.strip().str.lower().ne("đã xóa")
            ].copy()
            _id_hit = _active_defs_for_id[
                _active_defs_for_id["ID"].astype(str).str.strip().eq(requested_shift_id)
            ].copy()
            if shift_id:
                _id_hit = _id_hit[
                    ~_id_hit["ID"].astype(str).str.strip().eq(shift_id)
                ]
            if not _id_hit.empty:
                return False, f"ID ca '{requested_shift_id}' đang được một ca khác sử dụng."

        row_idx = None
        old_label = ""
        old_department = department
        if shift_id and isinstance(defs, pd.DataFrame) and not defs.empty:
            hit = defs[defs["ID"].astype(str).eq(shift_id)]
            if not hit.empty:
                rr = hit.iloc[0]
                row_idx = int(rr.get("__row", 0) or 0)
                old_department = str(rr.get("Bộ phận", department))
                old_label = _shift_display_label(
                    rr["Tên ca"], rr["Giờ bắt đầu"], rr["Giờ kết thúc"]
                )
                if (
                    str(rr.get("Ghi chú","")).strip().lower() == "không đổi"
                    and "không đổi" not in old_label.lower()
                ):
                    old_label += " (Không đổi)"

        try:
            break_duration_minutes = max(
                1, min(600, int(float(break_duration_minutes)))
            )
        except Exception:
            break_duration_minutes = 60

        try:
            faceid_cluster_minutes = max(
                1, min(60, int(float(faceid_cluster_minutes)))
            )
        except Exception:
            faceid_cluster_minutes = 10

        row = [
            requested_shift_id, name, str(start_time or "").strip(), str(end_time or "").strip(),
            str(note or "").strip(), str(int(order or 999)), "Đang dùng", department,
            "1" if bool(break_enabled) else "0",
            str(int(break_duration_minutes)),
            str(int(faceid_cluster_minutes)),
        ]
        if row_idx:
            gspread_update_range(ws, f"A{row_idx}:K{row_idx}", [row])
        else:
            _gs_call_with_backoff(ws.append_row, row, value_input_option="USER_ENTERED")

        try:
            load_shift_definitions.clear()
        except Exception:
            pass

        new_label = _shift_display_label(name, start_time, end_time)
        if (
            str(note or "").strip().lower() == "không đổi"
            and "không đổi" not in new_label.lower()
        ):
            new_label += " (Không đổi)"

        # Chỉ đổi phân ca nhân viên nếu vẫn cùng bộ phận.
        _id_change_note = ""
        if shift_id and shift_id != requested_shift_id:
            _id_change_note = f" Đã đổi ID {shift_id} → {requested_shift_id}."

        if old_label and old_label != new_label and old_department == department:
            ok_replace, msg_replace = _replace_shift_assignment(old_label, new_label)
            _clear_dynamic_data_caches()
            if ok_replace:
                return True, ("Đã sửa ca." + _id_change_note + " " + msg_replace).strip()
            # Cấu hình ca đã lưu thành công; lỗi cập nhật phân ca chỉ là cảnh báo.
            return True, (
                "Đã sửa ca." + _id_change_note
                + " ⚠️ Cấu hình đã lưu nhưng chưa cập nhật được một số phân ca: "
                + str(msg_replace)
            ).strip()

        _clear_dynamic_data_caches()
        return True, (
            f"Đã lưu ca cho bộ phận {department}." + _id_change_note + " · "
            + (
                f"Nghỉ giữa ca {int(break_duration_minutes)} phút."
                if break_enabled else "Không áp dụng nghỉ giữa ca."
            )
        )
    except Exception as e:
        return False, f"Lỗi lưu ca: {e}"


def delete_shift_definition(shift_id, username):
    """
    V92.6.11 - XÓA THẬT ca theo ID khỏi CauHinhCaLamViec.
    Không chỉ đánh dấu "Đã xóa", vì cách cũ khiến SHIFT001/ca mặc định
    có thể còn tồn tại và bị hiểu là chưa xóa.
    """
    try:
        target_id = str(shift_id or "").strip()
        if not target_id:
            return False, "ID ca không hợp lệ."

        ws = _get_shift_config_worksheet()
        if ws is None:
            return False, "Không mở được sheet cấu hình ca."

        vals = _gs_call_with_backoff(ws.get_all_values)
        if not vals or len(vals) < 2:
            return False, f"Không tìm thấy ca ID {target_id}."

        matched = []
        for ridx, row in enumerate(vals[1:], start=2):
            row_id = str(row[0] if len(row) > 0 else "").strip()
            if row_id != target_id:
                continue

            name = str(row[1] if len(row) > 1 else "").strip()
            start_time = str(row[2] if len(row) > 2 else "").strip()
            end_time = str(row[3] if len(row) > 3 else "").strip()
            note = str(row[4] if len(row) > 4 else "").strip()
            department = (
                str(row[7] if len(row) > 7 else "").strip()
                or "Nhân viên + Leader"
            )

            label = _shift_display_label(name, start_time, end_time)
            if note.lower() == "không đổi" and "không đổi" not in label.lower():
                label += " (Không đổi)"

            matched.append({
                "row": ridx,
                "label": label,
                "department": department,
                "name": name,
            })

        if not matched:
            return False, f"Không tìm thấy ca ID {target_id} trong sheet cấu hình."

        # Gỡ ca khỏi hồ sơ nhân viên trước. Nếu lỗi vẫn tiếp tục xóa cấu hình,
        # nhưng trả cảnh báo rõ ràng.
        cleanup_messages = []
        cleanup_ok = True
        for item in matched:
            if item["label"]:
                ok_replace, msg_replace = _replace_shift_assignment(
                    item["label"], ""
                )
                cleanup_ok = cleanup_ok and bool(ok_replace)
                if msg_replace:
                    cleanup_messages.append(str(msg_replace))

        # Xóa vật lý từ dòng lớn xuống nhỏ để số dòng không bị dịch.
        deleted_count = 0
        for item in sorted(matched, key=lambda x: x["row"], reverse=True):
            _gs_call_with_backoff(ws.delete_rows, int(item["row"]))
            deleted_count += 1

        try:
            load_shift_definitions.clear()
        except Exception:
            pass

        _clear_dynamic_data_caches()

        # Xóa các seed/editor cũ để giao diện đọc lại đúng dữ liệu mới.
        for _k in [
            "shift_schedule_working_df",
            "shift_schedule_seed_signature",
        ]:
            try:
                st.session_state.pop(_k, None)
            except Exception:
                pass

        dep_text = ", ".join(
            dict.fromkeys(
                str(x.get("department", "")).strip()
                for x in matched
                if str(x.get("department", "")).strip()
            )
        )

        base_msg = (
            f"Đã xóa thật ca ID {target_id}"
            + (f" · {matched[0]['name']}" if matched[0].get("name") else "")
            + (f" · Bộ phận {dep_text}" if dep_text else "")
            + f". Đã xóa {deleted_count} dòng cấu hình."
        )

        if cleanup_ok:
            if cleanup_messages:
                base_msg += " " + " | ".join(dict.fromkeys(cleanup_messages))
            return True, base_msg

        return True, (
            base_msg
            + " ⚠️ Ca đã xóa khỏi danh mục, nhưng có lỗi khi gỡ ca khỏi một số hồ sơ nhân viên: "
            + " | ".join(dict.fromkeys(cleanup_messages))
        )

    except Exception as e:
        return False, f"Lỗi xóa ca ID {shift_id}: {e}"



@st.cache_resource(show_spinner=False)
def _get_shift_break_config_worksheet():
    try:
        client = get_gspread_client()
        if not client:
            return None
        ss = client.open_by_key(SHEET_MAT_KHAU_ID)
        ws = _get_or_create_worksheet(
            ss, SHIFT_BREAK_CONFIG_WORKSHEET, rows=100, cols=8
        )
        header = _gs_call_with_backoff(ws.row_values, 1)
        if header[:len(SHIFT_BREAK_CONFIG_HEADERS)] != SHIFT_BREAK_CONFIG_HEADERS:
            gspread_update_range(ws, "A1:F1", [SHIFT_BREAK_CONFIG_HEADERS])

        vals = _gs_call_with_backoff(ws.get_all_values)
        existing = {
            str(r[0]).strip()
            for r in vals[1:]
            if r and str(r[0]).strip()
        }
        for dep in SHIFT_DEPARTMENT_ORDER:
            if dep not in existing:
                d = SHIFT_BREAK_DEFAULTS[dep]
                _gs_call_with_backoff(
                    ws.append_row,
                    [
                        dep,
                        "1" if d["enabled"] else "0",
                        str(int(d["duration_minutes"])),
                        "", "", "Hệ thống"
                    ],
                    value_input_option="USER_ENTERED",
                )
        return ws
    except Exception:
        return None


@st.cache_data(ttl=300, show_spinner=False)
def load_shift_break_config():
    result = {
        dep: dict(SHIFT_BREAK_DEFAULTS[dep])
        for dep in SHIFT_DEPARTMENT_ORDER
    }
    try:
        ws = _get_shift_break_config_worksheet()
        if ws is None:
            return result
        vals = _gs_call_with_backoff(ws.get_all_values)
        for row in vals[1:]:
            if not row:
                continue
            dep = str(row[0]).strip()
            if dep not in result:
                continue
            enabled_raw = str(row[1] if len(row) > 1 else "").strip().lower()
            enabled = enabled_raw in {"1","true","yes","on","có","co","bật","bat"}
            try:
                duration = int(float(row[2])) if len(row) > 2 and str(row[2]).strip() else result[dep]["duration_minutes"]
            except Exception:
                duration = result[dep]["duration_minutes"]
            result[dep] = {
                "enabled": bool(enabled),
                "duration_minutes": max(1, min(600, int(duration))),
            }
    except Exception:
        pass
    return result


def save_shift_break_config(department, enabled, duration_minutes, username):
    department = str(department or "").strip()
    if department not in SHIFT_DEPARTMENT_ORDER:
        return False, "Bộ phận không hợp lệ."
    try:
        duration = max(1, min(600, int(float(duration_minutes))))
        ws = _get_shift_break_config_worksheet()
        if ws is None:
            return False, "Không mở được sheet cấu hình nghỉ giữa ca."

        vals = _gs_call_with_backoff(ws.get_all_values)
        row_idx = None
        for idx, row in enumerate(vals[1:], start=2):
            if row and str(row[0]).strip() == department:
                row_idx = idx
                break

        now = datetime.now(VN_TZ)
        row = [
            department,
            "1" if enabled else "0",
            str(duration),
            now.strftime("%d/%m/%Y"),
            now.strftime("%H:%M:%S"),
            str(username or ""),
        ]
        if row_idx:
            gspread_update_range(ws, f"A{row_idx}:F{row_idx}", [row])
        else:
            _gs_call_with_backoff(ws.append_row, row, value_input_option="USER_ENTERED")
        try:
            load_shift_break_config.clear()
        except Exception:
            pass
        return True, (
            f"Đã {'bật' if enabled else 'tắt'} nghỉ giữa ca cho {department}"
            + (f" · duration {duration} phút." if enabled else ".")
        )
    except Exception as e:
        return False, f"Lỗi lưu cấu hình nghỉ giữa ca: {e}"


@st.cache_resource(show_spinner=False)
def _get_midshift_deadline_config_worksheet():
    try:
        client = get_gspread_client()
        if not client:
            return None
        ss = client.open_by_key(SHEET_MAT_KHAU_ID)
        ws = _get_or_create_worksheet(
            ss,
            MIDSHIFT_DEADLINE_CONFIG_WORKSHEET,
            rows=20,
            cols=8,
        )
        return ws
    except Exception:
        return None


@st.cache_data(ttl=300, show_spinner=False)
def load_midshift_deadline_config():
    """
    Giới hạn chung toàn hệ thống:
    - Giờ phải quay lại mặc định 20:00.
    - Từ đủ 5 phút sau giờ giới hạn (20:05) -> Ra ngoài vào muộn.
    """
    default = {
        "return_deadline": MIDSHIFT_RETURN_DEADLINE_DEFAULT,
        "late_threshold_minutes": MIDSHIFT_LATE_THRESHOLD_DEFAULT,
        "updated_date": "",
        "updated_time": "",
        "updated_by": "",
    }

    try:
        ws = _get_midshift_deadline_config_worksheet()
        if ws is None:
            return default

        vals = _gs_call_with_backoff(ws.get_all_values)
        if not vals:
            gspread_update_range(
                ws, "A1:F1", [MIDSHIFT_DEADLINE_CONFIG_HEADERS]
            )
            now = datetime.now(VN_TZ)
            row = [
                MIDSHIFT_DEADLINE_CONFIG_KEY,
                MIDSHIFT_RETURN_DEADLINE_DEFAULT,
                str(MIDSHIFT_LATE_THRESHOLD_DEFAULT),
                now.strftime("%d/%m/%Y"),
                now.strftime("%H:%M:%S"),
                "Hệ thống",
            ]
            gspread_update_range(ws, "A2:F2", [row])
            vals = [MIDSHIFT_DEADLINE_CONFIG_HEADERS, row]
        else:
            if vals[0][:6] != MIDSHIFT_DEADLINE_CONFIG_HEADERS:
                gspread_update_range(
                    ws, "A1:F1", [MIDSHIFT_DEADLINE_CONFIG_HEADERS]
                )

        row = vals[1] if len(vals) > 1 else []
        row = list(row) + [""] * max(0, 6 - len(row))

        deadline = str(row[1] or MIDSHIFT_RETURN_DEADLINE_DEFAULT).strip()
        if not re.fullmatch(r"(?:[01]\d|2[0-3]):[0-5]\d", deadline):
            deadline = MIDSHIFT_RETURN_DEADLINE_DEFAULT

        try:
            threshold = int(float(row[2] or MIDSHIFT_LATE_THRESHOLD_DEFAULT))
        except Exception:
            threshold = MIDSHIFT_LATE_THRESHOLD_DEFAULT
        threshold = max(1, min(120, threshold))

        return {
            "return_deadline": deadline,
            "late_threshold_minutes": threshold,
            "updated_date": str(row[3] or ""),
            "updated_time": str(row[4] or ""),
            "updated_by": str(row[5] or ""),
        }
    except Exception:
        return default


def save_midshift_deadline_config(
    return_deadline,
    late_threshold_minutes,
    updated_by,
):
    try:
        deadline = str(return_deadline or "").strip()
        if not re.fullmatch(r"(?:[01]\d|2[0-3]):[0-5]\d", deadline):
            return False, "Giờ giới hạn phải theo định dạng HH:MM, ví dụ 20:00."

        try:
            threshold = max(
                1, min(120, int(float(late_threshold_minutes)))
            )
        except Exception:
            return False, "Ngưỡng vào muộn không hợp lệ."

        ws = _get_midshift_deadline_config_worksheet()
        if ws is None:
            return False, "Không mở được sheet cấu hình giờ nghỉ giữa ca."

        now = datetime.now(VN_TZ)
        row = [
            MIDSHIFT_DEADLINE_CONFIG_KEY,
            deadline,
            str(threshold),
            now.strftime("%d/%m/%Y"),
            now.strftime("%H:%M:%S"),
            str(updated_by or "Admin"),
        ]
        gspread_update_range(
            ws, "A1:F1", [MIDSHIFT_DEADLINE_CONFIG_HEADERS]
        )
        gspread_update_range(ws, "A2:F2", [row])

        try:
            load_midshift_deadline_config.clear()
        except Exception:
            pass

        return True, (
            f"Đã lưu: phải quay lại trước/đúng {deadline}; "
            f"từ đủ {threshold} phút sau giới hạn sẽ tính Ra ngoài vào muộn."
        )
    except Exception as e:
        return False, f"Lỗi lưu cấu hình giới hạn nghỉ giữa ca: {e}"


def _midshift_deadline_datetime(work_date, deadline_text):
    try:
        hh, mm = [int(x) for x in str(deadline_text).split(":", 1)]
        return datetime(
            work_date.year, work_date.month, work_date.day,
            hh, mm, 0, tzinfo=VN_TZ
        )
    except Exception:
        return datetime(
            work_date.year, work_date.month, work_date.day,
            20, 0, 0, tzinfo=VN_TZ
        )


def get_shift_break_config_for_role(role):
    dep = _shift_department_label(role)
    return load_shift_break_config().get(
        dep, {"enabled": False, "duration_minutes": 60}
    )


def _extract_timesoft_punch_times_from_row(row):
    """
    V92.6.13 - lấy các mốc CHẤM MẶT thực tế từ một row TimeSoft.

    Không lấy StartWorkTime / EndWorkTime / WorkTimeName vì đó là giờ ca quy định,
    không phải mốc FaceID thực tế.
    """
    values = []

    def _is_punch_column(column_name):
        raw = str(column_name or "")
        key = normalize_login_name(raw).replace(" ", "")

        # Loại các field lịch/ca/tổng hợp dễ gây nhận nhầm.
        excluded = (
            "startworktime", "endworktime", "worktimename", "worktime",
            "totalminute", "duration", "schedule", "shift",
            "created", "updated", "modify", "server",
        )
        if any(x in key for x in excluded):
            return False

        positive = (
            "checkin", "checkout", "machine", "punch", "attendance",
            "scan", "face", "chamcong", "checktime", "logtime",
        )
        if any(x in key for x in positive):
            return True

        # Một số API detail chỉ đặt tên field là Time/Timestamp.
        return key in {"time", "timestamp", "datetime"}

    candidate_cols = [c for c in row.index if _is_punch_column(c)]

    def add_from_value(v):
        if v is None:
            return
        if isinstance(v, (list, tuple, set)):
            for x in v:
                add_from_value(x)
            return
        if isinstance(v, dict):
            for x in v.values():
                add_from_value(x)
            return

        s = str(v).strip()
        if not s or s.casefold() in {"nan", "none", "nat", "0"}:
            return

        full = re.findall(
            r'(\d{1,2}[/-]\d{1,2}[/-]\d{2,4}\s+\d{1,2}:\d{2}(?::\d{2})?)',
            s,
        )
        if full:
            values.extend(full)
            return

        times = re.findall(
            r'(?<!\d)(\d{1,2}:\d{2}(?::\d{2})?)(?!\d)',
            s,
        )
        values.extend(times)

    for c in candidate_cols:
        add_from_value(row.get(c))

    parsed = []
    seen = set()
    base_date = get_vn_today()
    date_raw = _timesoft_row_value(
        row, ["WorkDateStr", "WorkDate", "Date", "AttendanceDate"]
    )
    try:
        d = pd.to_datetime(date_raw, dayfirst=True, errors="coerce")
        if not pd.isna(d):
            base_date = d.date()
    except Exception:
        pass

    for item in values:
        item = str(item).strip()
        dt = None
        for fmt in (
            "%d/%m/%Y %H:%M:%S", "%d/%m/%Y %H:%M",
            "%d-%m-%Y %H:%M:%S", "%d-%m-%Y %H:%M",
        ):
            try:
                dt = datetime.strptime(item, fmt).replace(tzinfo=VN_TZ)
                break
            except Exception:
                pass

        if dt is None:
            m = re.fullmatch(r"(\d{1,2}):(\d{2})(?::(\d{2}))?", item)
            if m:
                try:
                    dt = datetime(
                        base_date.year, base_date.month, base_date.day,
                        int(m.group(1)), int(m.group(2)), int(m.group(3) or 0),
                        tzinfo=VN_TZ,
                    )
                except Exception:
                    dt = None

        if dt is not None:
            key = dt.isoformat()
            if key not in seen:
                seen.add(key)
                parsed.append(dt)

    parsed.sort()
    return parsed


def _timesoft_work_date_from_row(row, punches=None):
    raw = _timesoft_row_value(
        row, ["WorkDateStr", "WorkDate", "Date", "AttendanceDate"]
    )
    try:
        dt = pd.to_datetime(raw, dayfirst=True, errors="coerce")
        if not pd.isna(dt):
            return dt.date()
    except Exception:
        pass

    if punches:
        try:
            return punches[0].date()
        except Exception:
            pass
    return get_vn_today()


def _cluster_faceid_punches(punches, cluster_minutes=10):
    """
    Gom các lần chấm trong cùng cửa sổ thành 1 sự kiện FaceID.

    Quan trọng: cửa sổ được tính từ LẦN ĐẦU của cụm, không nối dây chuyền.
    Ví dụ 10:00, 10:09, 10:18 với cửa sổ 10 phút:
      cụm 1 = 10:00 + 10:09
      cụm 2 = 10:18
    """
    try:
        window = max(1, min(60, int(float(cluster_minutes))))
    except Exception:
        window = 10

    punches = sorted(
        [p for p in punches if isinstance(p, datetime)]
    )
    if not punches:
        return []

    clusters = []
    current = [punches[0]]
    anchor = punches[0]

    for punch in punches[1:]:
        if punch <= anchor + timedelta(minutes=window):
            current.append(punch)
        else:
            clusters.append({
                "start": current[0],
                "end": current[-1],
                "count": len(current),
                "punches": list(current),
            })
            current = [punch]
            anchor = punch

    clusters.append({
        "start": current[0],
        "end": current[-1],
        "count": len(current),
        "punches": list(current),
    })
    return clusters


def _pick_midshift_break_pair(clusters, allowed_minutes, cluster_minutes=10):
    """
    Cụm đầu tiên = vào ca.
    Không dùng cụm cuối làm check-out vì VERA hầu như không check mặt khi về.

    Nếu chỉ có đúng 3 cụm:
      cụm 2 -> cụm 3 = nghỉ giữa ca.

    Nếu có >3 cụm (ví dụ chấm nhầm giữa ngày):
      xét các CẶP CỤM LIỀN KỀ sau cụm vào ca và chọn khoảng thời gian
      gần Duration quy định nhất.
    """
    if len(clusters) < 3:
        return None

    allowed = max(1, int(allowed_minutes or 1))
    remaining = clusters[1:]

    if len(remaining) == 2:
        start_cluster = remaining[0]
        end_cluster = remaining[1]
        actual = max(
            0,
            int(round(
                (end_cluster["start"] - start_cluster["start"]).total_seconds()
                / 60.0
            )),
        )
        return {
            "start_cluster": start_cluster,
            "end_cluster": end_cluster,
            "actual_minutes": actual,
            "start_index": 2,
            "end_index": 3,
            "method": "Cụm 2 → 3",
        }

    candidates = []
    min_reasonable = max(
        int(cluster_minutes) + 1,
        min(30, max(15, int(round(allowed * 0.25)))),
    )

    for i in range(len(remaining) - 1):
        c1 = remaining[i]
        c2 = remaining[i + 1]
        gap = int(round(
            (c2["start"] - c1["start"]).total_seconds() / 60.0
        ))
        if gap < 0:
            continue

        # Khoảng quá sát thường chỉ là chấm dư bị tách cụm.
        too_short_penalty = 10000 if gap < min_reasonable else 0
        score = abs(gap - allowed) + too_short_penalty

        candidates.append({
            "start_cluster": c1,
            "end_cluster": c2,
            "actual_minutes": gap,
            "start_index": i + 2,
            "end_index": i + 3,
            "score": score,
        })

    if not candidates:
        return None

    best = min(
        candidates,
        key=lambda x: (
            x["score"],
            abs(x["actual_minutes"] - allowed),
            x["start_index"],
        ),
    )
    best["method"] = (
        f"Tự chọn cụm {best['start_index']} → {best['end_index']} "
        f"gần {allowed} phút nhất"
    )
    return best


def get_shift_break_setting_for_employee(employee_name, credentials_df=None):
    """
    Lấy cấu hình nghỉ giữa ca từ CHÍNH ca nhân viên đang được phân.
    Fallback về cấu hình bộ phận nếu ca cũ chưa match được.
    """
    role = ""
    assigned_shift = ""
    if isinstance(credentials_df, pd.DataFrame) and not credentials_df.empty:
        names = credentials_df["Tên nhân viên"].astype(str).apply(normalize_login_name)
        hit = credentials_df[names.eq(normalize_login_name(employee_name))]
        if not hit.empty:
            rr = hit.iloc[0]
            role = str(rr.get("Phân quyền", ""))
            assigned_shift = str(rr.get("Ca làm việc", "")).strip()

    dep = _shift_department_label(role)
    defs = load_shift_definitions()
    if (
        assigned_shift
        and isinstance(defs, pd.DataFrame)
        and not defs.empty
    ):
        active = defs[
            defs["Bộ phận"].astype(str).eq(dep)
            & defs["Trạng thái"].astype(str).str.lower().ne("đã xóa")
        ]
        for _, rr in active.iterrows():
            label = _shift_display_label(
                rr.get("Tên ca", ""),
                rr.get("Giờ bắt đầu", ""),
                rr.get("Giờ kết thúc", ""),
            )
            if (
                str(rr.get("Ghi chú", "")).strip().lower() == "không đổi"
                and "không đổi" not in label.lower()
            ):
                label += " (Không đổi)"
            if str(label).strip() == assigned_shift:
                return {
                    "department": dep,
                    "shift": label,
                    "enabled": bool(rr.get("Áp dụng nghỉ giữa ca", False)),
                    "duration_minutes": int(
                        rr.get("Duration nghỉ giữa ca (phút)", 60) or 60
                    ),
                    "faceid_cluster_minutes": int(
                        rr.get("Khoảng gom FaceID (phút)", 10) or 10
                    ),
                    "source": "shift",
                }

    fallback = load_shift_break_config().get(
        dep, {"enabled": False, "duration_minutes": 60}
    )
    return {
        "department": dep,
        "shift": assigned_shift,
        "enabled": bool(fallback.get("enabled", False)),
        "duration_minutes": int(fallback.get("duration_minutes", 60)),
        "faceid_cluster_minutes": 10,
        "source": "department_fallback",
    }


def calculate_midshift_break_from_timesoft(checkin_df, credentials_df=None):
    """
    V92.6.14 - Nghỉ giữa ca là PHÁT SINH THEO TỪNG NGÀY / TỪNG NGƯỜI.

    Quy tắc:
    - 1 cụm FaceID: không ghi nhận nghỉ giữa ca -> KHÔNG phạt.
    - 2 cụm FaceID: chưa đủ dữ liệu để kết luận nghỉ -> KHÔNG tự phạt.
    - >=3 cụm: xác định cặp bắt đầu/kết thúc nghỉ.
    - Duration thực tế <= Duration quy định là đạt về thời lượng.
    - Ngoài Duration, có GIỜ QUAY LẠI CUỐI CÙNG toàn hệ thống.
      Mặc định 20:00; ngưỡng vào muộn mặc định 5 phút.
      Vì vậy từ 20:05 trở đi = "Ra ngoài vào muộn", kể cả nghỉ chưa đủ 90 phút.
    - Không sử dụng check-out cuối ngày.
    """
    cols = [
        "Ngày", "Tên nhân viên", "Bộ phận", "Ca làm việc",
        "Có nghỉ giữa ca", "FaceID thô", "Số cụm FaceID",
        "Khoảng gom (phút)", "Vào ca", "Bắt đầu nghỉ", "Kết thúc nghỉ",
        "Duration quy định", "Duration thực tế", "Chênh lệch Duration",
        "Giờ phải quay lại", "Ngưỡng vào muộn (phút)", "Phút vào muộn",
        "Loại vi phạm", "Cách xác định", "Chi tiết cụm", "Trạng thái",
    ]
    if not isinstance(checkin_df, pd.DataFrame) or checkin_df.empty:
        return pd.DataFrame(columns=cols)

    cred_role = {}
    if (
        isinstance(credentials_df, pd.DataFrame)
        and not credentials_df.empty
        and "Tên nhân viên" in credentials_df.columns
        and "Phân quyền" in credentials_df.columns
    ):
        for _, r in credentials_df.iterrows():
            cred_role[normalize_login_name(r.get("Tên nhân viên", ""))] = str(
                r.get("Phân quyền", "")
            )

    deadline_cfg = load_midshift_deadline_config()
    deadline_text = str(
        deadline_cfg.get(
            "return_deadline",
            MIDSHIFT_RETURN_DEADLINE_DEFAULT,
        )
    )
    late_threshold = int(
        deadline_cfg.get(
            "late_threshold_minutes",
            MIDSHIFT_LATE_THRESHOLD_DEFAULT,
        )
        or MIDSHIFT_LATE_THRESHOLD_DEFAULT
    )

    # Gộp nhiều row TimeSoft theo cùng Nhân viên + Ngày.
    grouped = {}
    for _, row in checkin_df.iterrows():
        name = _timesoft_row_value(
            row,
            [
                "employeeInfo.Name", "EmployeeName",
                "Tên nhân viên", "Nhân viên", "Name",
            ],
        )
        name = str(name or "").strip()
        if not name:
            continue

        punches = _extract_timesoft_punch_times_from_row(row)
        work_date = _timesoft_work_date_from_row(row, punches)
        key = (normalize_login_name(name), work_date.isoformat())

        if key not in grouped:
            grouped[key] = {
                "name": name,
                "work_date": work_date,
                "punches": [],
            }
        grouped[key]["punches"].extend(punches)

    out = []
    for _, item in grouped.items():
        name = item["name"]
        work_date = item["work_date"]

        unique = {}
        for p in item["punches"]:
            if isinstance(p, datetime):
                unique[p.isoformat()] = p
        punches = sorted(unique.values())

        role = cred_role.get(normalize_login_name(name), "")
        dep = _shift_department_label(role)
        cfg = get_shift_break_setting_for_employee(name, credentials_df)

        # Ca không áp dụng nghỉ giữa ca: không cần đánh giá.
        if not cfg.get("enabled", False):
            continue

        allowed = int(cfg.get("duration_minutes", 60) or 60)
        cluster_minutes = int(
            cfg.get("faceid_cluster_minutes", 10) or 10
        )
        clusters = _cluster_faceid_punches(
            punches, cluster_minutes=cluster_minutes
        )

        cluster_detail = " · ".join(
            f"{c['start'].strftime('%H:%M:%S')}({c['count']})"
            for c in clusters
        )
        entry = clusters[0]["start"] if clusters else None

        base_row = {
            "Ngày": work_date.strftime("%d/%m/%Y"),
            "Tên nhân viên": name,
            "Bộ phận": dep,
            "Ca làm việc": str(cfg.get("shift", "")),
            "FaceID thô": len(punches),
            "Số cụm FaceID": len(clusters),
            "Khoảng gom (phút)": cluster_minutes,
            "Vào ca": entry.strftime("%H:%M:%S") if entry else "",
            "Duration quy định": allowed,
            "Giờ phải quay lại": deadline_text,
            "Ngưỡng vào muộn (phút)": late_threshold,
            "Chi tiết cụm": cluster_detail,
        }

        # 0-1 cụm: coi là ngày không ghi nhận nghỉ giữa ca.
        if len(clusters) <= 1:
            out.append({
                **base_row,
                "Có nghỉ giữa ca": "Không",
                "Bắt đầu nghỉ": "",
                "Kết thúc nghỉ": "",
                "Duration thực tế": "",
                "Chênh lệch Duration": "",
                "Phút vào muộn": "",
                "Loại vi phạm": "",
                "Cách xác định": "",
                "Trạng thái": "Không ghi nhận nghỉ giữa ca",
            })
            continue

        # 2 cụm: không đủ bằng chứng để biết có phải ra nghỉ hay chỉ chấm dư.
        if len(clusters) == 2:
            out.append({
                **base_row,
                "Có nghỉ giữa ca": "Chưa xác định",
                "Bắt đầu nghỉ": clusters[1]["start"].strftime("%H:%M:%S"),
                "Kết thúc nghỉ": "",
                "Duration thực tế": "",
                "Chênh lệch Duration": "",
                "Phút vào muộn": "",
                "Loại vi phạm": "",
                "Cách xác định": "Mới có 2 cụm FaceID",
                "Trạng thái": "Chưa đủ dữ liệu xác định nghỉ giữa ca",
            })
            continue

        pair = _pick_midshift_break_pair(
            clusters,
            allowed_minutes=allowed,
            cluster_minutes=cluster_minutes,
        )
        if not pair:
            out.append({
                **base_row,
                "Có nghỉ giữa ca": "Chưa xác định",
                "Bắt đầu nghỉ": "",
                "Kết thúc nghỉ": "",
                "Duration thực tế": "",
                "Chênh lệch Duration": "",
                "Phút vào muộn": "",
                "Loại vi phạm": "",
                "Cách xác định": "",
                "Trạng thái": "Không xác định được cặp nghỉ",
            })
            continue

        p2 = pair["start_cluster"]["start"]
        p3 = pair["end_cluster"]["start"]
        actual = int(pair["actual_minutes"])
        duration_diff = actual - allowed

        deadline_dt = _midshift_deadline_datetime(
            work_date, deadline_text
        )
        late_seconds = max(
            0.0,
            (p3 - deadline_dt).total_seconds(),
        )
        late_minutes = int(late_seconds // 60)

        is_outside_late = (
            late_seconds >= late_threshold * 60
        )

        if is_outside_late:
            violation = "Ra ngoài vào muộn"
            status = f"🔴 Ra ngoài vào muộn {late_minutes} phút"
        elif duration_diff > 0:
            violation = "Nghỉ giữa ca quá thời gian"
            status = f"❌ Nghỉ quá {duration_diff} phút"
        else:
            violation = ""
            status = "✅ Đúng quy định"

        out.append({
            **base_row,
            "Có nghỉ giữa ca": "Có",
            "Bắt đầu nghỉ": p2.strftime("%H:%M:%S"),
            "Kết thúc nghỉ": p3.strftime("%H:%M:%S"),
            "Duration thực tế": actual,
            "Chênh lệch Duration": duration_diff,
            "Phút vào muộn": late_minutes if is_outside_late else 0,
            "Loại vi phạm": violation,
            "Cách xác định": pair.get("method", ""),
            "Trạng thái": status,
        })

    return pd.DataFrame(out, columns=cols)



def get_shift_dataframe(credentials_df):
    """Hiển thị các bộ phận; leader + nhanvien được gom chung một nhóm."""
    cols = ['Tên nhân viên', 'Bộ phận', 'Phân quyền', 'Ca làm việc', 'Ngày bắt đầu ca', 'Chu kỳ']
    if credentials_df is None or credentials_df.empty:
        return pd.DataFrame(columns=cols)
    d = credentials_df.copy()
    for c in ['Tên nhân viên', 'Phân quyền', 'Ca làm việc', 'Ngày bắt đầu ca', 'Chu kỳ']:
        if c not in d.columns:
            d[c] = ''
    roles = {"nhanvien", "leader", "letan", "quanly", "locker", "tapvu"}
    d = d[d['Phân quyền'].astype(str).str.strip().str.lower().isin(roles)].copy()
    d['Bộ phận'] = d['Phân quyền'].apply(_shift_department_label)
    d = d[cols].copy()

    # V92.6.8 - chuẩn hóa dữ liệu ca từ hồ sơ.
    # Không để None/nan làm SelectboxColumn hiểu thành giá trị không hợp lệ.
    for _shift_col in ["Ca làm việc", "Ngày bắt đầu ca", "Chu kỳ"]:
        if _shift_col in d.columns:
            d[_shift_col] = (
                d[_shift_col]
                .fillna("")
                .astype(str)
                .replace({"None": "", "none": "", "nan": "", "NaN": "", "<NA>": ""})
                .str.strip()
            )

    if not d.empty:
        dept_rank = {v:i for i,v in enumerate(SHIFT_DEPARTMENT_ORDER)}
        d['_dept'] = d['Bộ phận'].map(dept_rank).fillna(999)
        d['_sort'] = d['Tên nhân viên'].astype(str).apply(normalize_login_name)
        d = d.sort_values(['_dept','_sort'], kind='stable').drop(columns=['_dept','_sort']).reset_index(drop=True)
    return d


def get_nhanvien_shift_dataframe(credentials_df):
    """Alias tương thích code cũ; V91.2 trả toàn bộ nhóm bộ phận được phép."""
    return get_shift_dataframe(credentials_df)


def _shift_pdf_font_setup():
    """
    Đăng ký font Unicode cho PDF tiếng Việt.

    V92.6.21:
    - Ưu tiên font hệ thống DejaVu/Noto/Roboto/Liberation/Arial.
    - Nếu Docker image không cài font hệ thống, tự tìm DejaVu Sans đi kèm
      package matplotlib (nếu matplotlib có trong requirements).
    - Không đóng gói/chia sẻ file font riêng trong ứng dụng.
    """
    try:
        from reportlab.pdfbase import pdfmetrics
        from reportlab.pdfbase.ttfonts import TTFont
    except Exception:
        return None, None, (
            "Thiếu thư viện reportlab. Hãy thêm `reportlab>=4.0` vào requirements.txt "
            "rồi build/deploy lại."
        )

    regular_candidates = [
        "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
        "/usr/share/fonts/dejavu/DejaVuSans.ttf",
        "/usr/share/fonts/truetype/noto/NotoSans-Regular.ttf",
        "/usr/share/fonts/opentype/noto/NotoSans-Regular.ttf",
        "/usr/share/fonts/truetype/roboto/unhinted/RobotoTTF/Roboto-Regular.ttf",
        "/usr/share/fonts/truetype/roboto/Roboto-Regular.ttf",
        "/usr/share/fonts/truetype/liberation/LiberationSans-Regular.ttf",
        "/usr/share/fonts/truetype/liberation2/LiberationSans-Regular.ttf",
        "/usr/share/fonts/truetype/open-sans/OpenSans-Regular.ttf",
        "/usr/local/share/fonts/DejaVuSans.ttf",
        "C:/Windows/Fonts/arial.ttf",
    ]
    bold_candidates = [
        "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
        "/usr/share/fonts/dejavu/DejaVuSans-Bold.ttf",
        "/usr/share/fonts/truetype/noto/NotoSans-Bold.ttf",
        "/usr/share/fonts/opentype/noto/NotoSans-Bold.ttf",
        "/usr/share/fonts/truetype/roboto/unhinted/RobotoTTF/Roboto-Bold.ttf",
        "/usr/share/fonts/truetype/roboto/Roboto-Bold.ttf",
        "/usr/share/fonts/truetype/liberation/LiberationSans-Bold.ttf",
        "/usr/share/fonts/truetype/liberation2/LiberationSans-Bold.ttf",
        "/usr/share/fonts/truetype/open-sans/OpenSans-Bold.ttf",
        "/usr/local/share/fonts/DejaVuSans-Bold.ttf",
        "C:/Windows/Fonts/arialbd.ttf",
    ]

    regular_path = next((p for p in regular_candidates if os.path.exists(p)), None)
    bold_path = next((p for p in bold_candidates if os.path.exists(p)), None)

    # Fallback không cần apt font: dùng DejaVu Sans đi kèm matplotlib.
    if not regular_path:
        try:
            from matplotlib import font_manager
            mpl_regular = font_manager.findfont(
                "DejaVu Sans", fallback_to_default=False
            )
            if mpl_regular and os.path.exists(mpl_regular):
                regular_path = mpl_regular
            try:
                prop = font_manager.FontProperties(
                    family="DejaVu Sans", weight="bold"
                )
                mpl_bold = font_manager.findfont(
                    prop, fallback_to_default=False
                )
                if mpl_bold and os.path.exists(mpl_bold):
                    bold_path = mpl_bold
            except Exception:
                pass
        except Exception:
            pass

    if not regular_path:
        return None, None, (
            "Máy chủ chưa có font Unicode để xuất PDF tiếng Việt. "
            "Cách nhanh nhất: thêm `matplotlib>=3.8` vào requirements.txt; "
            "hoặc cài `fonts-dejavu-core` trong Docker image rồi build/deploy lại."
        )

    try:
        regular_name = "VeraShiftPDF-Regular"
        bold_name = "VeraShiftPDF-Bold"
        if regular_name not in pdfmetrics.getRegisteredFontNames():
            pdfmetrics.registerFont(TTFont(regular_name, regular_path))
        if bold_path:
            if bold_name not in pdfmetrics.getRegisteredFontNames():
                pdfmetrics.registerFont(TTFont(bold_name, bold_path))
        else:
            bold_name = regular_name
        return regular_name, bold_name, ""
    except Exception as e:
        return None, None, f"Không đăng ký được font PDF Unicode: {e}"


def _shift_pdf_group(shift_value, cycle_value=""):
    """Phân nhóm đúng 4 ô của mẫu: Ca1, Ca2, Cố định Ca1, Cố định Ca2."""
    shift_text = str(shift_value or "").strip()
    cycle_text = str(cycle_value or "").strip()
    key = normalize_login_name(f"{shift_text} {cycle_text}")
    base = _shift_base_number(shift_text)
    is_fixed = ("co dinh" in key) or ("khong doi" in key)
    if base == 1:
        return "fixed1" if is_fixed else "ca1"
    if base == 2:
        return "fixed2" if is_fixed else "ca2"
    return "other"


def _shift_pdf_heading(rows, fallback):
    vals = []
    if isinstance(rows, pd.DataFrame) and not rows.empty and "Ca làm việc" in rows.columns:
        vals = [
            str(v).strip()
            for v in rows["Ca làm việc"].tolist()
            if str(v).strip() and str(v).strip().lower() not in {"nan", "none", "<na>"}
        ]
    vals = list(dict.fromkeys(vals))
    if len(vals) == 1:
        return vals[0]
    return fallback


def _shift_pdf_phone_map(credentials_df):
    result = {}
    if not isinstance(credentials_df, pd.DataFrame) or credentials_df.empty:
        return result
    phone_col = None
    for c in ["Điện thoại", "SĐT", "Số điện thoại", "Phone"]:
        if c in credentials_df.columns:
            phone_col = c
            break
    if not phone_col or "Tên nhân viên" not in credentials_df.columns:
        return result
    for _, r in credentials_df.iterrows():
        key = normalize_login_name(r.get("Tên nhân viên", ""))
        if key:
            result[key] = str(r.get(phone_col, "") or "").strip()
    return result


def build_shift_assignment_duplex_pdf_bytes(shift_df, credentials_df, print_date=None):
    """
    V92.6.21 - PDF phân ca Nhân viên + Leader, A4 ngang, in 2 mặt.

    Bố cục MẶT 1 và MẶT 2 GIỐNG HỆT NHAU để in duplex gióng đúng vị trí:
      1) Ca 1
      2) Ca 2
      3) Chung = Cố định Ca 1 + Cố định Ca 2

    - 19 dòng/bảng.
    - Nếu nhóm nào vượt 19 người, tự sinh thêm một CẶP mặt trước/mặt sau.
    - Mặt 2 dùng cùng tọa độ, kích thước, thứ tự và dữ liệu như Mặt 1.
    - Cột E của PDF không liên quan schema lịch nghỉ; đây chỉ là mẫu thẻ phân ca.
    """
    try:
        from reportlab.lib import colors
        from reportlab.lib.pagesizes import A4, landscape
        from reportlab.lib.units import mm
        from reportlab.pdfgen import canvas
        from reportlab.platypus import Table, TableStyle
    except Exception:
        return b"", (
            "Thiếu thư viện reportlab. Hãy thêm `reportlab>=4.0` vào requirements.txt "
            "rồi build/deploy lại."
        )

    font_regular, font_bold, font_err = _shift_pdf_font_setup()
    if font_err:
        return b"", font_err

    if not isinstance(shift_df, pd.DataFrame):
        shift_df = pd.DataFrame()
    d = shift_df.copy()

    # Chỉ lấy Nhân viên + Leader.
    if "Bộ phận" in d.columns:
        d = d[d["Bộ phận"].astype(str).eq("Nhân viên + Leader")].copy()
    elif "Phân quyền" in d.columns:
        d = d[
            d["Phân quyền"].astype(str).str.strip().str.lower().isin({"nhanvien", "leader"})
        ].copy()

    for c in ["Tên nhân viên", "Ca làm việc", "Chu kỳ"]:
        if c not in d.columns:
            d[c] = ""

    phone_map = _shift_pdf_phone_map(credentials_df)
    d["SĐT"] = d["Tên nhân viên"].astype(str).apply(
        lambda x: phone_map.get(normalize_login_name(x), "")
    )
    d = d[d["Tên nhân viên"].astype(str).str.strip().ne("")].copy()
    d["_group"] = d.apply(
        lambda r: _shift_pdf_group(r.get("Ca làm việc", ""), r.get("Chu kỳ", "")),
        axis=1,
    )
    d["_sort"] = d["Tên nhân viên"].astype(str).apply(normalize_login_name)
    d = d.sort_values(["_group", "_sort"], kind="stable").reset_index(drop=True)

    ca1 = d[d["_group"].eq("ca1")].copy().sort_values("_sort", kind="stable")
    ca2 = d[d["_group"].eq("ca2")].copy().sort_values("_sort", kind="stable")
    fixed1 = d[d["_group"].eq("fixed1")].copy().sort_values("_sort", kind="stable")
    fixed2 = d[d["_group"].eq("fixed2")].copy().sort_values("_sort", kind="stable")
    common = pd.concat([fixed1, fixed2], ignore_index=True, sort=False)
    other = d[d["_group"].eq("other")].copy()

    groups = {"ca1": ca1, "ca2": ca2, "common": common}

    rows_per_table = 19
    max_rows = max([len(x) for x in groups.values()] + [1])
    card_sets = max(1, int(math.ceil(max_rows / rows_per_table)))

    print_date = print_date or get_vn_today()
    try:
        if isinstance(print_date, datetime):
            print_date = print_date.date()
    except Exception:
        pass
    if not isinstance(print_date, date):
        try:
            parsed = pd.to_datetime(print_date, dayfirst=True, errors="coerce")
            print_date = parsed.date() if pd.notna(parsed) else get_vn_today()
        except Exception:
            print_date = get_vn_today()

    out = io.BytesIO()
    page_w, page_h = landscape(A4)
    pdf = canvas.Canvas(out, pagesize=(page_w, page_h), pageCompression=1)

    # 3 bảng song song, Fit A4 ngang.
    margin_x = 4.5 * mm
    top_y = page_h - 6 * mm
    gap = 2.5 * mm
    usable_w = page_w - 2 * margin_x
    table_w = (usable_w - 2 * gap) / 3.0

    title_h = 10 * mm
    section_y = top_y - title_h
    table_y_top = section_y - 6.5 * mm
    header_h = 8.0 * mm
    row_h = 7.2 * mm
    table_h = header_h + rows_per_table * row_h
    table_y = table_y_top - table_h

    # Tối ưu tỷ lệ cho 3 bảng trên cùng A4.
    weights = [0.075, 0.255, 0.175, 0.155, 0.10, 0.145, 0.095]
    col_widths = [table_w * w / sum(weights) for w in weights]
    headers = ["STT", "Tên Nhân Viên", "SĐT", "Giờ vào Ca", "Ký tên", "Giờ vào ra", "Ký tên"]

    def slice_group(gdf, batch_index):
        start = batch_index * rows_per_table
        end = start + rows_per_table
        return gdf.iloc[start:end].copy()

    def page_heading(side_label, batch_index):
        pdf.setFont(font_bold, 12)
        pdf.drawString(margin_x, top_y, "LỊCH LÀM VIỆC KTV")
        pdf.setFont(font_regular, 6.6)
        pdf.drawCentredString(page_w / 2, top_y + 0.2 * mm, f"{len(d)} Nhân viên")
        pdf.drawRightString(
            page_w - margin_x,
            top_y + 0.2 * mm,
            f"Ngày: {print_date.strftime('%d/%m/%Y')}",
        )
        pdf.setFont(font_regular, 4.8)
        pdf.drawRightString(
            page_w - margin_x,
            3.2 * mm,
            f"{side_label} - Bộ {batch_index + 1}/{card_sets} - A4 ngang - duplex gióng cùng tọa độ",
        )

    def table_data(gdf):
        data = [headers]
        for i in range(rows_per_table):
            if i < len(gdf):
                r = gdf.iloc[i]
                data.append([
                    str(i + 1),
                    str(r.get("Tên nhân viên", "") or "").strip(),
                    str(r.get("SĐT", "") or "").strip(),
                    "", "", "", "",
                ])
            else:
                data.append([str(i + 1), "", "", "", "", "", ""])
        return data

    def draw_shift_table(gdf, x, heading):
        pdf.setFont(font_bold, 6.4)
        pdf.drawString(x, section_y, str(heading or "").strip())
        tbl = Table(
            table_data(gdf),
            colWidths=col_widths,
            rowHeights=[header_h] + [row_h] * rows_per_table,
            repeatRows=1,
        )
        tbl.setStyle(TableStyle([
            ("FONTNAME", (0, 0), (-1, -1), font_regular),
            ("FONTNAME", (0, 0), (-1, 0), font_bold),
            ("FONTSIZE", (0, 0), (-1, 0), 4.25),
            ("FONTSIZE", (0, 1), (-1, -1), 4.55),
            ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#D9D9D9")),
            ("TEXTCOLOR", (0, 0), (-1, -1), colors.black),
            ("ALIGN", (0, 0), (0, -1), "CENTER"),
            ("ALIGN", (2, 0), (-1, -1), "CENTER"),
            ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
            ("LEFTPADDING", (0, 0), (-1, -1), 0.8),
            ("RIGHTPADDING", (0, 0), (-1, -1), 0.8),
            ("TOPPADDING", (0, 0), (-1, -1), 0.7),
            ("BOTTOMPADDING", (0, 0), (-1, -1), 0.7),
            ("GRID", (0, 0), (-1, -1), 0.45, colors.black),
        ]))
        tbl.wrapOn(pdf, table_w, table_h)
        tbl.drawOn(pdf, x, table_y)

    def draw_same_layout(side_label, batch_index):
        page_heading(side_label, batch_index)
        g1 = slice_group(ca1, batch_index)
        g2 = slice_group(ca2, batch_index)
        gc = slice_group(common, batch_index)
        xs = [
            margin_x,
            margin_x + table_w + gap,
            margin_x + 2 * (table_w + gap),
        ]
        draw_shift_table(g1, xs[0], _shift_pdf_heading(g1, "Ca 1 (10:00 - 23:00)"))
        draw_shift_table(g2, xs[1], _shift_pdf_heading(g2, "Ca 2 (13:00 - 23:59)"))
        draw_shift_table(gc, xs[2], "Chung (Cố định Ca 1 + Cố định Ca 2)")

        if not other.empty and batch_index == 0:
            unknown_names = ", ".join(other["Tên nhân viên"].astype(str).tolist()[:5])
            if len(other) > 5:
                unknown_names += f" và {len(other)-5} người khác"
            pdf.setFont(font_regular, 4.4)
            pdf.drawString(
                margin_x,
                2.0 * mm,
                f"Chưa nhận diện ca: {unknown_names}",
            )

    for batch in range(card_sets):
        # Mặt 1: Ca1 + Ca2 + Chung.
        draw_same_layout("Mặt 1", batch)
        pdf.showPage()

        # Mặt 2: cùng 3 bảng, cùng tọa độ - gióng chính xác với Mặt 1.
        draw_same_layout("Mặt 2", batch)
        pdf.showPage()

    pdf.save()
    return out.getvalue(), ""



def build_shift_template_excel_bytes(credentials_df):
    """
    V92.6 - Export template phân ca:
    - Cột B = Ca làm việc.
    - Dropdown cột B của từng nhân viên chỉ hiện ca thuộc đúng bộ phận.
    - leader + nhanvien dùng chung Nhân viên + Leader.
    - quanly / letan / locker / tapvu dùng danh mục riêng.
    """
    from openpyxl import Workbook
    from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
    from openpyxl.worksheet.datavalidation import DataValidation
    from openpyxl.utils import get_column_letter

    d = get_nhanvien_shift_dataframe(credentials_df).copy()

    wb = Workbook()
    ws = wb.active
    ws.title = "ThietLapCa"

    headers = [
        "Tên nhân viên",
        "Ca làm việc",
        "Ngày bắt đầu ca",
        "Chu kỳ luân phiên",
        "Bộ phận",
    ]
    ws.append(headers)

    for _, r in d.iterrows():
        ws.append([
            str(r.get("Tên nhân viên","")).strip(),
            str(r.get("Ca làm việc","")).strip(),
            str(r.get("Ngày bắt đầu ca","")).strip(),
            str(r.get("Chu kỳ","")).strip(),
            str(r.get("Bộ phận","")).strip(),
        ])

    # Style.
    fill = PatternFill("solid", fgColor="A1948C")
    thin = Side(style="thin", color="D9D9D9")
    for cell in ws[1]:
        cell.fill = fill
        cell.font = Font(bold=True, color="000000")
        cell.alignment = Alignment(
            horizontal="center", vertical="center", wrap_text=True
        )

    for row in ws.iter_rows(
        min_row=1,
        max_row=max(2, ws.max_row),
        min_col=1,
        max_col=5,
    ):
        for cell in row:
            cell.border = Border(
                left=thin, right=thin, top=thin, bottom=thin
            )
            cell.alignment = Alignment(vertical="center", wrap_text=False)

    widths = [24, 32, 22, 24, 24]
    for i, width in enumerate(widths, start=1):
        ws.column_dimensions[get_column_letter(i)].width = width

    # Cột E chỉ dùng để xác định bộ phận cho dropdown, ẩn khỏi người dùng.
    ws.column_dimensions["E"].hidden = True
    ws.freeze_panes = "A2"
    ws.auto_filter.ref = f"A1:D{max(2, ws.max_row)}"

    # ------------------------------------------------------
    # DANH MỤC CA RIÊNG THEO BỘ PHẬN
    # ------------------------------------------------------
    dm = wb.create_sheet("DanhMuc")
    dm["A1"] = "Chu kỳ luân phiên"

    for i, v in enumerate(SHIFT_CYCLE_OPTIONS, start=2):
        dm.cell(i, 1, v)

    # Mỗi bộ phận = 1 cột riêng trong sheet ẩn.
    dept_col_map = {}
    for col_idx, dep in enumerate(SHIFT_DEPARTMENT_ORDER, start=2):
        dept_col_map[dep] = col_idx
        dm.cell(1, col_idx, dep)

        options = get_shift_options(dep)
        for row_idx, value in enumerate(options, start=2):
            dm.cell(row_idx, col_idx, value)

    dm.sheet_state = "hidden"

    # ------------------------------------------------------
    # DROPDOWN CỘT B THEO ĐÚNG BỘ PHẬN TỪNG NHÂN VIÊN
    # ------------------------------------------------------
    dept_validations = {}

    for dep in SHIFT_DEPARTMENT_ORDER:
        col_idx = dept_col_map[dep]
        col_letter = get_column_letter(col_idx)
        options = get_shift_options(dep)

        if not options:
            continue

        dv = DataValidation(
            type="list",
            formula1=f"=DanhMuc!${col_letter}$2:${col_letter}${len(options)+1}",
            allow_blank=True,
        )
        dv.error = f"Chỉ được chọn ca thuộc bộ phận {dep}."
        dv.errorTitle = "Ca làm việc không hợp lệ"
        dv.prompt = f"Chọn ca của bộ phận {dep}."
        dv.promptTitle = "Danh sách ca"
        dv.showErrorMessage = True
        dv.showInputMessage = True
        ws.add_data_validation(dv)
        dept_validations[dep] = dv

    # Gán dropdown B cho đúng dòng nhân viên.
    for excel_row in range(2, ws.max_row + 1):
        dep = str(ws.cell(excel_row, 5).value or "").strip()
        dv = dept_validations.get(dep)
        if dv is not None:
            dv.add(ws[f"B{excel_row}"])

    # Chu kỳ vẫn dùng chung.
    dv_cycle = DataValidation(
        type="list",
        formula1=f"=DanhMuc!$A$2:$A${len(SHIFT_CYCLE_OPTIONS)+1}",
        allow_blank=True,
    )
    ws.add_data_validation(dv_cycle)

    max_target_row = max(300, ws.max_row + 100)
    dv_cycle.add(f"D2:D{max_target_row}")

    out = io.BytesIO()
    wb.save(out)
    return out.getvalue()


def render_shift_template_download_button(credentials_df):
    """
    V92.6.1 - Tải Excel template trực tiếp bằng data URI.
    Không dùng MediaFileManager/link file tạm của st.download_button,
    tránh lỗi "file không tồn tại" sau rerun hoặc khi Cloud Run đổi instance.
    """
    try:
        payload = build_shift_template_excel_bytes(credentials_df)
        if not payload:
            st.error("Không tạo được dữ liệu Excel template phân ca.")
            return

        filename = f"Vera-Spa_Template_Ca_{get_vn_today().strftime('%Y%m%d')}.xlsx"
        b64 = base64.b64encode(payload).decode("ascii")
        safe_filename = html.escape(filename, quote=True)

        st.markdown(
            f"""
            <a href="data:application/vnd.openxmlformats-officedocument.spreadsheetml.sheet;base64,{b64}"
               download="{safe_filename}"
               class="vera-shift-template-download-v9261">
               📥 Export Excel template phân ca
            </a>
            <style>
            .vera-shift-template-download-v9261{{
                display:flex;
                width:100%;
                min-height:40px;
                box-sizing:border-box;
                align-items:center;
                justify-content:center;
                padding:0.45rem 0.75rem;
                border:1px solid rgba(49,51,63,.2);
                border-radius:0.5rem;
                background:#FFFFFF;
                color:#222222 !important;
                font-weight:600;
                text-decoration:none !important;
                cursor:pointer;
            }}
            .vera-shift-template-download-v9261:hover{{
                border-color:rgba(49,51,63,.45);
                background:#F5F6FA;
            }}
            @media(max-width:768px){{
                .vera-shift-template-download-v9261{{min-height:44px;}}
            }}
            </style>
            """,
            unsafe_allow_html=True,
        )
    except Exception as e:
        st.error(f"Không tạo được Excel template phân ca: {e}")


def read_shift_template_excel(uploaded_file, credentials_df):
    """
    V92.6:
    Đọc template và chỉ chấp nhận ca thuộc đúng bộ phận của từng nhân viên.
    """
    try:
        raw = pd.read_excel(
            uploaded_file,
            sheet_name="ThietLapCa",
            dtype=str,
            engine="openpyxl",
        ).fillna("")
    except Exception as e:
        return pd.DataFrame(), f"Không đọc được file template: {e}"

    raw = raw.rename(columns={"Chu kỳ luân phiên": "Chu kỳ"})
    required = [
        "Tên nhân viên",
        "Ca làm việc",
        "Ngày bắt đầu ca",
        "Chu kỳ",
    ]
    missing = [c for c in required if c not in raw.columns]
    if missing:
        return pd.DataFrame(), "Thiếu cột: " + ", ".join(missing)

    allowed = get_nhanvien_shift_dataframe(credentials_df).copy()
    if allowed.empty:
        return pd.DataFrame(columns=required), ""

    employee_meta = {}
    for _, r in allowed.iterrows():
        key = normalize_login_name(r.get("Tên nhân viên", ""))
        if not key:
            continue
        employee_meta[key] = {
            "department": str(r.get("Bộ phận", "")).strip(),
        }

    raw = raw[required].copy()
    raw["_employee_key"] = (
        raw["Tên nhân viên"].astype(str).apply(normalize_login_name)
    )
    raw = raw[
        raw["_employee_key"].isin(set(employee_meta.keys()))
    ].copy()

    invalid_rows = []
    validated_shift = []

    for idx, row in raw.iterrows():
        emp_key = row["_employee_key"]
        dep = employee_meta.get(emp_key, {}).get("department", "")
        shift_value = str(row.get("Ca làm việc", "")).strip()
        valid_options = get_shift_options(dep)

        if shift_value and shift_value not in valid_options:
            invalid_rows.append(
                f"{row.get('Tên nhân viên','')} → {shift_value} ({dep})"
            )
            validated_shift.append("")
        else:
            validated_shift.append(shift_value)

    raw["Ca làm việc"] = validated_shift
    raw["Chu kỳ"] = (
        raw["Chu kỳ"].astype(str)
        .where(
            raw["Chu kỳ"].astype(str).isin(SHIFT_CYCLE_OPTIONS),
            "",
        )
    )

    raw = raw.drop(columns=["_employee_key"])
    raw["_sort"] = (
        raw["Tên nhân viên"].astype(str).apply(normalize_login_name)
    )
    raw = (
        raw.sort_values("_sort", kind="stable")
        .drop(columns=["_sort"])
        .reset_index(drop=True)
    )

    if invalid_rows:
        preview = "; ".join(invalid_rows[:8])
        extra = (
            f" và {len(invalid_rows)-8} dòng khác"
            if len(invalid_rows) > 8
            else ""
        )
        return raw, (
            "Có ca không thuộc đúng bộ phận nên hệ thống đã làm trống ô Ca làm việc: "
            + preview + extra
        )

    return raw, ""


# --- GHI NHẬN HÀNG LOẠT CA LÀM VIỆC TỪ DATAFRAME ---
def batch_update_shift_schedule(edited_df):
    """Ghi đồng loạt O:P:Q một lần, không update lại toàn bộ Sheet1."""
    try:
        client = get_gspread_client()
        if not client: return False, "Chưa cấu hình quyền kết nối."
        sheet = client.open_by_key(SHEET_MAT_KHAU_ID).get_worksheet(0)
        all_vals = _gs_call_with_backoff(sheet.get_all_values)
        if not all_vals or len(all_vals) < 2:
            return False, "Sheet1 chưa có dữ liệu nhân viên."

        shift_map = {}
        for _, r in edited_df.iterrows():
            nv_name = normalize_login_name(r.get('Tên nhân viên', ''))
            if not nv_name:
                continue
            shift_map[nv_name] = {
                'ca': (
                    "" if str(r.get('Ca làm việc', '')).strip().lower() in {"", "none", "nan", "<na>"}
                    else str(r.get('Ca làm việc', '')).strip()
                ),
                'ngay': (
                    "" if str(r.get('Ngày bắt đầu ca', '')).strip().lower() in {"", "none", "nan", "<na>"}
                    else str(r.get('Ngày bắt đầu ca', '')).strip()
                ),
                'chuky': (
                    "" if str(r.get('Chu kỳ', '')).strip().lower() in {"", "none", "nan", "<na>"}
                    else str(r.get('Chu kỳ', '')).strip()
                )
            }

        out = []
        updated = 0
        for row in all_vals[1:]:
            rr = list(row)
            while len(rr) < 17:
                rr.append("")
            key = normalize_login_name(rr[1] if len(rr) > 1 else '')
            ca, ngay, chuky = rr[14], rr[15], rr[16]
            if key in shift_map:
                ca = shift_map[key]['ca']; ngay = shift_map[key]['ngay']; chuky = shift_map[key]['chuky']
                updated += 1
            out.append([ca, ngay, chuky])

        if out:
            gspread_update_range(sheet, f"O2:Q{len(out)+1}", out, value_input_option='USER_ENTERED')
        _clear_dynamic_data_caches()
        return True, f"Đã lưu cấu hình ca cho {updated} nhân viên."
    except Exception as e:
        return False, f"Lỗi cập nhật: {e}"

# --- DANH SÁCH NHÂN SỰ: SẮP XẾP / EXPORT / IMPORT ---
STAFF_EXPORT_COLUMNS = [
    'Tên nhân viên', 'Họ và tên đầy đủ', 'Phân quyền', 'Trạng thái làm việc',
    'Điện thoại', 'Email', 'Địa chỉ', 'Số tài khoản ngân hàng',
    'Tên ngân hàng', 'Khóa đăng nhập'
]


def normalize_employment_status_value(value, default=EMPLOYMENT_STATUS_ACTIVE):
    key = normalize_login_name(value)
    if not key:
        return default
    return EMPLOYMENT_STATUS_ALIASES.get(key, default)


def build_staff_list_dataframe(credentials_df):
    """Danh sách nhân sự chuẩn: tên A→Z, role chuẩn hóa, trạng thái theo 3 mức mới."""
    if credentials_df is None or not isinstance(credentials_df, pd.DataFrame) or credentials_df.empty:
        return pd.DataFrame(columns=STAFF_EXPORT_COLUMNS)
    d = credentials_df.copy()
    employment_map = load_employment_status_map()
    if 'Tên nhân viên' not in d.columns:
        d['Tên nhân viên'] = ''
    if 'Phân quyền' not in d.columns:
        d['Phân quyền'] = 'nhanvien'
    d['Phân quyền'] = d['Phân quyền'].astype(str).str.strip().str.lower()
    d['Trạng thái làm việc'] = d['Tên nhân viên'].astype(str).apply(
        lambda name: employment_map.get(normalize_login_name(name), EMPLOYMENT_STATUS_ACTIVE)
    )
    for col in STAFF_EXPORT_COLUMNS:
        if col not in d.columns:
            d[col] = ''
    # Thứ tự nhân sự: Phân quyền theo thứ tự chuẩn; trong từng nhóm role, Tên nhân viên A→Z.
    # Các role còn lại (tapvu/admin) được đặt sau nhóm người dùng yêu cầu.
    role_rank = {role: i for i, role in enumerate(STAFF_ROLE_ORDER)}
    d['_staff_name_sort'] = d['Tên nhân viên'].astype(str).apply(normalize_login_name)
    d['_staff_role_rank'] = d['Phân quyền'].map(role_rank).fillna(len(role_rank)).astype(int)
    d = d.sort_values(['_staff_role_rank', '_staff_name_sort'], kind='stable')
    return d[STAFF_EXPORT_COLUMNS].reset_index(drop=True)


def staff_list_to_excel(df):
    """Export Danh sách nhân sự với dropdown Phân quyền/Trạng thái để có thể sửa rồi import lại."""
    from openpyxl import Workbook
    from openpyxl.styles import Font, Alignment
    from openpyxl.worksheet.datavalidation import DataValidation
    from openpyxl.utils import get_column_letter

    d = df.copy() if isinstance(df, pd.DataFrame) else pd.DataFrame(columns=STAFF_EXPORT_COLUMNS)
    for col in STAFF_EXPORT_COLUMNS:
        if col not in d.columns:
            d[col] = ''
    d = d[STAFF_EXPORT_COLUMNS].copy()

    wb = Workbook()
    ws = wb.active
    ws.title = 'DanhSachNhanSu'
    ws.append(list(d.columns))
    for _, row in d.iterrows():
        ws.append([str(row.get(c, '') if not pd.isna(row.get(c, '')) else '') for c in d.columns])

    for cell in ws[1]:
        cell.font = Font(bold=True)
        cell.alignment = Alignment(horizontal='center', vertical='center', wrap_text=True)
    ws.freeze_panes = 'A2'
    ws.auto_filter.ref = ws.dimensions

    widths = {
        'Tên nhân viên': 24, 'Họ và tên đầy đủ': 28, 'Phân quyền': 14,
        'Trạng thái làm việc': 22, 'Điện thoại': 16, 'Email': 30, 'Địa chỉ': 42,
        'Số tài khoản ngân hàng': 22, 'Tên ngân hàng': 24, 'Khóa đăng nhập': 18,
    }
    for idx, col in enumerate(d.columns, start=1):
        ws.column_dimensions[get_column_letter(idx)].width = widths.get(col, 18)

    max_row = max(2, ws.max_row)
    if 'Phân quyền' in d.columns:
        col_idx = d.columns.get_loc('Phân quyền') + 1
        role_list = ','.join(STAFF_ROLE_ORDER)
        dv_role = DataValidation(type='list', formula1=f'"{role_list}"', allow_blank=False)
        ws.add_data_validation(dv_role)
        dv_role.add(f'{get_column_letter(col_idx)}2:{get_column_letter(col_idx)}{max_row}')
    if 'Trạng thái làm việc' in d.columns:
        col_idx = d.columns.get_loc('Trạng thái làm việc') + 1
        status_list = ','.join(EMPLOYMENT_STATUS_OPTIONS)
        dv_status = DataValidation(type='list', formula1=f'"{status_list}"', allow_blank=False)
        ws.add_data_validation(dv_status)
        dv_status.add(f'{get_column_letter(col_idx)}2:{get_column_letter(col_idx)}{max_row}')

    note = wb.create_sheet('HuongDan')
    note['A1'] = 'HƯỚNG DẪN IMPORT DANH SÁCH NHÂN SỰ'
    note['A1'].font = Font(bold=True)
    note['A3'] = '1. Không đổi Tên nhân viên vì đây là khóa đối chiếu tài khoản.'
    note['A4'] = '2. Có thể sửa các cột hồ sơ, Phân quyền, Trạng thái làm việc và Khóa đăng nhập.'
    note['A5'] = '3. Import không ghi đè Mật khẩu, Ngày sinh, quỹ phép, ca làm việc hoặc Remember Token (trừ khi khóa đăng nhập).'
    note.column_dimensions['A'].width = 110

    out = io.BytesIO()
    wb.save(out)
    return out.getvalue()


def read_staff_list_import(uploaded_file):
    """Đọc file export Danh sách nhân sự; Tên nhân viên là khóa, không tạo/xóa tài khoản."""
    try:
        raw = pd.read_excel(uploaded_file, dtype=str, engine='openpyxl').fillna('')
    except Exception as e:
        return pd.DataFrame(), f"Không đọc được file Excel: {e}"
    if 'Tên nhân viên' not in raw.columns:
        return pd.DataFrame(), "File import phải có cột 'Tên nhân viên'."
    raw = raw.copy()
    raw['Tên nhân viên'] = raw['Tên nhân viên'].astype(str).str.strip()
    raw = raw[raw['Tên nhân viên'] != ''].copy()
    if raw.empty:
        return pd.DataFrame(), "File import không có nhân viên."

    keys = raw['Tên nhân viên'].apply(normalize_login_name)
    duplicated = raw.loc[keys.duplicated(keep=False), 'Tên nhân viên'].astype(str).tolist()
    if duplicated:
        return pd.DataFrame(), "Tên nhân viên bị trùng trong file import: " + ", ".join(sort_employee_names(duplicated))

    if 'Phân quyền' in raw.columns:
        roles = raw['Phân quyền'].astype(str).str.strip().str.lower()
        invalid_roles = sorted({x for x in roles if x and x not in ALL_ACCOUNT_ROLES})
        if invalid_roles:
            return pd.DataFrame(), "Phân quyền không hợp lệ: " + ", ".join(invalid_roles)
        raw['Phân quyền'] = roles

    if 'Trạng thái làm việc' in raw.columns:
        invalid_statuses = []
        normalized_statuses = []
        for val in raw['Trạng thái làm việc'].astype(str).tolist():
            if not str(val).strip():
                normalized_statuses.append('')
                continue
            key = normalize_login_name(val)
            if key not in EMPLOYMENT_STATUS_ALIASES:
                invalid_statuses.append(str(val).strip())
                normalized_statuses.append('')
            else:
                normalized_statuses.append(EMPLOYMENT_STATUS_ALIASES[key])
        if invalid_statuses:
            return pd.DataFrame(), "Trạng thái làm việc không hợp lệ: " + ", ".join(sorted(set(invalid_statuses)))
        raw['Trạng thái làm việc'] = normalized_statuses

    raw['_staff_import_key'] = raw['Tên nhân viên'].apply(normalize_login_name)
    return raw, ''


def batch_import_staff_list(import_df, updated_by, actor_role="admin"):
    """Import lại danh sách nhân sự hiện có, giữ giới hạn phân quyền của Admin/Lễ tân/Quản lý."""
    if import_df is None or not isinstance(import_df, pd.DataFrame) or import_df.empty:
        return False, "Không có dữ liệu để import."
    try:
        client = get_gspread_client()
        if not client:
            return False, "Chưa cấu hình quyền kết nối Google Sheets."
        sheet = client.open_by_key(SHEET_MAT_KHAU_ID).get_worksheet(0)
        all_vals = _gs_call_with_backoff(sheet.get_all_values)
        if not all_vals or len(all_vals) < 2:
            return False, "Sheet1 chưa có dữ liệu nhân sự."

        import_map = {
            normalize_login_name(r.get('Tên nhân viên', '')): r
            for _, r in import_df.iterrows()
            if normalize_login_name(r.get('Tên nhân viên', ''))
        }
        existing_keys = {
            normalize_login_name(row[1] if len(row) > 1 else '')
            for row in all_vals[1:]
            if normalize_login_name(row[1] if len(row) > 1 else '')
        }
        unknown = [str(r.get('Tên nhân viên', '')).strip() for _, r in import_df.iterrows()
                   if normalize_login_name(r.get('Tên nhân viên', '')) not in existing_keys]
        if unknown:
            return False, "Không tìm thấy trong hệ thống: " + ", ".join(sort_employee_names(unknown))

        actor_role = str(actor_role or '').strip().lower()
        current_status_map = load_employment_status_map()
        if actor_role != 'admin':
            # Lễ tân/Quản lý có thể import file đầy đủ, nhưng chỉ được THAY ĐỔI
            # các tài khoản thuộc nhanvien/locker/tapvu và không được nâng role.
            for row in all_vals[1:]:
                rr = list(row)
                while len(rr) < 20:
                    rr.append('')
                key = normalize_login_name(rr[1])
                item = import_map.get(key)
                if item is None:
                    continue
                current_role = str(rr[3]).strip().lower() or 'nhanvien'
                imported_role = str(item.get('Phân quyền', current_role)).strip().lower() if 'Phân quyền' in import_df.columns else current_role
                if current_role in FRONTDESK_MANAGEABLE_ROLES:
                    if imported_role and imported_role not in FRONTDESK_MANAGEABLE_ROLES:
                        return False, f"Không được đổi {rr[1]} sang phân quyền '{imported_role}'."
                    continue

                def _same_text(col, current):
                    return col not in import_df.columns or str(item.get(col, '')).replace("'", '').strip() == str(current).replace("'", '').strip()

                changed = False
                if 'Phân quyền' in import_df.columns and imported_role != current_role:
                    changed = True
                changed = changed or not _same_text('Họ và tên đầy đủ', rr[4])
                changed = changed or not _same_text('Điện thoại', rr[6])
                changed = changed or not _same_text('Email', rr[7])
                changed = changed or not _same_text('Địa chỉ', rr[8])
                changed = changed or not _same_text('Số tài khoản ngân hàng', rr[9])
                changed = changed or not _same_text('Tên ngân hàng', rr[10])
                if 'Khóa đăng nhập' in import_df.columns:
                    changed = changed or (is_locked_value(item.get('Khóa đăng nhập', '')) != is_locked_value(rr[17]))
                if 'Trạng thái làm việc' in import_df.columns:
                    imported_status = normalize_employment_status_value(item.get('Trạng thái làm việc', ''))
                    current_status = current_status_map.get(key, EMPLOYMENT_STATUS_ACTIVE)
                    changed = changed or imported_status != current_status
                if changed:
                    return False, (
                        f"Lễ tân/Quản lý không được thay đổi tài khoản {rr[1]} ({current_role}). "
                        "Chỉ được import thay đổi cho nhanvien, locker hoặc tapvu."
                    )

        out_dk = []  # D:K = role, họ tên, ngày sinh(preserve), phone, email, address, bank acc, bank
        out_rt = []  # R:T = khóa login + remember token hash/expiry (token chỉ xóa khi khóa)
        updated_count = 0
        imported_status_by_key = {}
        imported_role_by_key = {}

        for row in all_vals[1:]:
            rr = list(row)
            while len(rr) < 20:
                rr.append('')
            key = normalize_login_name(rr[1])
            item = import_map.get(key)
            role, fullname, dob, phone, email, address, bank_acc, bank_name = rr[3:11]
            lock_val, token_hash, token_expiry = rr[17], rr[18], rr[19]
            if item is not None:
                updated_count += 1
                if 'Phân quyền' in import_df.columns and str(item.get('Phân quyền', '')).strip():
                    role = str(item.get('Phân quyền', '')).strip().lower()
                imported_role_by_key[key] = role
                if 'Họ và tên đầy đủ' in import_df.columns:
                    fullname = str(item.get('Họ và tên đầy đủ', '')).strip()
                if 'Điện thoại' in import_df.columns:
                    phone = str(item.get('Điện thoại', '')).replace("'", '').strip()
                if 'Email' in import_df.columns:
                    email = str(item.get('Email', '')).strip()
                if 'Địa chỉ' in import_df.columns:
                    address = str(item.get('Địa chỉ', '')).strip()
                if 'Số tài khoản ngân hàng' in import_df.columns:
                    bank_acc = str(item.get('Số tài khoản ngân hàng', '')).replace("'", '').strip()
                if 'Tên ngân hàng' in import_df.columns:
                    bank_name = str(item.get('Tên ngân hàng', '')).strip()
                if 'Khóa đăng nhập' in import_df.columns:
                    lock_val = 'KHÓA' if is_locked_value(item.get('Khóa đăng nhập', '')) else ''
                    if lock_val:
                        token_hash = ''
                        token_expiry = ''
                if 'Trạng thái làm việc' in import_df.columns:
                    raw_status = str(item.get('Trạng thái làm việc', '')).strip()
                    if raw_status:
                        imported_status_by_key[key] = normalize_employment_status_value(raw_status)

            phone_write = f"'{phone}" if str(phone).strip() else ''
            bank_write = f"'{bank_acc}" if str(bank_acc).strip() else ''
            out_dk.append([role, fullname, dob, phone_write, email, address, bank_write, bank_name])
            out_rt.append([lock_val, token_hash, token_expiry])

        # Hai lần ghi range lớn thay cho hàng trăm update_cell -> giảm nguy cơ Sheets 429.
        last_row = len(out_dk) + 1
        if out_dk:
            gspread_update_range(sheet, f'D2:K{last_row}', out_dk, value_input_option='USER_ENTERED')
            gspread_update_range(sheet, f'R2:T{last_row}', out_rt, value_input_option='USER_ENTERED')

        # Cập nhật bảng trạng thái làm việc theo cùng danh sách nhân sự.
        if imported_status_by_key:
            status_ws = _get_employment_status_worksheet()
            existing_status = load_employment_status_map()
            now = datetime.now(VN_TZ)
            status_rows = []
            stt = 0
            for row in all_vals[1:]:
                name = str(row[1]).strip() if len(row) > 1 else ''
                key = normalize_login_name(name)
                if not key:
                    continue
                role_now = imported_role_by_key.get(key, str(row[3]).strip().lower() if len(row) > 3 else 'nhanvien')
                if role_now == 'admin':
                    continue
                stt += 1
                status = imported_status_by_key.get(key, existing_status.get(key, EMPLOYMENT_STATUS_ACTIVE))
                status_rows.append([
                    stt, name, status, now.strftime('%d/%m/%Y'), now.strftime('%H:%M:%S'), str(updated_by).strip()
                ])
            if status_ws is not None:
                try:
                    _gs_call_with_backoff(status_ws.batch_clear, ['A2:F1000'])
                except Exception:
                    pass
                if status_rows:
                    gspread_update_range(status_ws, f'A2:F{len(status_rows)+1}', status_rows, value_input_option='USER_ENTERED')

        _clear_dynamic_data_caches()
        try:
            load_employment_status_map.clear()
        except Exception:
            pass
        try:
            sync_tichluy_roles_and_stt(load_credentials_fresh())
        except Exception:
            pass
        return True, f"Đã import và cập nhật {updated_count} nhân viên. Mật khẩu, ngày sinh, quỹ phép, ca làm việc và Remember Token không bị ghi đè."
    except Exception as e:
        return False, f"Lỗi import danh sách nhân sự: {e}"


# --- TẢI DỮ LIỆU TỪ GOOGLE SHEET DỰ PHÒNG ---
def _load_backup_sheet_data_from_sheets():
    """Đọc Sheet1 A:M theo header thực tế."""
    expected = LEAVE_DATA_COLUMNS
    try:
        client = get_gspread_client()
        if not client:
            return pd.DataFrame(columns=expected + ["__source_sheet_id", "__source_row"])
        sheet = client.open_by_key(SHEET_DU_PHONG_ID).get_worksheet(0)
        headers = _ensure_leave_sheet_schema(sheet)
        values = _gs_call_with_backoff(sheet.get, LEAVE_MAIN_RANGE)
        if not values or len(values) < 2:
            return pd.DataFrame(columns=expected + ["__source_sheet_id", "__source_row"])
        rows = []
        for sheet_row, raw in enumerate(values[1:], start=2):
            vals = list(raw[:13]) + [""] * max(0, 13 - len(raw))
            if not any(str(v).strip() for v in vals):
                continue
            item = _leave_sheet_row_to_record(vals, headers)
            if not item.get("Thứ ngày"):
                item["Thứ ngày"] = _vn_weekday_label(item.get("Ngày", ""))
            if not item.get("Loại nghỉ"):
                item["Loại nghỉ"] = _leave_type_for_reason(item.get("Lý do nghỉ", ""))
            item["__source_sheet_id"] = SHEET_DU_PHONG_ID
            item["__source_row"] = sheet_row
            rows.append(item)
        return pd.DataFrame(rows) if rows else pd.DataFrame(
            columns=expected + ["__source_sheet_id", "__source_row"]
        )
    except Exception:
        return pd.DataFrame(columns=expected + ["__source_sheet_id", "__source_row"])

@st.cache_data(ttl=45, show_spinner=False)
def load_backup_sheet_data():
    """V75: đọc qua PostgreSQL dùng chung giữa các Cloud Run instance; Google Sheets là nguồn đồng bộ dự phòng."""
    if vpg is not None and _vpg_is_enabled():
        return vpg.load_dataset(
            "leave_primary",
            _load_backup_sheet_data_from_sheets,
            ttl_seconds=int(os.getenv("VERA_PG_TTL_LEAVE_PRIMARY", "45")),
        )
    return _load_backup_sheet_data_from_sheets()


