def _embedded_loai_nghi_dataframe():
    return pd.DataFrame(
        [list(row) for row in EMBEDDED_LOAI_NGHI_ROWS],
        columns=list(EMBEDDED_LOAI_NGHI_HEADERS),
    )


def _loai_nghi_payload_to_dataframe(payload):
    if not isinstance(payload, dict):
        return pd.DataFrame()
    headers = payload.get("headers")
    rows = payload.get("rows")
    if not isinstance(headers, list) or not isinstance(rows, list):
        return pd.DataFrame()
    try:
        width = len(headers)
        normalized = []
        for raw in rows:
            vals = list(raw) if isinstance(raw, (list, tuple)) else []
            vals = vals[:width] + [""] * max(0, width - len(vals))
            normalized.append(vals)
        return pd.DataFrame(normalized, columns=[str(x) for x in headers])
    except Exception:
        return pd.DataFrame()


def _loai_nghi_dataframe_to_payload(df, updated_by=""):
    safe_df = df.copy().fillna("")
    return {
        "schema": "LoaiNghi_A_N_v2",
        "headers": [str(x) for x in safe_df.columns.tolist()],
        "rows": [
            [str(v) if v is not None else "" for v in row]
            for row in safe_df.astype(str).values.tolist()
        ],
        "updated_at": datetime.now(VN_TZ).isoformat(),
        "updated_by": str(updated_by or ""),
    }


def _loai_nghi_header_lookup(df):
    return {normalize_login_name(c): c for c in df.columns}


def validate_loai_nghi_runtime_dataframe(df):
    """Kiểm tra cấu trúc/rule trước khi cho snapshot mới thay thế bản đang chạy."""
    if not isinstance(df, pd.DataFrame) or df.empty:
        return False, ["Sheet LoaiNghi không có dữ liệu."]

    lookup = _loai_nghi_header_lookup(df)
    required_any = [
        ["ly do nghi"],
        ["loai nghi"],
        ["so ngay tinh phep", "so ngay tinh"],
        ["phat vi pham"],
        ["chi nhap duoc cuoi tuan", "ngay duoc phep nhap", "ngay duoc nhap"],
        ["user co quyen duoc nhap"],
        ["kieu dang ky", "kieu dang ky"],  # chấp nhận cả Kiểu/Kiều sau normalize
        ["gia tri", "gia tri dang ky"],
        ["ngoai tru dang ky"],
        ["kieu huy"],
        ["so ngay huy truoc", "gia tri huy"],
        ["ngoai tru huy"],
    ]
    missing = []
    for aliases in required_any:
        if not any(alias in lookup for alias in aliases):
            missing.append("/".join(aliases))
    if missing:
        return False, ["Thiếu header bắt buộc: " + ", ".join(missing)]

    errors = []
    catalog = build_leave_reason_catalog(df)
    if not catalog:
        errors.append("Không tạo được Rule Catalog từ LoaiNghi.")
        return False, errors

    for item in catalog.values():
        name = str(item.get("name", "") or "")
        reg = _parse_leave_policy_rule(
            item.get("register_type", ""),
            item.get("register_value", ""),
            "register",
        )
        cancel = _parse_leave_policy_rule(
            item.get("cancel_type", ""),
            item.get("cancel_value", ""),
            "cancel",
        )
        if reg.get("mode") == "invalid":
            errors.append(
                f"{name}: Kiểu đăng ký '{item.get('register_type','')}' "
                f"có Giá trị '{item.get('register_value','')}' không hợp lệ."
            )
        # Kiểu hủy có thể để trống có chủ đích đối với một số lý do phát sinh.
        if item.get("cancel_type") and cancel.get("mode") == "invalid":
            errors.append(
                f"{name}: Kiểu hủy '{item.get('cancel_type','')}' "
                f"có Giá trị '{item.get('cancel_value','')}' không hợp lệ."
            )

    return len(errors) == 0, errors


def _fetch_loai_nghi_from_gsheet_once():
    """Chỉ gọi khi Admin bấm Cập nhật qui định."""
    client = get_gspread_client()
    if not client:
        raise RuntimeError("Không tạo được kết nối Google Sheets.")
    sheet = client.open_by_key(SHEET_DU_PHONG_ID).worksheet("LoaiNghi")
    rows = _gs_call_with_backoff(sheet.get_all_values)
    if not rows or len(rows) < 2:
        raise RuntimeError("Sheet LoaiNghi đang rỗng hoặc chưa có dữ liệu.")
    width = len(rows[0])
    normalized = [
        list(r[:width]) + [""] * max(0, width - len(r))
        for r in rows[1:]
        if any(str(v).strip() for v in r)
    ]
    return pd.DataFrame(normalized, columns=[str(x) for x in rows[0]])


@st.cache_data(ttl=60, show_spinner=False)
def _load_persistent_loai_nghi_snapshot():
    """
    Đọc snapshot PostgreSQL nhỏ, không đọc Google Sheet.
    TTL 60s chỉ để các Cloud Run instance khác tự nhận rule mới trong tối đa 1 phút.
    """
    if vpg is None or not _vpg_is_enabled():
        return pd.DataFrame()
    read_fn = getattr(vpg, "read_setting", None)
    if not callable(read_fn):
        return pd.DataFrame()
    try:
        payload = read_fn(
            LOAI_NGHI_RULE_SETTING_CATEGORY,
            LOAI_NGHI_RULE_SETTING_KEY,
            default=None,
        )
        return _loai_nghi_payload_to_dataframe(payload)
    except Exception:
        return pd.DataFrame()


def load_runtime_loai_nghi():
    """
    Không gọi Google Sheet.
    Phiên vừa bấm cập nhật dùng override ngay; các phiên khác dùng PostgreSQL,
    cuối cùng fallback về quy định đóng sẵn trong app.py.
    """
    session_payload = st.session_state.get("_loai_nghi_runtime_override_v92631")
    session_df = _loai_nghi_payload_to_dataframe(session_payload)
    if isinstance(session_df, pd.DataFrame) and not session_df.empty:
        return session_df

    pg_df = _load_persistent_loai_nghi_snapshot()
    if isinstance(pg_df, pd.DataFrame) and not pg_df.empty:
        return pg_df

    return _embedded_loai_nghi_dataframe()


def refresh_loai_nghi_rules_now():
    """
    Sửa LoaiNghi -> bấm Cập nhật qui định -> xong.

    1) đọc Google Sheet đúng 1 lần;
    2) kiểm tra cấu trúc + Rule Engine;
    3) lưu snapshot vào PostgreSQL nếu khả dụng;
    4) áp dụng ngay trong phiên hiện tại;
    5) không đọc lại Google Sheet ở các thao tác bình thường.
    """
    if str(st.session_state.get("current_role", "") or "").strip().lower() != "admin":
        st.error("❌ Chỉ Admin được Cập nhật qui định.")
        return

    try:
        with st.spinner("Đang đọc LoaiNghi và kiểm tra qui định mới..."):
            fresh_df = _fetch_loai_nghi_from_gsheet_once()

        ok, errors = validate_loai_nghi_runtime_dataframe(fresh_df)
        if not ok:
            st.error("❌ Không cập nhật vì LoaiNghi có cấu hình chưa hợp lệ.")
            for msg in errors[:12]:
                st.error(f"• {msg}")
            return

        actor = str(st.session_state.get("current_user", "") or "admin").strip()
        payload = _loai_nghi_dataframe_to_payload(fresh_df, updated_by=actor)

        persisted = False
        persist_message = ""
        if vpg is not None and _vpg_is_enabled():
            write_fn = getattr(vpg, "write_setting", None)
            if callable(write_fn):
                try:
                    write_fn(
                        LOAI_NGHI_RULE_SETTING_CATEGORY,
                        LOAI_NGHI_RULE_SETTING_KEY,
                        payload,
                        updated_by=actor,
                        source="google_sheet_button",
                    )
                    persisted = True
                except Exception as exc:
                    persist_message = str(exc)

        # Áp dụng ngay cho phiên Admin hiện tại dù DB đang tạm lỗi.
        st.session_state["_loai_nghi_runtime_override_v92631"] = payload
        try:
            _load_persistent_loai_nghi_snapshot.clear()
        except Exception:
            pass
        try:
            load_leave_daily_quota_config.clear()
        except Exception:
            pass
        try:
            _clear_leave_data_caches()
        except Exception:
            pass

        st.session_state["_loai_nghi_refresh_result_v92631"] = {
            "ok": True,
            "rows": len(fresh_df),
            "persisted": persisted,
            "persist_message": persist_message,
        }
        rerun_current_view()
    except Exception as exc:
        st.error(f"❌ Không cập nhật được qui định: {exc}")


def render_refresh_loai_nghi_button(key, use_container_width=True):
    """Nút chỉ hiển thị cho Admin."""
    if str(st.session_state.get("current_role", "") or "").strip().lower() != "admin":
        return
    if st.button(
        "🔄 Cập nhật qui định",
        use_container_width=use_container_width,
        key=key,
        help=(
            "Chỉ khi bấm nút này app mới đọc sheet LoaiNghi. "
            "Sau đó toàn hệ thống dùng snapshot đã lưu, không đọc Google Sheet mỗi lần nhập lịch."
        ),
    ):
        refresh_loai_nghi_rules_now()


# --- GHI VÀ XÓA LỊCH ---
def _next_data_row_a_to_m(sheet):
    """Tìm dòng kế tiếp sau last row thực tế trong vùng A:M."""
    values = _gs_call_with_backoff(sheet.get, LEAVE_MAIN_RANGE)
    last_non_empty = 0
    for idx, row in enumerate(values, start=1):
        vals = list(row[:13])
        if any(str(v).strip() != "" for v in vals):
            last_non_empty = idx
    return max(2, last_non_empty + 1)

def _live_sheet_to_leave_df(sheet):
    """Đọc LIVE A:M theo header thực tế."""
    try:
        headers = _get_leave_sheet_headers(sheet, strict=True)
        values = _gs_call_with_backoff(sheet.get, LEAVE_MAIN_RANGE)
        if not values or len(values) < 2:
            return pd.DataFrame(columns=LEAVE_DATA_COLUMNS)
        rows = []
        for raw in values[1:]:
            vals = list(raw[:13]) + [""] * max(0, 13 - len(raw))
            if not any(str(v).strip() for v in vals):
                continue
            item = _leave_sheet_row_to_record(vals, headers)
            if not item.get("Thứ ngày"):
                item["Thứ ngày"] = _vn_weekday_label(item.get("Ngày", ""))
            if not item.get("Loại nghỉ"):
                item["Loại nghỉ"] = _leave_type_for_reason(item.get("Lý do nghỉ", ""))
            rows.append(item)
        return pd.DataFrame(rows) if rows else pd.DataFrame(columns=LEAVE_DATA_COLUMNS)
    except Exception:
        return pd.DataFrame(columns=LEAVE_DATA_COLUMNS)

def _daily_leave_group(reason, reason_type_map=None):
    """
    Phân nhóm đăng ký theo Loại nghỉ (cột C của LoaiNghi), fallback theo Lý do nghỉ.
    Trả về: co_phep / khong_phep / phat_sinh / "".
    """
    reason_clean = clean_leave_reason_display(reason)
    mapping = reason_type_map if isinstance(reason_type_map, dict) else _leave_reason_type_map(
        globals().get('df_loai_nghi', pd.DataFrame())
    )
    leave_type = clean_leave_reason_display(
        mapping.get(normalize_leave_reason(reason_clean), "")
    )

    type_key = normalize_login_name(leave_type)
    reason_key = normalize_login_name(reason_clean)

    if "khong phep" in type_key:
        return "khong_phep"
    if "phat sinh" in type_key:
        return "phat_sinh"
    if "co phep" in type_key:
        return "co_phep"

    # Fallback nếu danh mục tạm thời chưa tải được.
    if "khong phep" in reason_key:
        return "khong_phep"
    if "phat sinh" in reason_key:
        return "phat_sinh"
    if (
        "co phep" in reason_key
        or "nghi phep" in reason_key
        or "nghi dam hieu" in reason_key
        or re.search(r"(^|\s)cp($|\s)", reason_key)
    ):
        return "co_phep"
    return ""


def render_leave_reason_selectbox_color(selected_reason, reason_type_map=None, marker_id="vera-leave-reason-selectbox"):
    """
    Tô màu ô selectbox 'Lý do nghỉ' theo nhóm:
    - CÓ phép     -> xanh
    - KHÔNG phép  -> đỏ
    - còn lại     -> vàng
    Chỉ áp dụng cho phần hiển thị giá trị đang chọn của selectbox.
    """
    selected_text = str(selected_reason or "").strip()
    if not selected_text or selected_text == "-- Chọn lý do nghỉ --":
        group = "other"
    else:
        raw_group = _daily_leave_group(selected_text, reason_type_map=reason_type_map)
        if raw_group == "co_phep":
            group = "co_phep"
        elif raw_group == "khong_phep":
            group = "khong_phep"
        else:
            group = "other"

    palette = {
        "co_phep": {"bg": "#E8F5E9", "border": "#2E7D32", "text": "#1B5E20"},
        "khong_phep": {"bg": "#FDECEC", "border": "#D32F2F", "text": "#8B1E1E"},
        "other": {"bg": "#FFF8E1", "border": "#E6B800", "text": "#6B5A00"},
    }
    c = palette[group]

    st.markdown(
        f"""
        <style>
        div[data-testid="stVerticalBlock"]:has(#{marker_id}) div[data-testid="stSelectbox"] [data-baseweb="select"] > div {{
            background: {c['bg']} !important;
            border: 2px solid {c['border']} !important;
            border-radius: 12px !important;
            box-shadow: none !important;
        }}
        div[data-testid="stVerticalBlock"]:has(#{marker_id}) div[data-testid="stSelectbox"] [data-baseweb="select"] * {{
            color: {c['text']} !important;
            font-weight: 700 !important;
        }}
        div[data-testid="stVerticalBlock"]:has(#{marker_id}) div[data-testid="stSelectbox"] svg {{
            fill: {c['text']} !important;
        }}
        </style>
        """,
        unsafe_allow_html=True,
    )


@st.cache_data(ttl=300, show_spinner=False)
def load_leave_daily_quota_config():
    """
    Đọc sheet Config của file lịch nghỉ:
      weekday_limit  = số CÓ PHÉP tối đa Thứ 2 -> Thứ 6
      weekend_limit  = số CÓ PHÉP tối đa Thứ 7/Chủ nhật
      phat_sinh_limit = số PHÁT SINH tối đa ngày thường
    Fallback an toàn: 5 / 3 / 2.
    """
    defaults = {
        "weekday_limit": 5,
        "weekend_limit": 3,
        "phat_sinh_limit": 2,
    }
    try:
        client = get_gspread_client()
        if not client:
            return defaults.copy()

        ss = client.open_by_key(SHEET_DU_PHONG_ID)
        ws = ss.worksheet("Config")
        values = _gs_call_with_backoff(ws.get_all_values)
        if not values:
            return defaults.copy()

        cfg = defaults.copy()
        # Hỗ trợ sheet có header Key / Value hoặc không có header.
        start_row = 1 if values and len(values[0]) >= 2 and normalize_login_name(values[0][0]) == "key" else 0
        for row in values[start_row:]:
            if len(row) < 2:
                continue
            key = str(row[0]).strip()
            if key not in cfg:
                continue
            try:
                cfg[key] = max(0, int(float(str(row[1]).replace(",", ".").strip())))
            except Exception:
                pass
        return cfg
    except Exception:
        return defaults.copy()


@st.cache_data(ttl=15, show_spinner=False)
def load_live_leave_registration_cached():
    """
    V92.6.15: snapshot ngắn 15 giây từ Google Sheet lịch nghỉ chính duy nhất.
    Sau mọi Thêm/Sửa/Xóa, _clear_leave_data_caches() xóa cache ngay nên quota vẫn chính xác.
    """
    try:
        client = get_gspread_client()
        if client:
            live = _load_live_primary_leave_sheet(client)
            if isinstance(live, pd.DataFrame):
                return live
    except Exception:
        pass
    return pd.DataFrame()


def _load_live_leave_registration_for_validation(fallback_sources=None):
    """
    Chỉ dùng Google Sheet lịch nghỉ chính (SHEET_DU_PHONG_ID). Không dùng file LichNghi cũ hoặc nguồn phụ.
    """
    live = load_live_leave_registration_cached()
    if isinstance(live, pd.DataFrame) and not live.empty:
        return live

    fallback_sources = fallback_sources or []
    try:
        return combine_leave_sources_for_daily_stats(*fallback_sources)
    except Exception:
        return pd.DataFrame()


def _daily_leave_quota_counts(all_leave_df, target_date):
    """
    Đếm quota theo NHÓM Loại nghỉ:
      co_phep: chỉ dòng Số ngày tính > 0 (giữ quy tắc Có phép 0 ngày không chiếm suất)
      phat_sinh: mọi dòng thuộc nhóm Phát sinh.
    Không dùng 'tổng người nghỉ chung' để chặn chéo hai quota.
    """
    if not isinstance(all_leave_df, pd.DataFrame) or all_leave_df.empty:
        return {"co_phep": 0, "phat_sinh": 0}

    d = all_leave_df.copy()
    if "Ngày" not in d.columns or "Lý do nghỉ" not in d.columns:
        return {"co_phep": 0, "phat_sinh": 0}

    d["__date"] = d["Ngày"].apply(_parse_vn_date)
    d = d[d["__date"].eq(target_date)].copy()
    if d.empty:
        return {"co_phep": 0, "phat_sinh": 0}

    reason_type_map = _leave_reason_type_map(globals().get("df_loai_nghi", pd.DataFrame()))
    d["__group"] = d["Lý do nghỉ"].apply(lambda x: _daily_leave_group(x, reason_type_map))

    if "Số ngày tính" in d.columns:
        d["__days"] = pd.to_numeric(d["Số ngày tính"], errors="coerce").fillna(0.0)
    else:
        d["__days"] = 1.0

    # Đếm theo nhân viên duy nhất trong cùng nhóm/ngày để dữ liệu trùng nguồn không làm tăng quota giả.
    if "Tên nhân viên" in d.columns:
        d["__emp"] = d["Tên nhân viên"].apply(normalize_login_name)
    else:
        d["__emp"] = d.index.astype(str)

    co = d[(d["__group"] == "co_phep") & (d["__days"] > 0)]
    ps = d[d["__group"] == "phat_sinh"]

    return {
        "co_phep": int(co["__emp"].replace("", pd.NA).dropna().nunique()),
        "phat_sinh": int(ps["__emp"].replace("", pd.NA).dropna().nunique()),
    }


def _daily_leave_quota_limits(target_date):
    cfg = load_leave_daily_quota_config()
    is_weekend = target_date.weekday() >= 5
    return {
        "co_phep": int(cfg["weekend_limit"] if is_weekend else cfg["weekday_limit"]),
        # Cuối tuần tuyệt đối không PHÁT SINH.
        "phat_sinh": 0 if is_weekend else int(cfg["phat_sinh_limit"]),
        "is_weekend": is_weekend,
    }


def _validate_daily_group_quota(all_leave_df, target_date, reason, is_zero_day_co_phep=False):
    """
    Trả (ok, message). Chỉ chặn quota của chính nhóm đang đăng ký:
      - Có phép không bị số Phát sinh ảnh hưởng.
      - Phát sinh không bị số Có phép ảnh hưởng.
    """
    group = _daily_leave_group(reason)
    limits = _daily_leave_quota_limits(target_date)
    counts = _daily_leave_quota_counts(all_leave_df, target_date)

    if group == "co_phep":
        if is_zero_day_co_phep:
            return True, ""
        if counts["co_phep"] >= limits["co_phep"]:
            return False, (
                f"Ngày {target_date.strftime('%d/%m/%Y')} đã đủ "
                f"{limits['co_phep']} người CÓ phép."
            )
        return True, ""

    if group == "phat_sinh":
        if limits["is_weekend"]:
            return False, (
                f"Ngày {target_date.strftime('%d/%m/%Y')} là cuối tuần "
                "(Thứ 7/Chủ nhật), không được đăng ký PHÁT SINH."
            )
        if counts["phat_sinh"] >= limits["phat_sinh"]:
            return False, (
                f"Ngày {target_date.strftime('%d/%m/%Y')} đã đủ "
                f"{limits['phat_sinh']} người PHÁT SINH."
            )
        return True, ""

    # Không phép / vi phạm khác không dùng quota Có phép hoặc Phát sinh.
    return True, ""



def _validate_daily_employee_registration_rule(df_sources, ngay, employee, new_reason, new_days):
    """
    V86.11 - Quy tắc bắt buộc cho MỘT NHÂN VIÊN trong MỘT NGÀY:

    1) Số ngày tính của một dòng đăng ký chỉ được 0, 0.5 hoặc 1.
    2) Chỉ được có tối đa 1 dòng có Số ngày tính > 0.
       Vì vậy 0.5 + 0.5 trong cùng ngày cũng bị chặn.
    3) Tối đa 1 dòng thuộc từng nhóm:
       - Có phép
       - Không phép
       - Phát sinh

    Các dòng Số ngày tính = 0 vẫn phải tuân thủ quy tắc không lặp nhóm.
    """
    try:
        new_days = float(new_days or 0)
    except Exception:
        new_days = 0.0

    # Chỉ chấp nhận đúng 0 / 0.5 / 1 cho đăng ký lịch nghỉ.
    allowed_day_values = (0.0, 0.5, 1.0)
    if not any(abs(new_days - x) < 1e-9 for x in allowed_day_values):
        return False, "Số ngày tính trong 1 ngày chỉ được phép là 0, 0.5 hoặc 1."

    target_dt = pd.to_datetime(ngay, errors="coerce", dayfirst=True)
    if pd.isna(target_dt):
        return False, "Không xác định được ngày đăng ký."
    target_date = target_dt.date()

    if df_sources is None or not isinstance(df_sources, pd.DataFrame) or df_sources.empty:
        return True, ""

    required = {"Ngày", "Tên nhân viên", "Lý do nghỉ"}
    if not required.issubset(set(df_sources.columns)):
        return True, ""

    d = df_sources.copy()
    d["_date_rule"] = pd.to_datetime(d["Ngày"], errors="coerce", dayfirst=True).dt.date
    d["_emp_rule"] = d["Tên nhân viên"].astype(str).apply(normalize_login_name)
    d = d[
        (d["_date_rule"] == target_date)
        & (d["_emp_rule"] == normalize_login_name(employee))
    ].copy()

    if d.empty:
        return True, ""

    # --- Quy tắc: trong ngày chỉ được 1 dòng có Số ngày tính > 0 ---
    if new_days > 0:
        if "Số ngày tính" in d.columns:
            existing_days = pd.to_numeric(d["Số ngày tính"], errors="coerce").fillna(0.0)
        else:
            existing_days = pd.Series([0.0] * len(d), index=d.index)

        positive_rows = d[existing_days > 0]
        if not positive_rows.empty:
            existing_desc = []
            for _, r in positive_rows.iterrows():
                try:
                    day_val = float(pd.to_numeric(r.get("Số ngày tính", 0), errors="coerce") or 0)
                except Exception:
                    day_val = 0.0
                existing_desc.append(
                    f"{clean_leave_reason_display(r.get('Lý do nghỉ', ''))} ({day_val:g} ngày)"
                )
            return False, (
                "Trong cùng 1 ngày, mỗi nhân viên chỉ được có 1 dòng có Số ngày tính > 0. "
                "Không cho phép 0.5 + 0.5 = 1. "
                f"Đã có: {', '.join(existing_desc)}."
            )

    # --- Quy tắc: không được có 2 lần cùng nhóm Có phép/Không phép/Phát sinh ---
    reason_type_map = _leave_reason_type_map(globals().get("df_loai_nghi", pd.DataFrame()))
    new_group = _daily_leave_group(new_reason, reason_type_map)

    if new_group:
        existing_groups = d["Lý do nghỉ"].astype(str).apply(
            lambda x: _daily_leave_group(x, reason_type_map)
        )
        same_group_rows = d[existing_groups == new_group]
        if not same_group_rows.empty:
            labels = {
                "co_phep": "CÓ phép",
                "khong_phep": "KHÔNG phép",
                "phat_sinh": "PHÁT SINH",
            }
            old_reasons = [
                clean_leave_reason_display(x)
                for x in same_group_rows["Lý do nghỉ"].astype(str).tolist()
                if clean_leave_reason_display(x)
            ]
            return False, (
                f"Trong cùng 1 ngày, một nhân viên không được có 2 lần {labels.get(new_group, new_group)}. "
                f"Đã có: {', '.join(old_reasons)}."
            )

    return True, ""


def _leave_exists_in_sources(df_sources, ngay, nv, loai_nghi):
    """
    Chỉ xem là TRÙNG khi cùng Ngày + cùng Nhân viên + cùng Lý do nghỉ.
    Vì vậy trong cùng một ngày, một nhân viên được phép có nhiều dòng vi phạm/phạt > 0
    nếu mỗi dòng là một Lý do nghỉ khác nhau.
    """
    if df_sources is None or df_sources.empty:
        return False
    target_date = pd.to_datetime(ngay, errors='coerce', dayfirst=True)
    if pd.isna(target_date):
        return False
    target_date = target_date.date()
    d = df_sources.copy()
    d['Ngày_cmp'] = pd.to_datetime(d['Ngày'], errors='coerce', dayfirst=True).dt.date
    name_cmp = d['Tên nhân viên'].astype(str).apply(normalize_login_name)
    reason_cmp = d['Lý do nghỉ'].astype(str).apply(normalize_leave_reason)
    return bool(((d['Ngày_cmp'] == target_date) &
                 (name_cmp == normalize_login_name(nv)) &
                 (reason_cmp == normalize_leave_reason(loai_nghi))).any())


def _progressive_ordinal_and_bonus(df_sources, ngay, loai_nghi):
    """
    Tính thứ tự RIÊNG cho từng loại vi phạm trong cùng ngày:
    - Nghỉ không phép
    - Đi trễ không phép
    - Về sớm không phép (kể cả biến thể Ra sớm không phép)

    Người 1/2: +0; Người 3: +100.000; Người 4: +200.000; ...
    """
    canonical = get_progressive_penalty_reason(loai_nghi)
    if canonical is None:
        return 1, 0

    target_date = pd.to_datetime(ngay, errors='coerce', dayfirst=True)
    if pd.isna(target_date) or df_sources is None or df_sources.empty:
        ordinal = 1
    else:
        target_date = target_date.date()
        d = df_sources.copy()
        d['Ngày_cmp'] = pd.to_datetime(d['Ngày'], errors='coerce', dayfirst=True).dt.date
        canonical_series = d['Lý do nghỉ'].astype(str).apply(get_progressive_penalty_reason)
        mask = (d['Ngày_cmp'] == target_date) & canonical_series.eq(canonical)
        ordinal = int(mask.sum()) + 1

    bonus = max(0, ordinal - 2) * 100000
    return ordinal, bonus


def _unexcused_ordinal_and_bonus(df_sources, ngay):
    """Alias tương thích code cũ cho riêng Nghỉ không phép."""
    return _progressive_ordinal_and_bonus(df_sources, ngay, "Nghỉ không phép")


def save_lich_nghi_to_backup_sheet(ngay, nv, loai_nghi, chi_tiet, so_ngay, so_ngay_cong_don, phat_vi_pham, updated_by, df_main_source=None):
    """
    V92.6.16: ghi DUY NHẤT vào Sheet1 chính theo schema A:M.
    Ghi theo header A1:M1 thực tế.
    """
    try:
        client = get_gspread_client()
        if not client:
            return False, "Chưa cấu hình quyền kết nối Google Sheets."

        now_vn = datetime.now(VN_TZ)
        ngay_cn = now_vn.strftime('%d/%m/%Y')
        gio_cn = now_vn.strftime('%H:%M:%S')

        sheet_dp = client.open_by_key(SHEET_DU_PHONG_ID).get_worksheet(0)
        sheet_headers = _ensure_leave_sheet_schema(sheet_dp)

        live_backup = _live_sheet_to_leave_df(sheet_dp)
        combined_live = combine_leave_sources_for_daily_stats(live_backup)

        if _leave_exists_in_sources(combined_live, ngay, nv, loai_nghi):
            return False, f"Nhân viên '{nv}' đã có đúng lý do '{clean_leave_reason_display(loai_nghi)}' trong ngày {ngay}. Lý do khác vẫn được phép ghi riêng."

        save_detail = str(chi_tiet).strip()
        save_penalty = float(phat_vi_pham) if phat_vi_pham is not None else 0.0
        ordinal_note = ""
        progressive_reason = get_progressive_penalty_reason(loai_nghi)
        if progressive_reason:
            ordinal, extra_penalty = _progressive_ordinal_and_bonus(combined_live, ngay, loai_nghi)
            ordinal_note = f"Người Thứ {ordinal} {progressive_reason.lower()}"
            save_detail = f"{ordinal_note} | {save_detail}" if save_detail else ordinal_note
            save_penalty += extra_penalty

        record = {
            'Ngày': normalize_schedule_date(ngay) or str(ngay),
            'Thứ ngày': _vn_weekday_label(ngay),
            'Tên nhân viên': str(nv),
            'Lý do nghỉ': clean_leave_reason_display(loai_nghi),
            'Loại nghỉ': _leave_type_for_reason(loai_nghi),
            'Chi tiết': save_detail,
            'Số ngày tính': float(so_ngay) if so_ngay is not None else 0.0,
            'Số ngày phép cộng dồn': float(so_ngay_cong_don),
            'Phạt vi phạm': save_penalty,
            'Ngày cập nhật': ngay_cn,
            'Giờ cập nhật': gio_cn,
            'Người cập nhật': str(updated_by),
        }
        row_values = _leave_record_to_sheet_row(record, sheet_headers=sheet_headers)
        target_row = _next_data_row_a_to_m(sheet_dp)
        gspread_update_range(sheet_dp, f"A{target_row}:M{target_row}", [row_values], value_input_option='USER_ENTERED')

        _clear_leave_data_caches()
        if ordinal_note:
            extra = max(0, save_penalty - float(phat_vi_pham or 0))
            return True, f"{ordinal_note}. Phạt lũy tiến cộng thêm {extra:,.0f} VNĐ; tổng phạt {save_penalty:,.0f} VNĐ."
        return True, "Đã ghi nhận lịch nghỉ thành công vào Sheet1 chính."
    except Exception as e:
        return False, f"Lỗi ghi dữ liệu: {e}"

def delete_backup_row(row_index_1_based, updated_by=None):
    """Xóa 1 dòng Sheet1 chính và tự xếp lại Người Thứ X/phạt lũy tiến nếu cần."""
    try:
        client = get_gspread_client()
        sheet = client.open_by_key(SHEET_DU_PHONG_ID).get_worksheet(0)
        actor = str(updated_by or st.session_state.get("current_user", "Hệ thống"))

        sheet_headers = _get_leave_sheet_headers(sheet, strict=True)
        row_values = sheet.get(f'A{row_index_1_based}:M{row_index_1_based}')
        affected_groups = set()
        if row_values and row_values[0]:
            deleted_row = _leave_sheet_row_to_record(row_values[0], sheet_headers)
            deleted_row['__source_sheet_id'] = SHEET_DU_PHONG_ID
            deleted_row['__source_row'] = int(row_index_1_based)
            group_key = _progressive_group_key(deleted_row)
            if group_key:
                affected_groups.add(group_key)

        sheet.delete_rows(row_index_1_based)
        rebalanced = rebalance_progressive_penalty_groups(client, affected_groups, actor) if affected_groups else 0
        _clear_leave_data_caches()
        if rebalanced:
            return True, f"Đã xóa lịch nghỉ và tự xếp lại thứ tự/phạt cho {rebalanced} bản ghi còn lại."
        return True, "Đã xóa lịch nghỉ thành công!"
    except Exception as e:
        return False, f"Lỗi xóa dòng: {e}"

def _find_schedule_row_index(sheet, original_row):
    """Tìm dòng vật lý theo Ngày + Nhân viên + Lý do trong schema A:M."""
    target_key = schedule_key(original_row)
    if not target_key:
        return None
    data = _read_leave_sheet_with_source(sheet, SHEET_DU_PHONG_ID)
    if data is None or data.empty:
        return None
    for _, row in data.iterrows():
        if schedule_key(row) == target_key:
            try:
                return int(float(row.get('__source_row')))
            except Exception:
                return None
    return None

def _parse_leave_number(value, default=0.0, money=False):
    """Chuẩn hóa số lấy từ sheet LoaiNghi, hỗ trợ dấu chấm/phẩy và ký hiệu tiền."""
    try:
        if value is None or pd.isna(value):
            return float(default)
        s = str(value).strip()
        if s.lower() in ["", "-", "nan", "none", "nat"]:
            return float(default)
        if money:
            s = (s.replace('.', '').replace(',', '').replace(' ', '')
                   .replace('đ', '').replace('Đ', '').replace('VNĐ', '').replace('VND', ''))
        else:
            s = s.replace(',', '.')
        return float(s)
    except Exception:
        return float(default)


def _leave_policy_row_value(row, aliases, fallback_idx=None, default=""):
    """Đọc field LoaiNghi theo HEADER động; hỗ trợ cả header cũ và typo hiện hữu."""
    aliases = [aliases] if isinstance(aliases, str) else list(aliases or [])
    try:
        normalized_columns = {
            normalize_login_name(col): col for col in list(getattr(row, "index", []))
        }
        for alias in aliases:
            actual = normalized_columns.get(normalize_login_name(alias))
            if actual is not None:
                value = row.get(actual, default)
                try:
                    if pd.isna(value):
                        continue
                except Exception:
                    pass
                return value
    except Exception:
        pass

    if fallback_idx is not None:
        try:
            vals = row.tolist()
            if 0 <= int(fallback_idx) < len(vals):
                value = vals[int(fallback_idx)]
                try:
                    if pd.isna(value):
                        return default
                except Exception:
                    pass
                return value
        except Exception:
            pass
    return default


def _leave_policy_clean_text(value):
    try:
        if pd.isna(value):
            return ""
    except Exception:
        pass
    text = str(value or "").strip()
    return "" if text.casefold() in {"nan", "none", "nat", "<na>"} else text


def _leave_policy_role_tokens(raw_value):
    """Tách danh sách role ở H/K/N; chấp nhận cả 'ngoại trừ ...' và list thuần."""
    norm = normalize_login_name(raw_value)
    if not norm or norm in {"nan", "none", "tat ca", "all"}:
        return set()
    known = [
        "admin", "quanly", "letan", "leader", "nhanvien",
        "locker", "tapvu", "auto update",
    ]
    return {role for role in known if role in norm}


def build_leave_reason_catalog(source_df=None):
    """
    Rule Engine LoaiNghi V2 — đọc A:N theo HEADER thực tế.

    A STT
    B Lý do nghỉ
    C Loại nghỉ
    D Chi tiết
    E Số ngày tính phép
    F Phạt vi phạm
    G Chỉ nhập được cuối tuần / ngày được phép nhập
    H User có quyền được nhập
    I Kiểu đăng ký (sheet hiện tại đang ghi 'Kiều đăng ký' — code chấp nhận cả 2)
    J Giá trị
    K Ngoại trừ đăng ký
    L Kiểu hủy
    M Số ngày hủy trước / Giá trị hủy
    N Ngoại trừ hủy

    Từ bản này không gắn rule thời gian vào tên Lý do nghỉ. Thêm/đổi Lý do hoặc
    thay số ngày/giờ/ngoại lệ chỉ cần sửa LoaiNghi.
    """
    source = source_df if source_df is not None else globals().get("df_loai_nghi", pd.DataFrame())
    catalog = {}
    if source is None or source.empty:
        return catalog

    for _, row in source.iterrows():
        name = clean_leave_reason_display(_leave_policy_clean_text(
            _leave_policy_row_value(row, ["Lý do nghỉ", "Loại nghỉ"], 1, "")
        ))
        if not name or normalize_login_name(name) in {"loai nghi", "ly do nghi", "none", "nan"}:
            continue

        detail = _leave_policy_clean_text(
            _leave_policy_row_value(row, "Chi tiết", 3, "")
        )
        days = _parse_leave_number(
            _leave_policy_row_value(row, ["Số ngày tính phép", "Số ngày tính"], 4, 0),
            0.0,
            money=False,
        )
        penalty_raw = _leave_policy_row_value(row, "Phạt vi phạm", 5, "")
        penalty = _parse_leave_number(penalty_raw, 0.0, money=True)
        penalty_text = _leave_policy_clean_text(penalty_raw)

        item = {
            "name": name,
            "leave_type": _leave_policy_clean_text(
                _leave_policy_row_value(row, "Loại nghỉ", 2, "")
            ),
            "detail": detail,
            "days": float(days),
            "penalty": float(penalty),
            "penalty_configured": penalty_text.casefold() not in {"", "-", "nan", "none", "nat"},
            "allowed_days": _leave_policy_clean_text(
                _leave_policy_row_value(
                    row,
                    ["Chỉ nhập được cuối tuần", "Ngày được phép nhập", "Ngày được nhập"],
                    6,
                    "",
                )
            ),
            "allowed_roles": _leave_policy_clean_text(
                _leave_policy_row_value(row, "User có quyền được nhập", 7, "")
            ),
            "register_type": _leave_policy_clean_text(
                _leave_policy_row_value(row, ["Kiểu đăng ký", "Kiều đăng ký"], 8, "")
            ),
            "register_value": _leave_policy_clean_text(
                _leave_policy_row_value(row, ["Giá trị", "Giá trị đăng ký"], 9, "")
            ),
            "register_exceptions": _leave_policy_clean_text(
                _leave_policy_row_value(row, "Ngoại trừ đăng ký", 10, "")
            ),
            "cancel_type": _leave_policy_clean_text(
                _leave_policy_row_value(row, "Kiểu hủy", 11, "")
            ),
            "cancel_value": _leave_policy_clean_text(
                _leave_policy_row_value(row, ["Số ngày hủy trước", "Giá trị hủy"], 12, "")
            ),
            "cancel_exceptions": _leave_policy_clean_text(
                _leave_policy_row_value(row, "Ngoại trừ hủy", 13, "")
            ),
        }

        # Alias tương thích cho các đoạn code/caption cũ nếu còn gọi.
        item["register_notice"] = item["register_type"]
        item["cancel_notice"] = item["cancel_type"]
        catalog[normalize_leave_reason(name)] = item
    return catalog


def _leave_notice_policy_item(reason, source_df=None):
    catalog = build_leave_reason_catalog(
        source_df if isinstance(source_df, pd.DataFrame)
        else globals().get("df_loai_nghi", pd.DataFrame())
    )
    item = catalog.get(normalize_leave_reason(reason))
    if item:
        return item
    wanted = normalize_login_name(clean_leave_reason_display(reason))
    for candidate in catalog.values():
        if normalize_login_name(candidate.get("name", "")) == wanted:
            return candidate
    return None


def _leave_policy_number(value):
    text = _leave_policy_clean_text(value).replace(",", ".")
    m = re.search(r"-?\d+(?:\.\d+)?", text)
    if not m:
        return None
    try:
        return float(m.group(0))
    except Exception:
        return None


def _leave_policy_time(value):
    """Đọc 9:00, 09:00, 9h00; trả (hour, minute) hoặc None."""
    text = normalize_login_name(_leave_policy_clean_text(value))
    m = re.search(r"\b(\d{1,2})\s*(?::|h)\s*(\d{1,2})?\b", text)
    if not m:
        # Cho phép chỉ nhập 9 / 09 ở cột Giá trị.
        m2 = re.fullmatch(r"\s*(\d{1,2})\s*", text)
        if not m2:
            return None
        hour, minute = int(m2.group(1)), 0
    else:
        hour, minute = int(m.group(1)), int(m.group(2) or 0)
    if not (0 <= hour <= 23 and 0 <= minute <= 59):
        return None
    return hour, minute


def _parse_leave_policy_rule(rule_type, rule_value="", rule_kind="register"):
    """Biến I/J hoặc L/M thành rule machine-readable, không phụ thuộc tên Lý do nghỉ."""
    raw_type = _leave_policy_clean_text(rule_type)
    raw_value = _leave_policy_clean_text(rule_value)
    norm = normalize_login_name(raw_type)

    if not raw_type:
        return {"mode": "blank", "raw_type": "", "raw_value": raw_value}

    if "khong gioi han" in norm:
        return {"mode": "unlimited", "raw_type": raw_type, "raw_value": raw_value}

    if "truoc n ngay" in norm or norm in {"truoc ngay", "before days"}:
        num = _leave_policy_number(raw_value)
        if num is None:
            return {"mode": "invalid", "raw_type": raw_type, "raw_value": raw_value}
        return {
            "mode": "days_before",
            "days": max(0, int(num)),
            "raw_type": raw_type,
            "raw_value": raw_value,
        }

    if rule_kind == "register" and "ngay hien tai tu gio" in norm:
        hm = _leave_policy_time(raw_value)
        if hm is None:
            return {"mode": "invalid", "raw_type": raw_type, "raw_value": raw_value}
        return {
            "mode": "same_day_after",
            "hour": hm[0],
            "minute": hm[1],
            "raw_type": raw_type,
            "raw_value": raw_value,
        }

    if rule_kind == "cancel" and "khong duoc huy ngay hien tai" in norm:
        return {"mode": "no_same_day", "raw_type": raw_type, "raw_value": raw_value}

    if (
        "khong cho phep" in norm
        or (rule_kind == "register" and "khong duoc dang ky" in norm)
        or (rule_kind == "cancel" and "khong duoc huy" in norm)
    ):
        return {"mode": "deny", "raw_type": raw_type, "raw_value": raw_value}

    # Tương thích dữ liệu cũ nếu trước đây ô rule chỉ chứa số hoặc câu gộp.
    numeric = _leave_policy_number(raw_type)
    if numeric is not None and re.fullmatch(r"\s*\d+(?:[.,]\d+)?\s*(?:ngay)?\s*", norm):
        return {
            "mode": "days_before",
            "days": max(0, int(numeric)),
            "raw_type": raw_type,
            "raw_value": raw_value,
        }
    if rule_kind == "register" and "ngay hien tai" in norm and "tu" in norm:
        hm = _leave_policy_time(raw_type)
        if hm is not None:
            return {
                "mode": "same_day_after",
                "hour": hm[0],
                "minute": hm[1],
                "raw_type": raw_type,
                "raw_value": raw_value,
            }

    return {"mode": "unknown", "raw_type": raw_type, "raw_value": raw_value}


def leave_notice_policy_text(reason):
    item = _leave_notice_policy_item(reason)
    if not item:
        return ""

    def _fmt(kind):
        if kind == "register":
            typ = item.get("register_type", "") or "(chưa cấu hình)"
            val = item.get("register_value", "")
            exc = item.get("register_exceptions", "")
        else:
            typ = item.get("cancel_type", "") or "(chưa cấu hình)"
            val = item.get("cancel_value", "")
            exc = item.get("cancel_exceptions", "")
        out = typ
        if val:
            out += f" · {val}"
        if exc:
            out += f" · ngoại lệ: {exc}"
        return out

    return f"Đăng ký: **{_fmt('register')}** · Hủy: **{_fmt('cancel')}**"


def _leave_allowed_role_tokens(raw_value):
    # Giữ tên hàm cũ cho các call hiện hữu.
    return _leave_policy_role_tokens(raw_value)


def _leave_day_rule_matches(raw_value, target_date):
    """Kiểm cột G của LoaiNghi theo đúng thứ/ngày thực tế."""
    norm = normalize_login_name(raw_value)
    if not norm or norm in {"nan", "none", "tat ca", "all"}:
        return True
    if not isinstance(target_date, date):
        return False
    weekday_tokens = {
        0: ["thu hai", "t2"],
        1: ["thu ba", "t3"],
        2: ["thu tu", "t4"],
        3: ["thu nam", "t5"],
        4: ["thu sau", "t6"],
        5: ["thu bay", "t7", "cuoi tuan"],
        6: ["chu nhat", "cn", "cuoi tuan"],
    }
    return any(token in norm for token in weekday_tokens.get(target_date.weekday(), []))


def validate_leave_reason_catalog_access(reason, target_date, role=None):
    """
    Quyền nền từ LoaiNghi:
      G = ngày được phép nhập
      H = role được phép nhập
    Ngoại trừ K/N chỉ miễn RULE THỜI GIAN, không tự cấp quyền H và không bỏ rule G.
    """
    role = str(
        role if role is not None else st.session_state.get("current_role", "")
    ).strip().lower()
    if role == "admin":
        return True, ""

    item = _leave_notice_policy_item(reason)
    if not item:
        return False, f"Không tìm thấy Lý do nghỉ '{clean_leave_reason_display(reason)}' trong LoaiNghi."

    allowed_roles = _leave_policy_role_tokens(item.get("allowed_roles", ""))
    if allowed_roles and role not in allowed_roles:
        return False, (
            f"Tài khoản {role} không được phép nhập lý do '{item.get('name', reason)}' "
            "theo cột 'User có quyền được nhập'."
        )

    if not _leave_day_rule_matches(item.get("allowed_days", ""), target_date):
        return False, (
            f"'{item.get('name', reason)}' không được nhập vào "
            f"{_vn_weekday_label(target_date)} {target_date.strftime('%d/%m/%Y')} "
            "theo cột quy định ngày của LoaiNghi."
        )
    return True, ""


def validate_leave_registration_notice(reason, target_date, role=None, now_vn=None):
    """Kiểm đăng ký động theo G/H + I/J/K của LoaiNghi."""
    role = str(role if role is not None else st.session_state.get("current_role", "")).strip().lower()
    if role == "admin":
        return True, ""
    if not isinstance(target_date, date):
        return False, "Ngày đăng ký không hợp lệ."

    access_ok, access_msg = validate_leave_reason_catalog_access(reason, target_date, role=role)
    if not access_ok:
        return False, access_msg

    now_vn = now_vn or datetime.now(VN_TZ)
    today = now_vn.date()
    if target_date < today:
        return False, "Không được đăng ký lịch ở ngày quá khứ."

    item = _leave_notice_policy_item(reason)
    if not item:
        return False, f"Không tìm thấy cấu hình LoaiNghi cho '{clean_leave_reason_display(reason)}'."

    # K = ngoại trừ đăng ký: miễn rule I/J nhưng vẫn phải thỏa G/H và không đăng ký quá khứ.
    register_exceptions = _leave_policy_role_tokens(item.get("register_exceptions", ""))
    if role in register_exceptions:
        return True, ""

    rule = _parse_leave_policy_rule(
        item.get("register_type", ""), item.get("register_value", ""), "register"
    )
    mode = rule.get("mode")

    if mode == "days_before":
        days = int(rule.get("days", 0))
        min_date = today + timedelta(days=days)
        if target_date < min_date:
            return False, (
                f"'{item.get('name', reason)}' phải đăng ký trước ít nhất {days} ngày. "
                f"Ngày sớm nhất được đăng ký là {min_date.strftime('%d/%m/%Y')}."
            )
        return True, ""

    if mode == "same_day_after":
        hh, mm = int(rule.get("hour", 0)), int(rule.get("minute", 0))
        if target_date != today:
            return False, (
                f"'{item.get('name', reason)}' chỉ được đăng ký cho ngày hiện tại từ "
                f"{hh:02d}:{mm:02d}."
            )
        cutoff = now_vn.replace(hour=hh, minute=mm, second=0, microsecond=0)
        if now_vn < cutoff:
            return False, f"'{item.get('name', reason)}' chỉ được đăng ký từ {cutoff.strftime('%H:%M')} hôm nay."
        return True, ""

    if mode == "unlimited":
        return True, ""
    if mode == "deny":
        return False, f"'{item.get('name', reason)}' đang được cấu hình không cho phép đăng ký."
    if mode == "blank":
        return False, f"LoaiNghi chưa cấu hình 'Kiểu đăng ký' cho '{item.get('name', reason)}'."

    return False, (
        f"Không nhận diện được Kiểu đăng ký '{rule.get('raw_type', '')}' / "
        f"Giá trị '{rule.get('raw_value', '')}' của '{item.get('name', reason)}'."
    )


def validate_leave_cancel_notice(reason, target_date, role=None, today=None):
    """Kiểm hủy/sửa động theo L/M/N của LoaiNghi."""
    role = str(role if role is not None else st.session_state.get("current_role", "")).strip().lower()
    if role == "admin":
        return True, ""
    today = today or get_vn_today()
    if not isinstance(target_date, date):
        return False, "Ngày lịch nghỉ không hợp lệ."
    if target_date < today:
        return False, "Không được hủy/thay đổi lịch trong quá khứ."

    item = _leave_notice_policy_item(reason)
    if not item:
        return False, f"Không tìm thấy cấu hình LoaiNghi cho '{clean_leave_reason_display(reason)}'."

    # N = ngoại trừ hủy: miễn rule L/M nhưng không bỏ quyền chức năng và không cho xóa quá khứ.
    cancel_exceptions = _leave_policy_role_tokens(item.get("cancel_exceptions", ""))
    if role in cancel_exceptions:
        return True, ""

    rule = _parse_leave_policy_rule(
        item.get("cancel_type", ""), item.get("cancel_value", ""), "cancel"
    )
    mode = rule.get("mode")

    if mode == "days_before":
        days = int(rule.get("days", 0))
        min_date = today + timedelta(days=days)
        if target_date < min_date:
            return False, (
                f"'{item.get('name', reason)}' phải hủy/thay đổi trước ít nhất {days} ngày. "
                f"Chỉ xử lý lịch từ {min_date.strftime('%d/%m/%Y')} trở đi."
            )
        return True, ""

    if mode == "no_same_day":
        if target_date == today:
            return False, f"'{item.get('name', reason)}' không được hủy/thay đổi trong ngày hiện tại."
        return True, ""

    if mode == "unlimited":
        return True, ""
    if mode == "deny":
        return False, f"'{item.get('name', reason)}' đang được cấu hình không cho phép hủy."

    if mode == "blank":
        # Tương thích an toàn với các dòng Phát sinh hiện đang để trống Kiểu hủy:
        # Leader/Nhân viên không được tự hủy; Lễ tân/Quản lý vẫn có thể xử lý nếu đã có quyền chức năng.
        if role in {"letan", "quanly"}:
            return True, ""
        return False, (
            f"'{item.get('name', reason)}' chưa cấu hình 'Kiểu hủy'. "
            "Nhân viên/Leader không được tự hủy/thay đổi lý do này."
        )

    return False, (
        f"Không nhận diện được Kiểu hủy '{rule.get('raw_type', '')}' / "
        f"Giá trị '{rule.get('raw_value', '')}' của '{item.get('name', reason)}'."
    )


# ==========================================================
# V84 - AUTO UPDATE VI PHẠM: BẢNG TOUR + TIMESOFT
# ==========================================================
def _auto_penalty_catalog_item(reason_name, catalog=None):
    catalog = catalog if catalog is not None else build_leave_reason_catalog(globals().get('df_loai_nghi', pd.DataFrame()))
    exact = catalog.get(normalize_leave_reason(reason_name))
    if exact:
        return exact
    wanted = normalize_login_name(reason_name)
    for item in catalog.values():
        if normalize_login_name(item.get('name', '')) == wanted:
            return item
    return None

def _canonical_system_employee_name(raw_name):
    """Đối chiếu tên nguồn ngoài với Tên nhân viên hệ thống; bỏ dấu * ở cuối khi so sánh."""
    cleaned = clean_employee_match_name(raw_name)
    if not cleaned:
        return ""
    creds = globals().get('df_credentials', pd.DataFrame())
    if isinstance(creds, pd.DataFrame) and not creds.empty and 'Tên nhân viên' in creds.columns:
        target = normalize_employee_match_name(cleaned)
        for name in creds['Tên nhân viên'].dropna().astype(str).tolist():
            if normalize_employee_match_name(name) == target:
                # Luôn ghi tên chuẩn đang lưu trong hệ thống, không ghi dấu * từ Bảng tour.
                return str(name).strip()
        # Có danh sách nhân sự nhưng không khớp -> không tự tạo bản ghi phạt sai tên.
        return ""
    # Fallback chỉ dùng khi bảng hồ sơ chưa tải được.
    return cleaned

def _tour_late_minutes(value):
    """Đọc cột Vào trễ thành số phút; hỗ trợ số phút, timedelta, time và chuỗi HH:MM[:SS]."""
    try:
        if value is None or pd.isna(value):
            return None
    except Exception:
        pass
    if isinstance(value, timedelta):
        return max(0.0, value.total_seconds() / 60.0)
    # pandas Timedelta
    try:
        if isinstance(value, pd.Timedelta):
            return max(0.0, value.total_seconds() / 60.0)
    except Exception:
        pass
    # datetime.time hoặc datetime/datetime-like.
    if hasattr(value, 'hour') and hasattr(value, 'minute') and not isinstance(value, numbers.Number):
        try:
            return max(0.0, float(value.hour * 60 + value.minute + getattr(value, 'second', 0) / 60.0))
        except Exception:
            pass
    text = str(value).strip()
    if not text or text.casefold() in {'nan', 'none', 'nat', '<na>'}:
        return None
    # Nếu là số thuần thì Bảng tour đang lưu trực tiếp số phút.
    try:
        return max(0.0, float(text.replace(',', '.')))
    except Exception:
        pass
    m = re.fullmatch(r'\s*(\d{1,3}):(\d{1,2})(?::(\d{1,2}))?\s*', text)
    if m:
        h, mi, sec = int(m.group(1)), int(m.group(2)), int(m.group(3) or 0)
        return max(0.0, h * 60 + mi + sec / 60.0)
    # Chuỗi dạng "5 phút", "10 min"...
    m = re.search(r'(-?\d+(?:[\.,]\d+)?)', text)
    if m:
        try:
            return max(0.0, float(m.group(1).replace(',', '.')))
        except Exception:
            pass
    return None

def _outside_late_reason_for_minutes(minutes, catalog=None):
    """Chọn đúng bậc Ra ngoài vào muộn theo số phút và ưu tiên tên đang cấu hình trong LoaiNghi."""
    try:
        m = float(minutes)
    except Exception:
        return None
    if m < AUTO_PENALTY_MINUTES:
        return None
    if m < 30:
        candidates = ["Ra ngoài vào muộn dưới 30 phút"]
    elif m < 60:
        candidates = ["Ra ngoài vào muộn dưới 60 phút"]
    elif m < 120:
        candidates = ["Ra ngoài vào muộn dưới 120 phút"]
    else:
        # Nếu danh mục có bậc >=120 thì dùng đúng bậc đó; nếu chưa có, dùng bậc cao nhất hiện tại.
        candidates = [
            "Ra ngoài vào muộn từ 120 phút trở lên",
            "Ra ngoài vào muộn trên 120 phút",
            "Ra ngoài vào muộn dưới 120 phút",
        ]
    for reason in candidates:
        item = _auto_penalty_catalog_item(reason, catalog)
        if item:
            return item.get('name', reason)
    return None

def _auto_result(source):
    return {
        "source": source, "added": 0, "skipped": 0, "errors": 0,
        "eligible": 0, "messages": [], "paused": False, "unmatched": []
    }

CA1_CLEANING_REASON = "KHÔNG dọn vệ sinh ca 1"
CA1_LATE_REASON_KEYS = {
    normalize_login_name("Đi trễ nhỏ hơn hoặc bằng 30 phút"),
    normalize_login_name("Đi trễ nhỏ hơn hoặc bằng 60 phút"),
    normalize_login_name("Đi trễ lớn 60 phút và nhỏ hơn hoặc bằng 120 phút"),
}
CA1_SUPPORT_REASON_KEYS = {
    normalize_login_name("Hỗ trợ Ca 1 đi trễ 2 tiếng"),
    normalize_login_name("Hỗ trợ Ca 1 đi trễ 3 tiếng"),
    normalize_login_name("Hỗ trợ Ca 2 đi trễ 1 tiếng"),
}


def _shift_base_number(value):
    key = normalize_login_name(value)
    if "ca 1" in key:
        return 1
    if "ca 2" in key:
        return 2
    return None


def _credential_effective_shift_for_week(cred_row, target_date=None):
    """Xác định ca đang làm của cả tuần dựa trên cấu hình Ca/Ngày bắt đầu/Chu kỳ."""
    target_date = target_date or get_vn_today()
    monday = target_date - timedelta(days=target_date.weekday())
    base = _shift_base_number(cred_row.get("Ca làm việc", ""))
    if base not in {1, 2}:
        return None

    shift_key = normalize_login_name(cred_row.get("Ca làm việc", ""))
    cycle_key = normalize_login_name(cred_row.get("Chu kỳ", ""))
    if "co dinh" in shift_key or "co dinh" in cycle_key:
        return base

    raw_start = cred_row.get("Ngày bắt đầu ca", "")
    try:
        anchor_dt = pd.to_datetime(raw_start, dayfirst=True, errors="coerce")
        anchor = anchor_dt.date() if pd.notna(anchor_dt) else None
    except Exception:
        anchor = None
    if not anchor or monday <= anchor:
        return base

    if "14 ngay" in cycle_key or "luan phien" in cycle_key:
        periods = max(0, (monday - anchor).days // 14)
    elif "thang" in cycle_key:
        periods = max(0, (monday.year - anchor.year) * 12 + monday.month - anchor.month)
    else:
        return base
    return base if periods % 2 == 0 else (2 if base == 1 else 1)


def auto_update_ca1_cleaning_from_leave_data(actor="AUTO UPDATE - CA1"):
    """Auto ghi 'KHÔNG dọn vệ sinh ca 1' cho dữ liệu hôm nay theo quy tắc V84.7.

    Điều kiện đồng thời:
    1) Role nhanvien và ca hiệu lực của tuần hiện tại là Ca 1.
    2) Hôm nay có một trong 3 loại Đi trễ 30/60/120 đã chỉ định.
    3) Hôm nay KHÔNG có một trong 3 loại Hỗ trợ Ca đi trễ đã chỉ định.
    """
    result = _auto_result("KHÔNG dọn vệ sinh ca 1")
    cfg = load_auto_penalty_config()
    if cfg.get("paused"):
        result["paused"] = True
        result["messages"].append("Auto Update đang tạm dừng bởi Admin.")
        return result

    try:
        leave_df = _load_backup_sheet_data_from_sheets()
    except Exception as exc:
        result["errors"] += 1
        result["messages"].append(f"Không đọc được lịch nghỉ LIVE: {exc}")
        return result

    if leave_df.empty:
        return result

    today = get_vn_today()
    day_key = today.strftime("%d/%m/%Y")
    d = leave_df.copy()
    d["__date"] = pd.to_datetime(d.get("Ngày"), dayfirst=True, errors="coerce").dt.date
    d = d[d["__date"].eq(today)].copy()
    if d.empty:
        return result
    d["__emp"] = d.get("Tên nhân viên", "").astype(str).apply(normalize_login_name)
    d["__reason"] = d.get("Lý do nghỉ", "").astype(str).apply(normalize_login_name)

    late_by_emp = {}
    support_by_emp = {}
    for _, r in d.iterrows():
        ekey = str(r.get("__emp", "")).strip()
        rkey = str(r.get("__reason", "")).strip()
        reason_display = str(r.get("Lý do nghỉ", "") or "").strip()
        if not ekey:
            continue
        if rkey in CA1_LATE_REASON_KEYS:
            late_by_emp.setdefault(ekey, []).append(reason_display)
        if rkey in CA1_SUPPORT_REASON_KEYS:
            support_by_emp.setdefault(ekey, []).append(reason_display)

    if not late_by_emp:
        return result

    try:
        creds = load_credentials_fresh()
    except Exception:
        creds = globals().get("df_credentials", pd.DataFrame())
    if creds is None or creds.empty:
        result["errors"] += 1
        result["messages"].append("Không đọc được cấu hình ca nhân viên.")
        return result

    catalog = build_leave_reason_catalog(globals().get("df_loai_nghi", pd.DataFrame()))
    reason_item = _auto_penalty_catalog_item(CA1_CLEANING_REASON, catalog)
    if not reason_item:
        result["errors"] += 1
        result["messages"].append(f"Sheet LoaiNghi chưa có '{CA1_CLEANING_REASON}'.")
        return result

    for _, cred in creds.iterrows():
        if str(cred.get("Phân quyền", "")).strip().lower() != "nhanvien":
            continue
        employee = str(cred.get("Tên nhân viên", "") or "").strip()
        ekey = normalize_login_name(employee)
        if ekey not in late_by_emp:
            continue
        if _credential_effective_shift_for_week(cred, today) != 1:
            result["skipped"] += 1
            continue

        result["eligible"] += 1
        if support_by_emp.get(ekey):
            result["skipped"] += 1
            result["messages"].append(
                f"{employee}: bỏ qua vì có {support_by_emp[ekey][0]}."
            )
            continue

        late_reason = late_by_emp[ekey][0]
        week_start = today - timedelta(days=today.weekday())
        week_end = week_start + timedelta(days=6)
        detail = (
            f"Auto Update Ca 1 · tuần {week_start.strftime('%d/%m')}–{week_end.strftime('%d/%m/%Y')} · "
            f"phát hiện '{late_reason}' · không có Hỗ trợ Ca đi trễ"
        )
        ok, msg = save_lich_nghi_to_backup_sheet(
            day_key,
            employee,
            reason_item.get("name", CA1_CLEANING_REASON),
            detail,
            float(reason_item.get("days", 0) or 0),
            0.0,
            float(reason_item.get("penalty", 0) or 0),
            actor,
            df_main_source=_load_live_leave_registration_for_validation(),
        )
        if ok:
            result["added"] += 1
        elif "không được đăng ký trùng" in str(msg).lower() or "đã có loại nghỉ" in str(msg).lower():
            result["skipped"] += 1
        else:
            result["errors"] += 1
            result["messages"].append(f"{employee}: {msg}")
    return result


def auto_update_outside_late_from_tour(df_tour, actor="AUTO UPDATE - BẢNG TOUR"):
    """
    Tự ghi vi phạm Ra ngoài vào muộn từ Bảng tour.
    Chỉ xử lý khi cột `Vào trễ` >= 5 phút. `Cẩm Nhung *` được đối chiếu như `Cẩm Nhung`.
    """
    result = _auto_result("Bảng tour")
    cfg = load_auto_penalty_config()
    if cfg.get('paused'):
        result['paused'] = True
        result['messages'].append('Auto Update đang tạm dừng bởi Admin.')
        return result
    if not isinstance(df_tour, pd.DataFrame) or df_tour.empty:
        return result

    late_col = _find_tour_col(df_tour, "Vào trễ")
    name_col = _find_tour_col(df_tour, "Tên nhân viên") or _find_tour_col(df_tour, "Tên Nhân Viên")
    out_col = _find_tour_col(df_tour, "Giờ ra")
    in_col = _find_tour_col(df_tour, "Giờ vào")
    if late_col is None or name_col is None:
        result['errors'] += 1
        result['messages'].append("Bảng tour chưa có cột 'Vào trễ' hoặc 'Tên nhân viên'.")
        return result

    catalog = build_leave_reason_catalog(globals().get('df_loai_nghi', pd.DataFrame()))
    threshold = max(AUTO_PENALTY_MINUTES, int(cfg.get('threshold_minutes', AUTO_PENALTY_MINUTES) or AUTO_PENALTY_MINUTES))
    today = get_vn_today()
    main_source = _load_live_leave_registration_for_validation()

    for _, row in df_tour.iterrows():
        minutes = _tour_late_minutes(row.get(late_col, ""))
        if minutes is None or float(minutes) < threshold:
            continue
        result['eligible'] += 1
        raw_name = row.get(name_col, "")
        employee = _canonical_system_employee_name(raw_name)
        if not employee:
            result['skipped'] += 1
            result['unmatched'].append(str(raw_name or '(không có tên)'))
            continue
        reason = _outside_late_reason_for_minutes(minutes, catalog)
        if not reason:
            result['errors'] += 1
            result['messages'].append(
                f"{employee}: chưa tìm thấy loại 'Ra ngoài vào muộn' phù hợp trong sheet LoaiNghi."
            )
            continue
        item = _auto_penalty_catalog_item(reason, catalog) or {}
        base_penalty = float(item.get('penalty', 0) or 0)
        days = float(item.get('days', 0) or 0)
        details = [f"Auto Update Bảng tour · vào muộn {int(round(float(minutes)))} phút"]
        if out_col is not None and str(row.get(out_col, '')).strip():
            details.append(f"Giờ ra {str(row.get(out_col)).strip()}")
        if in_col is not None and str(row.get(in_col, '')).strip():
            details.append(f"Giờ vào {str(row.get(in_col)).strip()}")
        ok, msg = save_lich_nghi_to_backup_sheet(
            today.strftime('%d/%m/%Y'), employee, reason, " · ".join(details),
            days, 0.0, base_penalty, actor, df_main_source=main_source
        )
        if ok:
            result['added'] += 1
        elif 'không được đăng ký trùng' in str(msg).lower() or 'đã có loại nghỉ' in str(msg).lower():
            result['skipped'] += 1
        else:
            result['errors'] += 1
            result['messages'].append(f"{employee}: {msg}")
    return result

def _timesoft_row_value(row, candidates):
    for c in candidates:
        if c in row.index:
            val = row.get(c)
            if val is not None and str(val).strip().casefold() not in {"", "nan", "none", "nat"}:
                return val
    return ""

def _parse_minutes_late_from_timesoft_row(row):
    direct = _timesoft_row_value(row, [
        'TotalMinuteInGoLate', 'TotalMinuteGoLate', 'MinuteInGoLate', 'GoLateMinute', 'LateMinute'
    ])
    try:
        if str(direct).strip() != "":
            return max(0.0, float(str(direct).replace(',', '.').strip()))
    except Exception:
        pass

    # Fallback: tự so giờ check-in với giờ bắt đầu ca nếu TimeSoft không trả cột phút trễ.
    start = _timesoft_row_value(row, ['StartWorkTime', 'WorkTimeStart', 'ShiftStartTime'])
    checkin = _timesoft_row_value(row, ['MachineTimeCheckInStr', 'CheckInTimeStr', 'CheckInTime'])
    if not start or not checkin:
        return None
    def _time_minutes(v):
        text = str(v).strip()
        m = re.search(r'(\d{1,2}):(\d{2})(?::(\d{2}))?', text)
        if not m:
            return None
        h, mi = int(m.group(1)), int(m.group(2))
        return h * 60 + mi
    sm = _time_minutes(start)
    cm = _time_minutes(checkin)
    if sm is None or cm is None:
        return None
    diff = cm - sm
    if diff < -12 * 60:
        diff += 24 * 60
    return max(0.0, float(diff))

TIMESOFT_SUPPORT_LATE_ALLOWANCES = {
    normalize_login_name("Hỗ trợ Ca 1 đi trễ 2 tiếng"): 120,
    normalize_login_name("Hỗ trợ Ca 1 sau 0:0H đi trễ 3 tiếng"): 180,
    normalize_login_name("Hỗ trợ Ca 2 sau 0:0H đi trễ 1 tiếng"): 60,
}


def _timesoft_support_for_day(employee, target_date):
    """Đọc Hỗ trợ cùng Ngày + Nhân viên từ dữ liệu lịch nghỉ đã hợp nhất."""
    data = globals().get("df_backup")
    if not isinstance(data, pd.DataFrame) or data.empty:
        return [], 0, ""
    data = data.copy()
    if "Ngày" not in data.columns or "Tên nhân viên" not in data.columns or "Lý do nghỉ" not in data.columns:
        return [], 0, ""

    td = pd.to_datetime(target_date, errors="coerce", dayfirst=True)
    if pd.isna(td):
        return [], 0, ""
    target = td.date()

    dates = pd.to_datetime(data["Ngày"], errors="coerce", dayfirst=True).dt.date
    emp_keys = data["Tên nhân viên"].astype(str).apply(normalize_login_name)
    target_emp = normalize_login_name(employee)
    reasons = data.loc[(dates == target) & (emp_keys == target_emp), "Lý do nghỉ"].astype(str).tolist()
    supports = [r.strip() for r in reasons if "ho tro" in normalize_login_name(r)]

    if not supports:
        return [], 0, ""

    matched = []
    unknown = []
    for reason in supports:
        allowance = TIMESOFT_SUPPORT_LATE_ALLOWANCES.get(normalize_login_name(reason))
        if allowance is None:
            unknown.append(reason)
        else:
            matched.append((allowance, reason))

    # Hỗ trợ khác: giữ hành vi cũ, bỏ qua Auto phạt.
    if unknown:
        return supports, None, unknown[0]
    allowance, reason = max(matched, key=lambda x: x[0])
    return supports, int(allowance), reason


def _timesoft_late_vs_shift(row):
    """Ưu tiên check-in - giờ bắt đầu ca, fallback về parser hiện có."""
    start = _timesoft_row_value(row, ['StartWorkTime', 'WorkTimeStart', 'ShiftStartTime'])
    checkin = _timesoft_row_value(row, ['MachineTimeCheckInStr', 'CheckInTimeStr', 'CheckInTime'])

    def _tm(v):
        m = re.search(r'(\d{1,2}):(\d{2})(?::(\d{2}))?', str(v or '').strip())
        if not m:
            return None
        return int(m.group(1)) * 60 + int(m.group(2)) + int(m.group(3) or 0) / 60.0

    sm, cm = _tm(start), _tm(checkin)
    if sm is not None and cm is not None:
        diff = cm - sm
        if diff < -12 * 60:
            diff += 24 * 60
        return max(0.0, float(diff))
    return _parse_minutes_late_from_timesoft_row(row)



ABSENCE_AUTO_UPDATE_CUTOFF_HOUR = 20
ABSENCE_AUTO_ROLES = {"nhanvien", "leader"}


def _timesoft_checkin_employee_keys_for_date(checkin_df, target_date):
    """
    Lấy tập nhân viên có ít nhất một dữ liệu check-in trong ngày.
    API TimeSoft được gọi theo ngày nên nếu một row thiếu WorkDate vẫn tính cho target_date.
    """
    keys = set()
    if not isinstance(checkin_df, pd.DataFrame) or checkin_df.empty:
        return keys

    for _, row in checkin_df.iterrows():
        raw_date = _timesoft_row_value(
            row,
            ["WorkDateStr", "WorkDate", "CreateDateStr", "CreateDate"],
        )
        parsed_date = _parse_vn_date(raw_date)
        if parsed_date is None and str(raw_date or "").strip():
            try:
                parsed = pd.to_datetime(raw_date, dayfirst=True, errors="coerce")
                parsed_date = parsed.date() if pd.notna(parsed) else None
            except Exception:
                parsed_date = None
        if parsed_date is not None and parsed_date != target_date:
            continue

        raw_name = _timesoft_row_value(
            row,
            [
                "employeeInfo.Name", "EmployeeName", "employeeName",
                "Name", "FullName",
            ],
        )
        key = normalize_employee_match_name(raw_name)
        if key:
            keys.add(key)
    return keys


def _leave_coverage_employee_keys_for_date(leave_df, target_date):
    """
    Một nhân viên được coi là đã có lịch nghỉ hợp lệ cho quy tắc vắng mặt khi
    cùng ngày có ít nhất một dòng Số ngày tính chính xác 0.5 hoặc 1.0.

    Lưu ý schema A:M hiện tại: Số ngày tính là cột H.
    Hàm dùng tên trường, không hard-code cột vật lý.
    """
    if not isinstance(leave_df, pd.DataFrame) or leave_df.empty:
        return set()
    required = {"Ngày", "Tên nhân viên", "Số ngày tính"}
    if not required.issubset(set(leave_df.columns)):
        return set()

    d = leave_df.copy()
    dates = pd.to_datetime(d["Ngày"], dayfirst=True, errors="coerce").dt.date
    days = pd.to_numeric(d["Số ngày tính"], errors="coerce")
    valid_days = days.apply(
        lambda x: bool(pd.notna(x) and (abs(float(x) - 0.5) < 1e-9 or abs(float(x) - 1.0) < 1e-9))
    )
    d = d[dates.eq(target_date) & valid_days].copy()
    return {
        normalize_employee_match_name(x)
        for x in d["Tên nhân viên"].astype(str).tolist()
        if normalize_employee_match_name(x)
    }


def _active_shifted_absence_staff(credentials_df):
    """
    Chỉ xét Nhân viên + Leader đang làm việc và đã được phân ca.
    Nhân sự Tạm thời nghỉ việc / Đã nghỉ việc hoặc chưa phân ca không bị Auto phạt vắng.
    """
    if not isinstance(credentials_df, pd.DataFrame) or credentials_df.empty:
        return []

    status_map = load_employment_status_map()
    out = []
    for _, row in credentials_df.iterrows():
        employee = str(row.get("Tên nhân viên", "") or "").strip()
        role = str(row.get("Phân quyền", "") or "").strip().lower()
        shift = str(row.get("Ca làm việc", "") or "").strip()
        if not employee or role not in ABSENCE_AUTO_ROLES or not shift:
            continue

        status = status_map.get(
            normalize_login_name(employee),
            EMPLOYMENT_STATUS_ACTIVE,
        )
        if status != EMPLOYMENT_STATUS_ACTIVE:
            continue
        out.append({
            "employee": employee,
            "employee_key": normalize_employee_match_name(employee),
            "role": role,
            "shift": shift,
        })
    return out


def auto_update_absence_without_checkin_from_timesoft(
    checkin_df,
    target_date=None,
    actor="AUTO UPDATE - TIMESOFT NGHỈ KHÔNG PHÉP",
):
    """
    Auto Nghỉ không phép:
    - nhân viên/leader đang làm việc + đã phân ca;
    - không có bất kỳ check-in TimeSoft nào trong ngày;
    - Sheet1 cùng ngày không có dòng của người đó với Số ngày tính = 0.5 hoặc 1;
    - hôm nay chỉ kết luận từ 20:00 trở đi để Scheduler 15:00 không phạt nhầm.
    - nếu toàn bộ snapshot check-in rỗng thì không phạt để tránh lỗi TimeSoft/API gây phạt hàng loạt.
    """
    result = _auto_result("TimeSoft nghỉ không phép")
    cfg = load_auto_penalty_config()
    if cfg.get("paused"):
        result["paused"] = True
        result["messages"].append("Auto Update đang tạm dừng bởi Admin.")
        return result

    target_date = target_date or get_vn_today()
    now_vn = datetime.now(VN_TZ)

    if target_date == now_vn.date() and now_vn.hour < ABSENCE_AUTO_UPDATE_CUTOFF_HOUR:
        result["messages"].append(
            f"Nghỉ không phép chỉ được đối soát từ {ABSENCE_AUTO_UPDATE_CUTOFF_HOUR:02d}:00 để tránh phạt nhầm trước khi hoàn tất ngày làm việc."
        )
        return result

    # Guard quan trọng: không biến lỗi fetch TimeSoft thành "mọi người đều vắng".
    if not isinstance(checkin_df, pd.DataFrame) or checkin_df.empty:
        result["messages"].append(
            "Snapshot chấm công TimeSoft đang rỗng; hệ thống bỏ qua Auto Nghỉ không phép để tránh phạt hàng loạt do lỗi dữ liệu."
        )
        return result

    checkin_keys = _timesoft_checkin_employee_keys_for_date(checkin_df, target_date)
    if not checkin_keys:
        result["messages"].append(
            "Không nhận diện được nhân viên nào trong snapshot TimeSoft của ngày; bỏ qua Auto Nghỉ không phép."
        )
        return result

    try:
        live_leave = _load_live_leave_registration_for_validation()
    except Exception as exc:
        result["errors"] += 1
        result["messages"].append(f"Không đọc được lịch nghỉ LIVE: {exc}")
        return result

    covered_leave_keys = _leave_coverage_employee_keys_for_date(
        live_leave, target_date
    )

    try:
        creds = load_credentials_fresh()
    except Exception:
        creds = globals().get("df_credentials", pd.DataFrame())
    staff = _active_shifted_absence_staff(creds)
    if not staff:
        result["messages"].append(
            "Không tìm thấy Nhân viên + Leader đang làm việc và đã phân ca để đối soát."
        )
        return result

    catalog = build_leave_reason_catalog(
        globals().get("df_loai_nghi", pd.DataFrame())
    )
    reason_item = _auto_penalty_catalog_item("Nghỉ không phép", catalog)
    if not reason_item:
        result["errors"] += 1
        result["messages"].append(
            "Sheet LoaiNghi chưa có 'Nghỉ không phép', nên hệ thống không thể Auto Update phạt."
        )
        return result

    reason = reason_item.get("name", "Nghỉ không phép")
    base_penalty = float(reason_item.get("penalty", 0) or 0)
    days = float(reason_item.get("days", 0) or 0)
    weekday = _vn_weekday_label(target_date)
    main_source = live_leave

    for profile in staff:
        employee = profile["employee"]
        ekey = profile["employee_key"]

        if ekey in checkin_keys:
            continue
        if ekey in covered_leave_keys:
            continue

        result["eligible"] += 1
        detail = (
            f"Auto Update TimeSoft · không có dữ liệu check-in · {weekday}"
            " · Sheet1 không có lịch nghỉ Số ngày tính 0.5 hoặc 1"
            f" · Ca {profile['shift']}"
        )

        ok, msg = save_lich_nghi_to_backup_sheet(
            target_date.strftime("%d/%m/%Y"),
            employee,
            reason,
            detail,
            days,
            0.0,
            base_penalty,
            actor,
            df_main_source=main_source,
        )
        if ok:
            result["added"] += 1
        elif (
            "đã có đúng lý do" in str(msg).lower()
            or "không được đăng ký trùng" in str(msg).lower()
            or "đã có loại nghỉ" in str(msg).lower()
        ):
            result["skipped"] += 1
        else:
            result["errors"] += 1
            result["messages"].append(f"{employee}: {msg}")

    if result["eligible"] == 0:
        result["messages"].append(
            f"{target_date.strftime('%d/%m/%Y')} ({weekday}): không có nhân viên đủ điều kiện Auto Nghỉ không phép."
        )
    return result


def auto_update_checkin_late_from_timesoft(checkin_df, actor="AUTO UPDATE - TIMESOFT"):
    """Tự ghi Đi trễ không phép khi check-in muộn hơn ca quy định từ 5 phút trở lên."""
    result = _auto_result("TimeSoft")
    cfg = load_auto_penalty_config()
    if cfg.get('paused'):
        result['paused'] = True
        result['messages'].append('Auto Update đang tạm dừng bởi Admin.')
        return result
    if not isinstance(checkin_df, pd.DataFrame) or checkin_df.empty:
        return result

    catalog = build_leave_reason_catalog(globals().get('df_loai_nghi', pd.DataFrame()))
    reason_item = _auto_penalty_catalog_item('Đi trễ không phép', catalog)
    if not reason_item:
        result['errors'] += 1
        result['messages'].append("Sheet LoaiNghi chưa có 'Đi trễ không phép', nên hệ thống không tự ghi phạt.")
        return result
    reason = reason_item.get('name', 'Đi trễ không phép')
    base_penalty = float(reason_item.get('penalty', 0) or 0)
    days = float(reason_item.get('days', 0) or 0)
    threshold = max(AUTO_PENALTY_MINUTES, int(cfg.get('threshold_minutes', AUTO_PENALTY_MINUTES) or AUTO_PENALTY_MINUTES))
    main_source = _load_live_leave_registration_for_validation()

    for _, row in checkin_df.iterrows():
        minutes = _timesoft_late_vs_shift(row)
        if minutes is None or float(minutes) < threshold:
            continue
        result['eligible'] += 1
        raw_name = _timesoft_row_value(row, [
            'employeeInfo.Name', 'EmployeeName', 'employeeName', 'Name', 'FullName'
        ])
        employee = _canonical_system_employee_name(raw_name)
        if not employee:
            result['skipped'] += 1
            result['unmatched'].append(str(raw_name or '(không có tên)'))
            continue
        raw_date = _timesoft_row_value(row, ['WorkDateStr', 'WorkDate', 'CreateDateStr', 'CreateDate'])
        parsed_date = _parse_vn_date(raw_date)
        if not parsed_date:
            try:
                parsed_date = pd.to_datetime(raw_date, dayfirst=True, errors='coerce').date()
            except Exception:
                parsed_date = None
        if not parsed_date or pd.isna(parsed_date):
            result['skipped'] += 1
            result['messages'].append(f"{employee}: không xác định được ngày chấm công.")
            continue

        support_reasons, allowance, support_reason = _timesoft_support_for_day(employee, parsed_date)
        if support_reasons:
            if allowance is None:
                result['skipped'] += 1
                result['messages'].append(f"{employee}: bỏ qua Auto phạt vì có Hỗ trợ '{support_reason}'.")
                continue
            if float(minutes) <= float(allowance):
                result['skipped'] += 1
                result['messages'].append(
                    f"{employee}: Hỗ trợ cho phép trễ {allowance} phút; thực tế {int(round(float(minutes)))} phút → không phạt."
                )
                continue

        shift_start = _timesoft_row_value(row, ['StartWorkTime', 'WorkTimeStart', 'ShiftStartTime'])
        checkin_time = _timesoft_row_value(row, ['MachineTimeCheckInStr', 'CheckInTimeStr', 'CheckInTime'])
        detail = f"Auto Update TimeSoft · check-in muộn {int(round(float(minutes)))} phút"
        if support_reasons and allowance is not None and float(minutes) > float(allowance):
            detail += f" · Hỗ trợ cho phép {allowance} phút nhưng đã vượt {int(round(float(minutes) - float(allowance)))} phút"
        if shift_start:
            detail += f" · Ca bắt đầu {shift_start}"
        if checkin_time:
            detail += f" · Check-in {checkin_time}"
        ok, msg = save_lich_nghi_to_backup_sheet(
            parsed_date.strftime('%d/%m/%Y'), employee, reason, detail,
            days, 0.0, base_penalty, actor, df_main_source=main_source
        )
        if ok:
            result['added'] += 1
        elif 'không được đăng ký trùng' in str(msg).lower() or 'đã có loại nghỉ' in str(msg).lower():
            result['skipped'] += 1
        else:
            result['errors'] += 1
            result['messages'].append(f"{employee}: {msg}")
    return result

def auto_update_midshift_late_from_timesoft(
    checkin_df,
    actor="AUTO UPDATE - TIMESOFT NGHỈ GIỮA CA",
):
    """
    Tự ghi "Ra ngoài vào muộn" khi nhân viên quay lại nghỉ giữa ca
    từ đủ ngưỡng sau giờ giới hạn (mặc định 20:05 trở đi).
    Không ghi nếu ngày đó không nghỉ hoặc dữ liệu chưa đủ cụm FaceID.
    """
    result = _auto_result("TimeSoft nghỉ giữa ca")

    cfg_auto = load_auto_penalty_config()
    if cfg_auto.get("paused"):
        result["paused"] = True
        result["messages"].append("Auto Update đang tạm dừng bởi Admin.")
        return result

    if not isinstance(checkin_df, pd.DataFrame) or checkin_df.empty:
        return result

    try:
        creds = load_credentials_fresh()
    except Exception:
        creds = globals().get("df_credentials", pd.DataFrame())

    status_df = calculate_midshift_break_from_timesoft(
        checkin_df, creds
    )
    if status_df.empty:
        return result

    late_rows = status_df[
        status_df.get("Loại vi phạm", "").astype(str)
        .eq("Ra ngoài vào muộn")
    ].copy()
    if late_rows.empty:
        return result

    catalog = build_leave_reason_catalog(
        globals().get("df_loai_nghi", pd.DataFrame())
    )
    main_source = _load_live_leave_registration_for_validation()

    for _, row in late_rows.iterrows():
        employee = _canonical_system_employee_name(
            row.get("Tên nhân viên", "")
        )
        if not employee:
            result["skipped"] += 1
            result["unmatched"].append(
                str(row.get("Tên nhân viên", "") or "(không có tên)")
            )
            continue

        try:
            minutes = int(float(row.get("Phút vào muộn", 0) or 0))
        except Exception:
            minutes = 0

        deadline_cfg = load_midshift_deadline_config()
        threshold = int(
            deadline_cfg.get(
                "late_threshold_minutes",
                MIDSHIFT_LATE_THRESHOLD_DEFAULT,
            )
            or MIDSHIFT_LATE_THRESHOLD_DEFAULT
        )
        if minutes < threshold:
            continue

        reason = _outside_late_reason_for_minutes(minutes, catalog)
        if not reason:
            result["errors"] += 1
            result["messages"].append(
                f"{employee}: chưa tìm thấy loại 'Ra ngoài vào muộn' phù hợp trong LoaiNghi."
            )
            continue

        item = _auto_penalty_catalog_item(reason, catalog) or {}
        base_penalty = float(item.get("penalty", 0) or 0)
        days = float(item.get("days", 0) or 0)

        date_value = _parse_vn_date(row.get("Ngày"))
        if date_value is None:
            date_value = get_vn_today()

        details = (
            f"Auto Update TimeSoft nghỉ giữa ca · vào muộn {minutes} phút"
            f" · Bắt đầu nghỉ {row.get('Bắt đầu nghỉ','')}"
            f" · Quay lại {row.get('Kết thúc nghỉ','')}"
            f" · Giới hạn {row.get('Giờ phải quay lại','')}"
            f" · Duration {row.get('Duration thực tế','')}/{row.get('Duration quy định','')} phút"
        )

        result["eligible"] += 1
        ok, msg = save_lich_nghi_to_backup_sheet(
            date_value.strftime("%d/%m/%Y"),
            employee,
            reason,
            details,
            days,
            0.0,
            base_penalty,
            actor,
            df_main_source=main_source,
        )
        if ok:
            result["added"] += 1
        elif (
            "không được đăng ký trùng" in str(msg).lower()
            or "đã có loại nghỉ" in str(msg).lower()
        ):
            result["skipped"] += 1
        else:
            result["errors"] += 1
            result["messages"].append(f"{employee}: {msg}")

    return result


def run_auto_penalty_now(tour_df=None, checkin_df=None, actor="AUTO UPDATE"):
    """Chạy cả 2 nguồn; dùng cho trang Admin và các lần đồng bộ thủ công."""
    if tour_df is None:
        try:
            tour_df, _ = load_bang_tour_input()
        except Exception:
            tour_df = pd.DataFrame()
    r_tour = auto_update_outside_late_from_tour(tour_df, actor=f"{actor} - BẢNG TOUR")
    r_ts = auto_update_checkin_late_from_timesoft(checkin_df, actor=f"{actor} - TIMESOFT") if isinstance(checkin_df, pd.DataFrame) else _auto_result("TimeSoft")
    r_midshift = auto_update_midshift_late_from_timesoft(
        checkin_df,
        actor=f"{actor} - TIMESOFT NGHỈ GIỮA CA",
    ) if isinstance(checkin_df, pd.DataFrame) else _auto_result("TimeSoft nghỉ giữa ca")
    r_absence = auto_update_absence_without_checkin_from_timesoft(
        checkin_df,
        target_date=get_vn_today(),
        actor=f"{actor} - TIMESOFT NGHỈ KHÔNG PHÉP",
    ) if isinstance(checkin_df, pd.DataFrame) else _auto_result("TimeSoft nghỉ không phép")
    r_ca1 = auto_update_ca1_cleaning_from_leave_data(actor=f"{actor} - CA1")
    return {
        "tour": r_tour,
        "timesoft": r_ts,
        "midshift": r_midshift,
        "absence": r_absence,
        "ca1": r_ca1,
    }


def _vn_weekday_label(value):
    """Trả về Thứ 2..Thứ 7 / Chủ nhật từ giá trị ngày; không làm thay đổi dữ liệu nguồn."""
    d = _parse_vn_date(value)
    if d is None:
        return ""
    labels = {
        0: "Thứ 2",
        1: "Thứ 3",
        2: "Thứ 4",
        3: "Thứ 5",
        4: "Thứ 6",
        5: "Thứ 7",
        6: "Chủ nhật",
    }
    return labels.get(d.weekday(), "")


def add_weekday_column(df):
    """Thêm cột hiển thị `Thứ ngày` ngay bên phải cột `Ngày`."""
    if not isinstance(df, pd.DataFrame):
        return df
    d = df.copy()
    if "Ngày" not in d.columns:
        return d
    if "Thứ ngày" in d.columns:
        d = d.drop(columns=["Thứ ngày"])
    pos = d.columns.get_loc("Ngày") + 1
    d.insert(pos, "Thứ ngày", d["Ngày"].apply(_vn_weekday_label))
    return d


def _leave_reason_type_map(source_df=None):
    """
    Mapping chuẩn từ sheet LoaiNghi của file 1Kz0...:
    - Cột B = Lý do nghỉ
    - Cột C = Loại nghỉ

    Trả về dict theo khóa normalize_leave_reason(Lý do nghỉ) -> Loại nghỉ.
    """
    source = source_df if isinstance(source_df, pd.DataFrame) else globals().get('df_loai_nghi', pd.DataFrame())
    result = {}
    if source is None or not isinstance(source, pd.DataFrame) or source.empty:
        return result

    for _, row in source.iterrows():
        vals = row.tolist()

        # Ưu tiên tuyệt đối vị trí vật lý B/C như người dùng quy định.
        reason = str(vals[1]).strip() if len(vals) > 1 else ""
        leave_type = str(vals[2]).strip() if len(vals) > 2 else ""

        # Fallback theo tên header nếu file thay đổi cách load nhưng vẫn giữ ý nghĩa cột.
        if not reason or reason.casefold() in {"nan", "none"}:
            reason = str(row.get('Lý do nghỉ', '') or '').strip()
        if not leave_type or leave_type.casefold() in {"nan", "none"}:
            leave_type = str(row.get('Loại nghỉ', '') or '').strip()

        reason = clean_leave_reason_display(reason)
        leave_type = clean_leave_reason_display(leave_type)

        if not reason or reason.casefold() in {"nan", "none", "lý do nghỉ"}:
            continue
        if leave_type.casefold() in {"nan", "none", "loại nghỉ"}:
            leave_type = ""

        key = normalize_leave_reason(reason)
        if key and key not in result:
            result[key] = leave_type

    return result


def _leave_type_series_from_reason(df):
    """Trả về Loại nghỉ chuẩn theo mapping LoaiNghi: cột B (Lý do) -> cột C (Loại nghỉ)."""
    if not isinstance(df, pd.DataFrame) or df.empty:
        return pd.Series(dtype=str)
    d = df.copy()
    if 'Lý do nghỉ' not in d.columns:
        return pd.Series([''] * len(d), index=d.index, dtype=str)
    mapping = _leave_reason_type_map(globals().get('df_loai_nghi', pd.DataFrame()))
    return d['Lý do nghỉ'].astype(str).apply(
        lambda v: clean_leave_reason_display(mapping.get(normalize_leave_reason(v), ''))
    )


def add_source_leave_type_column(df):
    """
    V86.1: đồng nhất dữ liệu hiển thị lịch nghỉ:
    - `Lý do nghỉ` = giá trị Lý do đã lưu, đối chiếu danh mục cột B của sheet LoaiNghi.
    - `Loại nghỉ` = giá trị cột C tương ứng trong sheet LoaiNghi.
    - `Thứ ngày` đặt ngay sau `Ngày`.

    Không còn sao chép Lý do nghỉ sang Loại nghỉ.
    """
    if not isinstance(df, pd.DataFrame):
        return df

    d = add_weekday_column(df.copy())
    if 'Lý do nghỉ' not in d.columns:
        return d

    # Làm sạch Lý do nghỉ để khớp đúng với cột B của danh mục.
    d['Lý do nghỉ'] = d['Lý do nghỉ'].apply(clean_leave_reason_display)

    reason_type_map = _leave_reason_type_map(globals().get('df_loai_nghi', pd.DataFrame()))
    type_values = d['Lý do nghỉ'].apply(
        lambda v: reason_type_map.get(normalize_leave_reason(v), "")
    )

    if 'Loại nghỉ' in d.columns:
        d = d.drop(columns=['Loại nghỉ'])

    pos = d.columns.get_loc('Lý do nghỉ') + 1
    d.insert(pos, 'Loại nghỉ', type_values)
    return d


def get_leave_reason_options(source_df=None, extra_values=None):
    """Danh sách dropdown Lý do nghỉ luôn chứa ĐÚNG chuỗi hiện có của dữ liệu lịch sử.

    Streamlit SelectboxColumn không chỉ so khớp theo ý nghĩa mà yêu cầu chuỗi trong ô phải
    khớp CHÍNH XÁC với một option. Vì danh mục LoaiNghi có thể dùng kiểu chữ khác nhau
    (ví dụ ``Nghỉ KHÔNG phép``) trong khi dữ liệu lịch sử là ``Nghỉ không phép``, nếu chỉ
    khử trùng theo dạng chuẩn hóa thì ô sẽ bị hiển thị trắng dù dữ liệu vẫn còn nguyên.

    V69 giữ cả biến thể danh mục và biến thể chính xác đang tồn tại trong bảng. Nhờ vậy mọi
    loại có chữ KHÔNG phép (Nghỉ/Đi trễ/Về sớm, kể cả CUỐI TUẦN) luôn hiện đúng trong editor.
    """
    catalog = build_leave_reason_catalog(source_df)
    options = []
    seen_exact = set()

    def _append_exact(value):
        clean = clean_leave_reason_display(value)
        if not clean or clean.casefold() in ['nan', 'none', 'nat', 'loại nghỉ', 'lý do nghỉ']:
            return
        # Chỉ bỏ trùng khi chuỗi sau làm sạch thực sự giống HỆT nhau. Không dùng
        # normalize_leave_reason ở đây vì khác kiểu HOA/thường cũng làm SelectboxColumn
        # coi là hai giá trị khác nhau.
        if clean not in seen_exact:
            options.append(clean)
            seen_exact.add(clean)

    for item in [v['name'] for v in catalog.values()]:
        _append_exact(item)
    if extra_values is not None:
        for val in extra_values:
            _append_exact(val)
    return options



def _schedule_compare_value(column_name, value):
    """Chuẩn hóa giá trị để phát hiện dòng lịch nghỉ thật sự đã thay đổi."""
    if column_name == 'Ngày':
        return normalize_schedule_date(value)
    if column_name == 'Tên nhân viên':
        return normalize_login_name(value)
    if column_name == 'Lý do nghỉ':
        return normalize_leave_reason(clean_leave_reason_display(value))
    if column_name == 'Chi tiết':
        return str(value or '').strip()
    return str(value if value is not None else '').strip()


def get_changed_schedule_positions(original_df, edited_df, editable_columns=None):
    """Trả về các vị trí dòng đã đổi, không phụ thuộc checkbox Chọn."""
    if original_df is None or edited_df is None:
        return []
    editable_columns = editable_columns or ['Ngày', 'Tên nhân viên', 'Lý do nghỉ', 'Chi tiết']
    changed = []
    limit = min(len(original_df), len(edited_df))
    for pos in range(limit):
        old = original_df.iloc[pos]
        new = edited_df.iloc[pos]
        if any(
            c in new.index and _schedule_compare_value(c, old.get(c, '')) != _schedule_compare_value(c, new.get(c, ''))
            for c in editable_columns
        ):
            changed.append(pos)
    return changed


LEADER_POLICY_LEAVE_REASONS = {
    normalize_login_name(""),
    normalize_login_name(""),
    normalize_login_name(""),
}
BEREAVEMENT_LEAVE_REASON = "Nghỉ đám hiếu"


def is_leader_policy_leave_reason(value):
    return normalize_login_name(clean_leave_reason_display(value)) in LEADER_POLICY_LEAVE_REASONS


def is_bereavement_leave_reason(value):
    return normalize_login_name(clean_leave_reason_display(value)) == normalize_login_name(BEREAVEMENT_LEAVE_REASON)


def is_special_day_rule_exempt(role, reason):
    role = str(role or "").strip().lower()
    if role == "leader" and is_leader_policy_leave_reason(reason):
        return True
    if role in {"admin", "letan", "quanly"} and is_bereavement_leave_reason(reason):
        return True
    if is_video_leave_reason(reason):
        return True
    return False


def _filter_active_employees_for_leave_stats(df):
    """Chỉ nhân sự Đang làm việc được tính thống kê/hạn mức nghỉ."""
    if not isinstance(df, pd.DataFrame) or df.empty or "Tên nhân viên" not in df.columns:
        return df.copy() if isinstance(df, pd.DataFrame) else pd.DataFrame()
    status_map = load_employment_status_map()
    if not status_map:
        return df.copy()
    d = df.copy()
    keys = d["Tên nhân viên"].astype(str).apply(normalize_login_name)
    statuses = keys.map(lambda k: status_map.get(k, EMPLOYMENT_STATUS_ACTIVE))
    return d[statuses.eq(EMPLOYMENT_STATUS_ACTIVE)].copy()


VIDEO_LEAVE_REASON = "Nghỉ phép quay video"


def is_video_leave_reason(value):
    """Loại nghỉ đặc biệt: không chịu hạn mức ngày/tháng/cuối tuần và không chiếm suất nghỉ của người khác."""
    return normalize_login_name(clean_leave_reason_display(value)) == normalize_login_name(VIDEO_LEAVE_REASON)


def is_employee_khong_phep_leave_reason(value):
    """Nhận diện Loại nghỉ KHÔNG phép cho quyền Sửa/Hủy của Nhân viên/Leader."""
    key = normalize_login_name(clean_leave_reason_display(value))
    return bool(key and "khong phep" in key)


def _reason_is_unlimited_for_weekend_limit(reason):
    """
    V92.6.29:
    Mọi Lý do nghỉ có chữ 'KHÔNG phép' không chịu giới hạn số lần nghỉ cuối tuần/tháng.
    """
    return is_employee_khong_phep_leave_reason(reason)


def _weekend_registration_count_by_month(all_leave_df, employee_name, year, month):
    """
    Đếm số ngày cuối tuần đã đăng ký của nhân viên trong tháng,
    nhưng KHÔNG tính các lý do có chữ 'KHÔNG phép' và Nghỉ phép quay video.
    """
    if not isinstance(all_leave_df, pd.DataFrame) or all_leave_df.empty:
        return 0
    if "Ngày" not in all_leave_df.columns or "Tên nhân viên" not in all_leave_df.columns:
        return 0

    d = all_leave_df.copy()
    if "Lý do nghỉ" in d.columns:
        d = d[
            ~d["Lý do nghỉ"].astype(str).apply(_reason_is_unlimited_for_weekend_limit)
            & ~d["Lý do nghỉ"].astype(str).apply(is_video_leave_reason)
        ].copy()

    if d.empty:
        return 0

    d["__date"] = d["Ngày"].apply(_parse_vn_date)
    emp_key = normalize_login_name(employee_name)
    d["__emp"] = d["Tên nhân viên"].apply(normalize_login_name)
    d = d[
        d["__date"].notna()
        & d["__emp"].eq(emp_key)
        & d["__date"].apply(lambda x: x.year == int(year) and x.month == int(month))
        & d["__date"].apply(lambda x: x.weekday() >= 5)
    ].copy()
    if d.empty:
        return 0
    return len(set(d["__date"].tolist()))


def _validate_monthly_weekend_registration_limit(
    all_leave_df,
    employee_name,
    start_date,
    end_date,
    reason="",
    max_weekend_dates=2,
):
    """
    Giới hạn cuối tuần theo tháng.

    - Lý do nghỉ có chữ 'KHÔNG phép' => KHÔNG giới hạn số lần.
    - Các bản ghi KHÔNG phép đã có cũng không chiếm quota cuối tuần.
    - Các lý do khác vẫn giữ giới hạn cũ.
    """
    if _reason_is_unlimited_for_weekend_limit(reason):
        return True, ""

    selected_weekends = []
    current = start_date
    while current <= end_date:
        if current.weekday() >= 5:
            selected_weekends.append(current)
        current += timedelta(days=1)

    if not selected_weekends:
        return True, ""

    by_month = {}
    for d in selected_weekends:
        by_month.setdefault((d.year, d.month), set()).add(d)

    quota_df = all_leave_df.copy() if isinstance(all_leave_df, pd.DataFrame) else pd.DataFrame()
    if isinstance(quota_df, pd.DataFrame) and not quota_df.empty and "Lý do nghỉ" in quota_df.columns:
        quota_df = quota_df[
            ~quota_df["Lý do nghỉ"].astype(str).apply(_reason_is_unlimited_for_weekend_limit)
            & ~quota_df["Lý do nghỉ"].astype(str).apply(is_video_leave_reason)
        ].copy()

    for (year, month), selected_dates in sorted(by_month.items()):
        existing_count = _weekend_registration_count_by_month(
            quota_df, employee_name, year, month
        )

        existing_dates = set()
        if isinstance(quota_df, pd.DataFrame) and not quota_df.empty:
            tmp = quota_df.copy()
            if "Ngày" in tmp.columns and "Tên nhân viên" in tmp.columns:
                tmp["__date"] = tmp["Ngày"].apply(_parse_vn_date)
                tmp["__emp"] = tmp["Tên nhân viên"].apply(normalize_login_name)
                emp_key = normalize_login_name(employee_name)
                existing_dates = set(
                    tmp[
                        tmp["__date"].notna()
                        & tmp["__emp"].eq(emp_key)
                        & tmp["__date"].apply(
                            lambda x: x.year == year and x.month == month and x.weekday() >= 5
                        )
                    ]["__date"].tolist()
                )

        new_dates = set(selected_dates) - existing_dates
        projected = existing_count + len(new_dates)

        if projected > int(max_weekend_dates):
            dates_txt = ", ".join(sorted(d.strftime("%d/%m/%Y") for d in selected_dates))
            return False, (
                f"Nhân viên {employee_name} chỉ được đăng ký tối đa {max_weekend_dates} lần cuối tuần "
                f"trong tháng {month:02d}/{year} đối với các lý do chịu giới hạn. "
                f"Đã có {existing_count} lần; đăng ký này có ngày cuối tuần: {dates_txt}."
            )

    return True, ""


def _leave_rows_counting_toward_quota(df):
    """Loại Nghỉ phép quay video khỏi mọi phép đếm hạn mức nhân sự."""
    if not isinstance(df, pd.DataFrame) or df.empty or "Lý do nghỉ" not in df.columns:
        return df.copy() if isinstance(df, pd.DataFrame) else pd.DataFrame()
    return df[~df["Lý do nghỉ"].astype(str).apply(is_video_leave_reason)].copy()


def is_employee_co_phep_leave_reason(value):
    """Nhận diện nhóm Loại nghỉ CÓ phép theo cùng quy tắc đang dùng ở phần thống kê."""
    key = normalize_login_name(clean_leave_reason_display(value))
    if not key or "khong phep" in key or "nghi phat sinh" in key:
        return False
    excluded_keywords = [
        "di tre", "khong don ve sinh", "loi vi pham", "qua tour", "xuong phong",
        "ra som", "vao muon", "di tua", "ngung nhan", "ho tro ca"
    ]
    return not any(kw in key for kw in excluded_keywords)



def _validate_leave_registration_request_live(payload, live_df, credentials_df):
    """
    V92.6.32 - Đối chiếu tập trung SAU khi bấm Ghi Lịch Nghỉ.

    Không tự đọc Google Sheet / PostgreSQL.
    Caller truyền vào MỘT snapshot LIVE đã đọc đúng lúc bấm nút.

    Trả:
      {
        "ok": bool,
        "errors": [...],
        "warnings": [...],
        "accumulated_month": float,
      }
    """
    result = {
        "ok": False,
        "errors": [],
        "warnings": [],
        "accumulated_month": 0.0,
    }

    role = str(payload.get("role", "") or "").strip().lower()
    is_admin = role == "admin"
    employee = str(payload.get("employee", "") or "").strip()
    reason = clean_leave_reason_display(payload.get("reason", ""))
    detail = str(payload.get("detail", "") or "").strip()

    start_date = payload.get("start_date")
    end_date = payload.get("end_date")
    if not isinstance(start_date, date) or not isinstance(end_date, date):
        result["errors"].append("Ngày đăng ký không hợp lệ.")
        return result
    if end_date < start_date:
        result["errors"].append("Ngày kết thúc phải lớn hơn hoặc bằng ngày bắt đầu.")
        return result

    if not employee or employee == "-- Chọn nhân viên --":
        result["errors"].append("Vui lòng chọn nhân viên cần nhập lịch nghỉ.")
    if not reason or reason == "-- Chọn lý do nghỉ --":
        result["errors"].append("Vui lòng chọn lý do nghỉ.")

    try:
        val_songay = float(payload.get("days", 0) or 0)
    except Exception:
        val_songay = 0.0

    val_phat = payload.get("penalty")
    requires_manual_penalty = bool(payload.get("requires_manual_penalty", False))
    is_loi_vi_pham = bool(payload.get("is_loi_vi_pham", False))
    is_nghi_ly_do_khac = bool(payload.get("is_nghi_ly_do_khac", False))
    is_zero_day_co_phep = bool(payload.get("is_zero_day_co_phep", False))
    default_phat = float(payload.get("default_penalty", 0) or 0)

    if is_loi_vi_pham:
        val_songay = 0.0
        if not detail:
            result["errors"].append(
                "Chưa có Chi tiết vi phạm cho 'Lỗi vi phạm khác'."
            )
    if is_nghi_ly_do_khac and not detail:
        result["errors"].append(
            "Bắt buộc nhập Chi tiết vi phạm / Ghi chú đối với 'Nghỉ lý do khác'."
        )
    if requires_manual_penalty and val_phat is None:
        result["errors"].append("Bắt buộc nhập Mức phạt vi phạm.")

    if result["errors"]:
        return result

    now_vn = datetime.now(VN_TZ)
    today = now_vn.date()
    selected_dates = [
        start_date + timedelta(days=i)
        for i in range((end_date - start_date).days + 1)
    ]

    # Rule G/H/I/J/K chỉ dùng rule đang nằm trong bộ nhớ, không đọc nguồn ngoài.
    if not is_admin:
        for target_date in selected_dates:
            ok, msg = validate_leave_registration_notice(
                reason,
                target_date,
                role=role,
                now_vn=now_vn,
            )
            if not ok:
                result["errors"].append(msg)
                return result

    if role in EMPLOYEE_LIKE_ROLES:
        _, emp_max_date = employee_registration_window(today)
        if end_date > emp_max_date:
            result["errors"].append(
                f"Nhân viên chỉ được đăng ký đến hết {emp_max_date.strftime('%d/%m/%Y')}."
            )
            return result

    source_df = (
        live_df.copy()
        if isinstance(live_df, pd.DataFrame)
        else pd.DataFrame(columns=LEAVE_DATA_COLUMNS)
    )

    # KHÔNG phép không chịu giới hạn số lần cuối tuần theo V92.6.29.
    weekend_ok, weekend_msg = _validate_monthly_weekend_registration_limit(
        source_df,
        employee,
        start_date,
        end_date,
        reason=reason,
        max_weekend_dates=2,
    )
    if not weekend_ok:
        result["errors"].append(weekend_msg)
        return result

    norm_reason = normalize_leave_reason(reason)
    is_video_leave = is_video_leave_reason(reason)
    num_days_selected = len(selected_dates)

    # Hạn mức cá nhân.
    nv_info = pd.DataFrame()
    if isinstance(credentials_df, pd.DataFrame) and not credentials_df.empty:
        if "Tên nhân viên" in credentials_df.columns:
            nv_info = credentials_df[
                credentials_df["Tên nhân viên"].astype(str)
                .apply(normalize_login_name)
                .eq(normalize_login_name(employee))
            ]

    def _cred_limit(col):
        if nv_info.empty or col not in nv_info.columns:
            return 0.0
        v = pd.to_numeric(nv_info.iloc[0].get(col, 0), errors="coerce")
        return 0.0 if pd.isna(v) else float(v)

    limit_ps = _cred_limit("Phát sinh tháng")
    limit_cp = _cred_limit("Có phép tháng")
    limit_pn = _cred_limit("Phép năm")

    if (
        isinstance(source_df, pd.DataFrame)
        and not source_df.empty
        and "Tên nhân viên" in source_df.columns
    ):
        user_hist = source_df[
            source_df["Tên nhân viên"].astype(str)
            .apply(normalize_login_name)
            .eq(normalize_login_name(employee))
        ].copy()
    else:
        user_hist = pd.DataFrame(columns=["Ngày", "Lý do nghỉ", "Số ngày tính"])

    user_hist_quota = _leave_rows_counting_toward_quota(user_hist)

    for frame in (user_hist, user_hist_quota):
        if "Ngày" not in frame.columns:
            frame["Ngày"] = pd.Series(dtype="object")
        frame["Ngày_DT"] = pd.to_datetime(frame["Ngày"], errors="coerce", dayfirst=True)
        frame["M"] = frame["Ngày_DT"].dt.month
        frame["Y"] = frame["Ngày_DT"].dt.year
        if "Số ngày tính" in frame.columns:
            frame["Số ngày tính"] = pd.to_numeric(
                frame["Số ngày tính"], errors="coerce"
            ).fillna(0.0)

    curr_m = start_date.month
    curr_y = start_date.year
    total_phep_required = val_songay * num_days_selected

    month_hist = user_hist_quota[
        (user_hist_quota["M"] == curr_m)
        & (user_hist_quota["Y"] == curr_y)
    ]
    accumulated_month = (
        float(pd.to_numeric(month_hist.get("Số ngày tính", 0), errors="coerce").fillna(0).sum())
        if not month_hist.empty and "Số ngày tính" in month_hist.columns
        else 0.0
    )
    result["accumulated_month"] = accumulated_month

    if not is_admin and not is_video_leave:
        if "phép năm" in norm_reason:
            year_hist = user_hist_quota[user_hist_quota["Y"] == curr_y]
            used_pn = (
                float(
                    pd.to_numeric(
                        year_hist[
                            year_hist["Lý do nghỉ"].astype(str)
                            .str.lower()
                            .str.contains("phép năm", na=False)
                        ].get("Số ngày tính", 0),
                        errors="coerce",
                    ).fillna(0).sum()
                )
                if not year_hist.empty and "Lý do nghỉ" in year_hist.columns
                else 0.0
            )
            if limit_pn > 0 and used_pn + total_phep_required > limit_pn:
                result["errors"].append(
                    f"Vượt quá số ngày Phép năm. Cần {total_phep_required:g} ngày, "
                    f"quỹ còn {max(0.0, limit_pn - used_pn):g} ngày trong năm {curr_y}."
                )
                return result

        elif "phát sinh" in norm_reason:
            month_user = user_hist_quota[
                (user_hist_quota["M"] == curr_m)
                & (user_hist_quota["Y"] == curr_y)
            ]
            used_ps = (
                int(
                    month_user["Lý do nghỉ"].astype(str)
                    .str.lower()
                    .str.contains("phát sinh", na=False)
                    .sum()
                )
                if not month_user.empty and "Lý do nghỉ" in month_user.columns
                else 0
            )
            if limit_ps > 0 and used_ps >= limit_ps:
                result["errors"].append(
                    f"Vượt giới hạn Phát sinh. Nhân viên này chỉ được đăng ký "
                    f"{limit_ps:g} lần phát sinh/tháng."
                )
                return result

        elif (
            not is_nghi_ly_do_khac
            and "không phép" not in norm_reason
            and val_songay > 0
        ):
            month_user = user_hist_quota[
                (user_hist_quota["M"] == curr_m)
                & (user_hist_quota["Y"] == curr_y)
            ]
            if not month_user.empty and "Lý do nghỉ" in month_user.columns:
                cp_mask = ~month_user["Lý do nghỉ"].astype(str).str.lower().str.contains(
                    "không phép|phát sinh|lý do khác",
                    na=False,
                    regex=True,
                )
                used_cp = float(
                    pd.to_numeric(
                        month_user.loc[cp_mask, "Số ngày tính"],
                        errors="coerce",
                    ).fillna(0).sum()
                )
            else:
                used_cp = 0.0

            if limit_cp > 0 and used_cp + total_phep_required > limit_cp:
                result["errors"].append(
                    f"Vượt số ngày Có phép trong tháng. Nhân viên này chỉ được nghỉ "
                    f"tối đa {limit_cp:g} ngày/tháng."
                )
                return result

    # Đối chiếu từng ngày bằng CÙNG một snapshot live vừa tải.
    special_day_exempt = is_special_day_rule_exempt(role, reason)
    for target_date in selected_dates:
        # Save function luôn chống trùng đúng lý do, nên báo trước cho cả Admin.
        if _leave_exists_in_sources(source_df, target_date, employee, reason):
            result["errors"].append(
                f"{employee} đã có đúng lý do '{reason}' ngày "
                f"{target_date.strftime('%d/%m/%Y')}."
            )
            return result

        if not is_admin:
            daily_ok, daily_msg = _validate_daily_employee_registration_rule(
                source_df,
                target_date,
                employee,
                reason,
                val_songay,
            )
            if not daily_ok:
                result["errors"].append(
                    f"{employee} · {target_date.strftime('%d/%m/%Y')}: {daily_msg}"
                )
                return result

            if (
                not special_day_exempt
                and not is_nghi_ly_do_khac
                and "phép năm" not in norm_reason
                and not is_loi_vi_pham
            ):
                quota_ok, quota_msg = _validate_daily_group_quota(
                    source_df,
                    target_date,
                    reason,
                    is_zero_day_co_phep=is_zero_day_co_phep,
                )
                if not quota_ok:
                    result["errors"].append(quota_msg)
                    return result

        progressive_reason = get_progressive_penalty_reason(reason)
        if progressive_reason:
            ordinal, extra_penalty = _progressive_ordinal_and_bonus(
                source_df, target_date, reason
            )
            preview_total = default_phat + float(extra_penalty)
            result["warnings"].append(
                f"{target_date.strftime('%d/%m/%Y')}: Người Thứ {ordinal} "
                f"{progressive_reason.lower()} · tổng phạt dự kiến {preview_total:,.0f} VNĐ."
            )

    result["ok"] = True
    return result


def _leave_registration_pending_matches_current(
    pending, start_date, end_date, employee, reason
):
    """Không cho nút Xác nhận cũ tồn tại sau khi user đổi Ngày/NV/Lý do."""
    if not isinstance(pending, dict):
        return False
    return (
        pending.get("start_date") == start_date
        and pending.get("end_date") == end_date
        and normalize_login_name(pending.get("employee", ""))
            == normalize_login_name(employee)
        and normalize_leave_reason(pending.get("reason", ""))
            == normalize_leave_reason(reason)
    )


def validate_employee_leave_change_permission(
    original_row,
    edited_row=None,
    current_user=None,
    today=None,
    action="sửa",
):
    """
    Nhân viên/Leader:
    - chỉ thao tác lịch của chính mình;
    - rule HỦY/SỬA bản ghi cũ lấy từ LoaiNghi!L/M/N theo đúng Lý do nghỉ;
    - khi sửa sang ngày/lý do mới, rule ĐĂNG KÝ mới lấy từ LoaiNghi!I/J/K;
    - vẫn giữ các giới hạn nghiệp vụ về nhóm lý do và ownership.
    """
    today = today or get_vn_today()
    actor = normalize_login_name(current_user or st.session_state.get("current_user", ""))
    owner = normalize_login_name(original_row.get("Tên nhân viên", ""))
    role_now = str(st.session_state.get("current_role", "") or "").strip().lower()

    if not actor or owner != actor:
        return False, "Nhân viên chỉ được thao tác lịch nghỉ của chính mình."

    old_reason = original_row.get("Lý do nghỉ", original_row.get("Loại nghỉ", ""))
    old_dt = pd.to_datetime(original_row.get("Ngày"), errors="coerce", dayfirst=True)
    old_date = old_dt.date() if pd.notna(old_dt) else None

    cancel_ok, cancel_msg = validate_leave_cancel_notice(
        old_reason, old_date, role=role_now, today=today
    )
    if not cancel_ok:
        return False, cancel_msg

    old_is_video = is_video_leave_reason(old_reason)
    old_is_khong_phep = is_employee_khong_phep_leave_reason(old_reason)
    old_is_co_phep = is_employee_co_phep_leave_reason(old_reason)
    old_is_leader_policy = role_now == "leader" and is_leader_policy_leave_reason(old_reason)

    if edited_row is None:
        # J đã quyết định thời hạn hủy. Giữ rule loại lý do cũ:
        if not (old_is_video or old_is_leader_policy or old_is_khong_phep or old_is_co_phep):
            return False, (
                f"Nhân viên/Leader không được {action} lý do này theo quy tắc nghiệp vụ hiện tại."
            )
        return True, ""

    new_owner = normalize_login_name(
        edited_row.get("Tên nhân viên", original_row.get("Tên nhân viên", ""))
    )
    if new_owner != actor:
        return False, "Nhân viên không được đổi lịch sang tên người khác."

    new_reason = edited_row.get("Lý do nghỉ", edited_row.get("Loại nghỉ", old_reason))
    new_dt = pd.to_datetime(edited_row.get("Ngày"), errors="coerce", dayfirst=True)
    new_date = new_dt.date() if pd.notna(new_dt) else None
    if new_date is None:
        return False, "Ngày nghỉ sau khi sửa không hợp lệ."

    new_is_video = is_video_leave_reason(new_reason)
    new_is_khong_phep = is_employee_khong_phep_leave_reason(new_reason)
    new_is_co_phep = is_employee_co_phep_leave_reason(new_reason)

    # Giữ nguyên giới hạn chuyển nhóm nghiệp vụ hiện hành.
    if old_is_leader_policy:
        if not (
            is_leader_policy_leave_reason(new_reason)
            or is_video_leave_reason(new_reason)
        ):
            return False, (
                "Lịch chính sách Leader chỉ được đổi sang lý do chính sách Leader khác "
                "hoặc Nghỉ phép quay video."
            )
    elif old_is_khong_phep:
        if not (new_is_khong_phep or new_is_video):
            return False, (
                "Lịch Nghỉ KHÔNG phép chỉ được sửa sang một Lý do nghỉ KHÔNG phép khác "
                "hoặc Nghỉ phép quay video."
            )
    elif old_is_co_phep:
        if not (new_is_co_phep or new_is_video):
            return False, (
                "Lịch Nghỉ CÓ phép chỉ được thay đổi giữa các Loại nghỉ CÓ phép "
                "hoặc Nghỉ phép quay video."
            )
    elif not old_is_video:
        return False, "Lý do hiện tại không thuộc nhóm Nhân viên/Leader được phép sửa."

    register_ok, register_msg = validate_leave_registration_notice(
        new_reason,
        new_date,
        role=role_now,
        now_vn=datetime.now(VN_TZ),
    )
    if not register_ok:
        return False, register_msg

    return True, ""

def validate_schedule_delete_permission(original_row, role, current_user=None, today=None):
    """Quyền xóa = quyền chức năng + rule LoaiNghi!L/M/N + rule sở hữu/nghiệp vụ."""
    today = today or get_vn_today()
    role = str(role or "").strip().lower()
    if role == "admin":
        return True, ""

    old_reason = original_row.get("Lý do nghỉ", original_row.get("Loại nghỉ", ""))
    dt = pd.to_datetime(original_row.get("Ngày"), errors="coerce", dayfirst=True)
    old_date = dt.date() if pd.notna(dt) else None

    if role in EMPLOYEE_LIKE_ROLES:
        return validate_employee_leave_change_permission(
            original_row, None, current_user=current_user, today=today, action="hủy"
        )

    if role in {"letan", "quanly"}:
        special_today_khong_phep = (
            has_feature_access("leave_today_khong_phep_edit_delete")
            and old_date == today
            and _daily_leave_group(old_reason) == "khong_phep"
        )
        _has_general_leave_delete = (
            has_feature_access("leave_manage_delete")
            or has_feature_access("leave_detail_delete")
        )
        if not (special_today_khong_phep or _has_general_leave_delete):
            return False, (
                "Tài khoản chưa được cấp quyền xóa lịch. Admin có thể cấp quyền Xóa lịch "
                "hoặc quyền riêng KHÔNG PHÉP ngày hiện tại."
            )

        cancel_ok, cancel_msg = validate_leave_cancel_notice(
            old_reason, old_date, role=role, today=today
        )
        if not cancel_ok:
            return False, cancel_msg
        return True, ""

    return False, "Vai trò hiện tại không được phép xóa lịch nghỉ."

def validate_schedule_edit_permission(original_row, edited_row, role, today=None, current_user=None):
    """
    Sửa lịch:
    1) kiểm quyền chức năng;
    2) bản ghi CŨ phải thỏa rule HỦY/SỬA ở LoaiNghi!L/M/N;
    3) bản ghi MỚI phải thỏa rule ĐĂNG KÝ ở LoaiNghi!I/J/K.
    """
    today = today or get_vn_today()
    old_dt = pd.to_datetime(original_row.get("Ngày"), errors="coerce", dayfirst=True)
    new_dt = pd.to_datetime(edited_row.get("Ngày"), errors="coerce", dayfirst=True)
    old_date = old_dt.date() if pd.notna(old_dt) else None
    new_date = new_dt.date() if pd.notna(new_dt) else None
    if old_date is None or new_date is None:
        return False, "Ngày nghỉ không hợp lệ."

    role = str(role or "").strip().lower()
    if role == "admin":
        return True, ""

    if role in EMPLOYEE_LIKE_ROLES:
        permitted, message = validate_employee_leave_change_permission(
            original_row,
            edited_row,
            current_user=current_user,
            today=today,
            action="thay đổi",
        )
        if not permitted:
            return False, message

        # Giữ giới hạn phạm vi lịch tối đa đến hết tháng kế tiếp.
        _, emp_max_date = employee_registration_window(today)
        if new_date > emp_max_date:
            return False, (
                f"Nhân viên chỉ được sửa lịch đến hết {emp_max_date.strftime('%d/%m/%Y')}."
            )

    elif role in {"letan", "quanly"}:
        old_reason = original_row.get("Lý do nghỉ", original_row.get("Loại nghỉ", ""))
        new_reason = edited_row.get("Lý do nghỉ", edited_row.get("Loại nghỉ", old_reason))

        special_today_khong_phep = (
            has_feature_access("leave_today_khong_phep_edit_delete")
            and old_date == today
            and new_date == today
            and _daily_leave_group(old_reason) == "khong_phep"
            and _daily_leave_group(new_reason) == "khong_phep"
        )
        _has_general_leave_edit = (
            has_feature_access("leave_manage_edit")
            or has_feature_access("leave_detail_edit")
        )
        if not (special_today_khong_phep or _has_general_leave_edit):
            return False, (
                "Tài khoản chưa được cấp quyền sửa lịch. Admin có thể cấp quyền Sửa lịch "
                "hoặc quyền riêng KHÔNG PHÉP ngày hiện tại."
            )

        cancel_ok, cancel_msg = validate_leave_cancel_notice(
            old_reason, old_date, role=role, today=today
        )
        if not cancel_ok:
            return False, cancel_msg

        register_ok, register_msg = validate_leave_registration_notice(
            new_reason,
            new_date,
            role=role,
            now_vn=datetime.now(VN_TZ),
        )
        if not register_ok:
            return False, register_msg

    if not str(edited_row.get("Tên nhân viên", "")).strip():
        return False, "Tên nhân viên không được để trống."
    if not str(edited_row.get("Lý do nghỉ", "")).strip():
        return False, "Lý do nghỉ không được để trống."
    return True, ""

def _exclude_original_from_leave_df(df_sources, original_row):
    """Loại đúng bản ghi đang sửa ra khỏi tập dữ liệu dùng để tính lại."""
    if df_sources is None or df_sources.empty:
        return pd.DataFrame(columns=df_sources.columns if hasattr(df_sources, 'columns') else [])
    d = df_sources.copy()

    source_id = str(original_row.get('__source_sheet_id', '')).strip()
    source_row = original_row.get('__source_row', '')
    if source_id and source_row not in ['', None] and '__source_sheet_id' in d.columns and '__source_row' in d.columns:
        try:
            target_row = int(float(source_row))
            row_num = pd.to_numeric(d['__source_row'], errors='coerce')
            exact_mask = (d['__source_sheet_id'].astype(str).str.strip() == source_id) & (row_num == target_row)
            if exact_mask.any():
                return d.loc[~exact_mask].copy()
        except Exception:
            pass

    original_key = schedule_key(original_row)
    keep_mask = d.apply(lambda r: schedule_key(r) != original_key, axis=1)
    return d.loc[keep_mask].copy()


def _strip_generated_progressive_prefix(detail):
    """Bỏ tiền tố 'Người Thứ ...' do hệ thống từng tự thêm để tránh lặp khi sửa."""
    import re
    s = str(detail or '').strip()
    pattern = (
        r'^Người\s+Thứ\s+\d+\s+'
        r'(?:nghỉ\s+không\s+phép|đi\s+trễ\s+không\s+phép|về\s+sớm\s+không\s+phép|ra\s+sớm\s+không\s+phép)'
        r'\s*(?:\|\s*)?'
    )
    return re.sub(pattern, '', s, flags=re.IGNORECASE).strip()


def _get_existing_progressive_ordinal(original_row, all_leave_data=None):
    """
    Lấy đúng thứ tự Người Thứ X của bản ghi hiện hữu để GIỮ NGUYÊN khi sửa
    mà vẫn cùng ngày + cùng nhóm vi phạm lũy tiến.

    Ưu tiên:
    1) Đọc trực tiếp "Người Thứ X" đã lưu trong cột Chi tiết.
    2) Nếu dữ liệu cũ chưa có tiền tố này, suy ra vị trí từ chính bản ghi hiện hữu
       trong dữ liệu 2 nguồn (không coi thao tác sửa là một lượt vi phạm mới).
    """
    import re

    # 1. Bản ghi mới của hệ thống luôn có tiền tố này -> đây là nguồn chính xác nhất.
    detail = str(original_row.get('Chi tiết', '') or '')
    m = re.search(r'Người\s+Thứ\s+(\d+)', detail, flags=re.IGNORECASE)
    if m:
        try:
            return max(1, int(m.group(1)))
        except Exception:
            pass

    # 2. Tương thích dữ liệu cũ chưa ghi "Người Thứ X".
    canonical = get_progressive_penalty_reason(original_row.get('Lý do nghỉ', ''))
    ngay = normalize_schedule_date(original_row.get('Ngày', ''))
    if not canonical or not ngay or all_leave_data is None or getattr(all_leave_data, 'empty', True):
        return None

    d = all_leave_data.copy()
    if 'Ngày' not in d.columns or 'Lý do nghỉ' not in d.columns:
        return None

    d['_date_keep_ord'] = d['Ngày'].apply(normalize_schedule_date)
    d['_reason_keep_ord'] = d['Lý do nghỉ'].astype(str).apply(get_progressive_penalty_reason)
    same = d[(d['_date_keep_ord'] == ngay) & (d['_reason_keep_ord'] == canonical)].copy()
    if same.empty:
        return None

    # Cố gắng tìm đúng bản ghi theo source sheet + source row.
    src_id = str(original_row.get('__source_sheet_id', '') or '').strip()
    src_row = original_row.get('__source_row', None)
    if src_id and src_row not in [None, ''] and '__source_sheet_id' in same.columns and '__source_row' in same.columns:
        try:
            target_row = int(float(src_row))
            same['_src_row_num'] = pd.to_numeric(same['__source_row'], errors='coerce')
            same['_src_sheet_text'] = same['__source_sheet_id'].astype(str).str.strip()
            # Thứ tự lịch sử theo số dòng trong nguồn; nếu có nhiều nguồn thì giữ thứ tự ổn định
            # theo thứ tự hiện hữu trong DataFrame hợp nhất.
            same = same.reset_index(drop=False).rename(columns={'index': '_original_index'})
            match = same[(same['_src_sheet_text'] == src_id) & (same['_src_row_num'] == target_row)]
            if not match.empty:
                matched_original_index = match.iloc[0]['_original_index']
                # Dùng thứ tự xuất hiện trong tập cùng ngày/cùng loại.
                positions = list(same['_original_index'])
                return positions.index(matched_original_index) + 1
        except Exception:
            pass

    # Fallback theo khóa lịch nếu source metadata không còn.
    target_key = schedule_key(original_row)
    same = same.reset_index(drop=False).rename(columns={'index': '_original_index'})
    for idx, r in same.iterrows():
        if schedule_key(r) == target_key:
            return int(idx) + 1
    return None


def recalculate_schedule_fields(original_row, edited_row, updated_by, all_leave_data=None, source_df=None):
    """
    Tự động tính lại các cột phụ thuộc khi sửa lịch:
    - Số ngày tính: theo LoaiNghi
    - Số ngày phép cộng dồn: tổng tháng của nhân viên, loại bản ghi cũ rồi cộng giá trị mới
    - Phạt vi phạm: theo LoaiNghi + phạt lũy tiến nếu thuộc 3 nhóm vi phạm
    - Ngày/Giờ/Người cập nhật: theo thời điểm và tài khoản đang thao tác
    """
    catalog = build_leave_reason_catalog(source_df)
    result = edited_row.copy()

    ngay = normalize_schedule_date(result.get('Ngày', original_row.get('Ngày', '')))
    nv = str(result.get('Tên nhân viên', original_row.get('Tên nhân viên', ''))).strip()
    reason = clean_leave_reason_display(result.get('Lý do nghỉ', original_row.get('Lý do nghỉ', '')))
    key = normalize_leave_reason(reason)
    defaults = catalog.get(key)

    if defaults:
        reason = defaults['name']
        so_ngay = float(defaults['days'])
        base_penalty = float(defaults['penalty'])
    else:
        # Với dữ liệu lịch sử không còn trong LoaiNghi, giữ giá trị cũ để tránh làm mất dữ liệu.
        so_ngay = _parse_leave_number(original_row.get('Số ngày tính', result.get('Số ngày tính', 0)), 0.0)
        base_penalty = _parse_leave_number(original_row.get('Phạt vi phạm', result.get('Phạt vi phạm', 0)), 0.0, money=True)

    others = _exclude_original_from_leave_df(all_leave_data, original_row)

    # Tính số ngày phép cộng dồn trong cùng tháng/năm của đúng nhân viên.
    dt = pd.to_datetime(ngay, errors='coerce', dayfirst=True)
    accumulated = float(so_ngay)
    if pd.notna(dt) and others is not None and not others.empty:
        d = others.copy()
        d['_dt_calc'] = pd.to_datetime(d['Ngày'], errors='coerce', dayfirst=True)
        d['_days_calc'] = pd.to_numeric(d['Số ngày tính'], errors='coerce').fillna(0)
        same_emp = d['Tên nhân viên'].astype(str).apply(normalize_login_name).eq(normalize_login_name(nv))
        same_month = d['_dt_calc'].dt.month.eq(dt.month) & d['_dt_calc'].dt.year.eq(dt.year)
        accumulated = float(d.loc[same_emp & same_month, '_days_calc'].sum()) + float(so_ngay)

    # Phạt lũy tiến cho Nghỉ không phép / Đi trễ không phép / Về sớm không phép.
    final_penalty = float(base_penalty)
    detail = _strip_generated_progressive_prefix(result.get('Chi tiết', original_row.get('Chi tiết', '')))
    progressive_reason = get_progressive_penalty_reason(reason)
    if progressive_reason:
        # Nếu chỉ sửa nội dung nhưng vẫn cùng ngày + cùng nhóm vi phạm, giữ đúng
        # thứ tự Người Thứ đã ghi trước đó. Nếu đổi ngày/đổi loại thì tính lại thứ tự.
        ordinal = None
        original_reason = clean_leave_reason_display(original_row.get('Lý do nghỉ', ''))
        original_canonical = get_progressive_penalty_reason(original_reason)
        original_date = normalize_schedule_date(original_row.get('Ngày', ''))

        # QUY TẮC QUAN TRỌNG KHI SỬA:
        # Nếu vẫn cùng NGÀY + cùng NHÓM VI PHẠM thì đây vẫn là cùng một người/lượt cũ.
        # Tuyệt đối không đẩy Người Thứ 1 thành Người Thứ 2/3 chỉ vì bấm Sửa/Lưu lại.
        if original_canonical == progressive_reason and original_date == ngay:
            ordinal = _get_existing_progressive_ordinal(original_row, all_leave_data)

        # Chỉ cấp thứ tự mới khi thực sự đổi ngày hoặc đổi sang nhóm vi phạm khác,
        # hoặc dữ liệu lịch sử quá cũ không thể xác định thứ tự cũ.
        if ordinal is None:
            ordinal, _ = _progressive_ordinal_and_bonus(others, ngay, reason)
        extra_penalty = max(0, int(ordinal) - 2) * 100000
        final_penalty += float(extra_penalty)
        ordinal_note = f"Người Thứ {ordinal} {progressive_reason.lower()}"
        detail = f"{ordinal_note} | {detail}" if detail else ordinal_note

    now_vn = datetime.now(VN_TZ)
    result['Ngày'] = ngay
    result['Tên nhân viên'] = nv
    result['Lý do nghỉ'] = reason
    result['Thứ ngày'] = _vn_weekday_label(ngay)
    result['Loại nghỉ'] = _leave_type_for_reason(reason, source_df)
    result['Chi tiết'] = detail
    result['Số ngày tính'] = float(so_ngay)
    result['Số ngày phép cộng dồn'] = float(accumulated)
    result['Phạt vi phạm'] = float(final_penalty)
    result['Ngày cập nhật'] = now_vn.strftime('%d/%m/%Y')
    result['Giờ cập nhật'] = now_vn.strftime('%H:%M:%S')
    result['Người cập nhật'] = str(updated_by)
    return result


def _load_live_primary_leave_sheet(client):
    """V92.6.16: đọc DUY NHẤT Sheet1 chính A:M và giữ đúng số dòng vật lý."""
    primary = client.open_by_key(SHEET_DU_PHONG_ID).get_worksheet(0)
    df_primary = _read_leave_sheet_with_source(primary, SHEET_DU_PHONG_ID)
    return combine_leave_sources_for_daily_stats(df_primary)

def _read_leave_sheet_with_source(sheet, source_id):
    """Đọc A:M theo header thực tế; giữ raw row để sửa an toàn."""
    expected = LEAVE_DATA_COLUMNS
    try:
        headers = _get_leave_sheet_headers(sheet, strict=True)
        values = _gs_call_with_backoff(sheet.get, LEAVE_MAIN_RANGE)
        if not values or len(values) < 2:
            return pd.DataFrame(columns=expected + ["__source_sheet_id", "__source_row", "__raw_values"])
        rows = []
        for sheet_row, raw in enumerate(values[1:], start=2):
            vals = list(raw[:13]) + [""] * max(0, 13 - len(raw))
            if not any(str(v).strip() for v in vals):
                continue
            item = _leave_sheet_row_to_record(vals, headers)
            if not item.get("Thứ ngày"):
                item["Thứ ngày"] = _vn_weekday_label(item.get("Ngày", ""))
            if not item.get("Loại nghỉ"):
                item["Loại nghỉ"] = _leave_type_for_reason(item.get("Lý do nghỉ", ""))
            item["__source_sheet_id"] = str(source_id)
            item["__source_row"] = int(sheet_row)
            item["__raw_values"] = vals
            rows.append(item)
        return pd.DataFrame(rows) if rows else pd.DataFrame(
            columns=expected + ["__source_sheet_id", "__source_row", "__raw_values"]
        )
    except Exception:
        return pd.DataFrame(columns=expected + ["__source_sheet_id", "__source_row", "__raw_values"])

def _extract_progressive_ordinal(detail):
    """Lấy số X từ tiền tố 'Người Thứ X ...'."""
    try:
        m = re.search(r'Người\s+Thứ\s+(\d+)', str(detail or ''), flags=re.IGNORECASE)
        return max(1, int(m.group(1))) if m else None
    except Exception:
        return None


def _progressive_group_key(row):
    """Khóa nhóm phạt lũy tiến = (ngày, loại chuẩn)."""
    canonical = get_progressive_penalty_reason(row.get('Lý do nghỉ', ''))
    ngay = normalize_schedule_date(row.get('Ngày', ''))
    if not canonical or not ngay:
        return None
    return (str(ngay), str(canonical))


def _existing_base_penalty(row, catalog):
    """Lấy mức phạt gốc, tách phần lũy tiến khỏi tổng tiền hiện có khi cần."""
    reason = clean_leave_reason_display(row.get('Lý do nghỉ', ''))
    key = normalize_leave_reason(reason)
    if key in catalog:
        return float(catalog[key].get('penalty', 0) or 0)

    canonical = get_progressive_penalty_reason(reason)
    if canonical:
        for item in catalog.values():
            if get_progressive_penalty_reason(item.get('name', '')) == canonical:
                return float(item.get('penalty', 0) or 0)

    current_total = _parse_leave_number(row.get('Phạt vi phạm', 0), 0.0, money=True)
    old_ordinal = _extract_progressive_ordinal(row.get('Chi tiết', ''))
    old_extra = max(0, int(old_ordinal or 1) - 2) * 100000
    return max(0.0, float(current_total) - float(old_extra))


def rebalance_progressive_penalty_groups(client, affected_groups, updated_by):
    """Xếp lại Người Thứ X/phạt lũy tiến trên Sheet1 chính; ghi các cột G:M."""
    clean_groups = set()
    for item in affected_groups or []:
        try:
            ngay, canonical = item
            if ngay and canonical:
                clean_groups.add((str(ngay), str(canonical)))
        except Exception:
            continue
    if not clean_groups:
        return 0

    primary_sheet = client.open_by_key(SHEET_DU_PHONG_ID).get_worksheet(0)
    raw_all = _read_leave_sheet_with_source(primary_sheet, SHEET_DU_PHONG_ID)
    if raw_all is None or raw_all.empty:
        return 0
    raw_all['_reb_date'] = raw_all['Ngày'].apply(normalize_schedule_date)
    raw_all['_reb_reason'] = raw_all['Lý do nghỉ'].astype(str).apply(get_progressive_penalty_reason)

    catalog = build_leave_reason_catalog(globals().get('df_loai_nghi', pd.DataFrame()))
    now_vn = datetime.now(VN_TZ)
    actor = str(updated_by or 'Hệ thống')
    update_date = now_vn.strftime('%d/%m/%Y')
    update_time = now_vn.strftime('%H:%M:%S')
    updated_physical_rows = 0

    for ngay, canonical in sorted(clean_groups):
        group = raw_all[(raw_all['_reb_date'] == ngay) & (raw_all['_reb_reason'] == canonical)].copy()
        if group.empty:
            continue

        ordered = []
        for _, r in group.iterrows():
            old_ordinal = _extract_progressive_ordinal(r.get('Chi tiết', ''))
            try:
                row_idx = int(float(r.get('__source_row')))
            except Exception:
                continue
            ordered.append((old_ordinal, row_idx, r.copy()))
        ordered.sort(key=lambda x: (
            x[0] is None,
            x[0] if x[0] is not None else 10**9,
            x[1],
            normalize_login_name(x[2].get('Tên nhân viên', '')),
        ))

        for new_ordinal, (_, row_idx, physical) in enumerate(ordered, start=1):
            base_penalty = _existing_base_penalty(physical, catalog)
            extra_penalty = max(0, new_ordinal - 2) * 100000
            new_penalty = float(base_penalty) + float(extra_penalty)
            prefix = f"Người Thứ {new_ordinal} {canonical.lower()}"
            user_note = _strip_generated_progressive_prefix(physical.get('Chi tiết', ''))
            new_detail = f"{prefix} | {user_note}" if user_note else prefix

            current = primary_sheet.get(f"A{row_idx}:M{row_idx}")
            existing = list(current[0]) if current else [""] * 13
            updated_record = physical.to_dict() if hasattr(physical, "to_dict") else dict(physical)
            updated_record.update({
                "Chi tiết": new_detail,
                "Phạt vi phạm": new_penalty,
                "Ngày cập nhật": update_date,
                "Giờ cập nhật": update_time,
                "Người cập nhật": actor,
            })
            sheet_headers = _get_leave_sheet_headers(primary_sheet, strict=True)
            safe_values = _leave_record_to_sheet_row(
                updated_record,
                sheet_headers=sheet_headers,
                existing_values=existing,
            )
            gspread_update_range(
                primary_sheet,
                f"A{row_idx}:M{row_idx}",
                [safe_values],
                value_input_option='USER_ENTERED',
            )
            updated_physical_rows += 1

    if updated_physical_rows:
        _clear_leave_data_caches()
    return updated_physical_rows

def update_schedule_record(original_row, edited_row, updated_by):
    """Sửa đúng dòng Sheet1 chính theo schema A:M và tự xếp lại phạt lũy tiến."""
    try:
        client = get_gspread_client()
        if not client:
            return False, "Chưa cấu hình quyền kết nối Google Sheets."

        affected_groups = set()
        old_group = _progressive_group_key(original_row)
        if old_group:
            affected_groups.add(old_group)

        live_all = _load_live_primary_leave_sheet(client)
        _actor_role_direct_v92638 = str(
            st.session_state.get("current_role", "") or ""
        ).strip().lower()
        _admin_direct_v92638 = _actor_role_direct_v92638 == "admin"

        if _admin_direct_v92638:
            # V92.6.38: Admin sửa trực tiếp toàn bộ cột hiển thị.
            # Không tự tính lại Loại nghỉ / Số ngày / Phạt / metadata để đè giá trị Admin nhập.
            recalculated = edited_row.copy()
        else:
            recalculated = recalculate_schedule_fields(
                original_row,
                edited_row,
                updated_by,
                all_leave_data=live_all,
                source_df=globals().get('df_loai_nghi', pd.DataFrame()),
            )

        ngay = normalize_schedule_date(recalculated.get('Ngày', ''))
        nv = str(recalculated.get('Tên nhân viên', '')).strip()
        lydo = clean_leave_reason_display(recalculated.get('Lý do nghỉ', ''))
        if not nv or not lydo:
            return False, "Tên nhân viên và Lý do nghỉ không được để trống."

        others = _exclude_original_from_leave_df(live_all, original_row)
        if _leave_exists_in_sources(others, ngay, nv, lydo):
            return False, f"'{nv}' đã có đúng lý do '{lydo}' trong ngày {ngay}. Có thể ghi thêm nếu là lý do khác."

        recalculated['Ngày'] = ngay
        if not _admin_direct_v92638:
            recalculated['Thứ ngày'] = _vn_weekday_label(ngay)
            recalculated['Loại nghỉ'] = _leave_type_for_reason(lydo)

        target = client.open_by_key(SHEET_DU_PHONG_ID).get_worksheet(0)
        sheet_headers = _get_leave_sheet_headers(target, strict=True)
        row_idx = None
        try:
            if str(original_row.get('__source_sheet_id', '')).strip() == SHEET_DU_PHONG_ID:
                row_idx = int(float(original_row.get('__source_row')))
        except Exception:
            row_idx = None
        if not row_idx:
            row_idx = _find_schedule_row_index(target, original_row)
        if not row_idx:
            return False, "Không tìm thấy dòng tương ứng trong Google Sheet chính."
        current = target.get(f"A{row_idx}:M{row_idx}")
        existing = list(current[0]) if current else [""] * 13
        new_values = _leave_record_to_sheet_row(
            recalculated,
            sheet_headers=sheet_headers,
            existing_values=existing,
        )
        gspread_update_range(target, f'A{row_idx}:M{row_idx}', [new_values], raw=False)

        if _admin_direct_v92638:
            # Admin đã nhập trực tiếp tất cả giá trị, không cho rebalance ghi đè Chi tiết/Phạt.
            rebalanced = 0
        else:
            new_group = _progressive_group_key(recalculated)
            if new_group:
                affected_groups.add(new_group)
            rebalanced = rebalance_progressive_penalty_groups(client, affected_groups, updated_by)

        # Đọc lại đúng trạng thái SAU cùng sau rebalance để audit chính xác.
        _audit_after_row = recalculated
        try:
            _after_values = target.get(f"A{row_idx}:M{row_idx}")
            if _after_values and _after_values[0]:
                _audit_after_row = _leave_sheet_row_to_record(
                    _after_values[0], sheet_headers
                )
        except Exception:
            pass

        _audit_suffix = ""
        _actor_role = str(
            st.session_state.get("current_role", "") or ""
        ).strip().lower()
        if _actor_role in {"letan", "quanly"}:
            _audit_ok, _audit_msg = notify_admin_leave_schedule_change(
                "edit",
                updated_by,
                _actor_role,
                original_row,
                _audit_after_row,
            )
            if _audit_msg:
                _audit_suffix = (
                    " · 🔔 " if _audit_ok else " · ⚠️ "
                ) + str(_audit_msg)

        _clear_leave_data_caches()
        if rebalanced:
            return True, (
                f"Đã cập nhật lịch nghỉ và tự xếp lại thứ tự/phạt lũy tiến cho "
                f"{rebalanced} bản ghi trong nhóm bị ảnh hưởng."
                + _audit_suffix
            )
        return True, "Đã cập nhật lịch nghỉ thành công." + _audit_suffix
    except Exception as e:
        return False, f"Lỗi cập nhật lịch nghỉ: {e}"

def delete_schedule_records(original_rows, updated_by=None):
    """V92.6.16: xóa record CHỈ ở Sheet1 chính A:M."""
    try:
        client = get_gspread_client()
        if not client:
            return False, "Chưa cấu hình quyền kết nối Google Sheets."
        actor = str(updated_by or st.session_state.get("current_user", "Hệ thống"))

        target_keys = {schedule_key(r) for r in (original_rows or []) if schedule_key(r)}
        affected_groups = set()
        for row in (original_rows or []):
            group_key = _progressive_group_key(row)
            if group_key:
                affected_groups.add(group_key)
        if not target_keys:
            return False, "Không tìm thấy lịch cần xóa."

        target = client.open_by_key(SHEET_DU_PHONG_ID).get_worksheet(0)
        data = _read_leave_sheet_with_source(target, SHEET_DU_PHONG_ID)
        indices = []
        matched_delete_records = []
        if isinstance(data, pd.DataFrame) and not data.empty:
            for _, row in data.iterrows():
                if schedule_key(row) in target_keys:
                    g = _progressive_group_key(row)
                    if g:
                        affected_groups.add(g)
                    matched_delete_records.append(
                        row.to_dict() if hasattr(row, "to_dict") else dict(row)
                    )
                    try:
                        indices.append(int(float(row.get('__source_row'))))
                    except Exception:
                        pass

        deleted = 0
        for idx in sorted(set(indices), reverse=True):
            _gs_call_with_backoff(target.delete_rows, idx)
            deleted += 1

        rebalanced = rebalance_progressive_penalty_groups(client, affected_groups, actor) if affected_groups else 0

        if deleted <= 0:
            _clear_leave_data_caches()
            return False, "Không tìm thấy dòng tương ứng trong Google Sheet để xóa."

        _audit_messages = []
        _actor_role = str(
            st.session_state.get("current_role", "") or ""
        ).strip().lower()
        if _actor_role in {"letan", "quanly"}:
            for _deleted_record in matched_delete_records:
                _audit_ok, _audit_msg = notify_admin_leave_schedule_change(
                    "delete",
                    actor,
                    _actor_role,
                    _deleted_record,
                    None,
                )
                if _audit_msg:
                    _audit_messages.append(
                        ("🔔 " if _audit_ok else "⚠️ ") + str(_audit_msg)
                    )

        _clear_leave_data_caches()
        _audit_suffix = (
            " · " + " | ".join(_audit_messages)
            if _audit_messages else ""
        )

        if rebalanced:
            return True, (
                f"Đã xóa {deleted} dòng và tự xếp lại thứ tự/phạt lũy tiến cho "
                f"{rebalanced} bản ghi còn lại."
                + _audit_suffix
            )
        return True, f"Đã xóa {deleted} dòng lịch nghỉ." + _audit_suffix
    except Exception as e:
        return False, f"Lỗi xóa lịch nghỉ: {e}"

def download_file_from_google_drive(id, destination):
    """Tải file nhị phân từ Google Drive, hỗ trợ trang confirm của file lớn."""
    session = requests.Session()
    errors = []

    # Endpoint usercontent thường ổn định hơn với file Excel nhị phân công khai.
    urls = [
        f"https://drive.usercontent.google.com/download?id={id}&export=download&confirm=t",
        f"https://drive.google.com/uc?export=download&id={id}&confirm=t",
    ]

    for url in urls:
        try:
            response = session.get(url, stream=True, timeout=60, allow_redirects=True)
            response.raise_for_status()

            # Một số file lớn vẫn trả trang confirm; thử lấy token từ HTML/cookie.
            ctype = str(response.headers.get('Content-Type', '')).lower()
            if 'text/html' in ctype:
                html = response.text
                token = next((v for k, v in response.cookies.items() if k.startswith('download_warning')), None)
                if not token:
                    m = re.search(r'confirm=([0-9A-Za-z_-]+)', html)
                    token = m.group(1) if m else None
                if token:
                    response = session.get(
                        "https://drive.google.com/uc",
                        params={'export': 'download', 'id': id, 'confirm': token},
                        stream=True, timeout=60, allow_redirects=True
                    )
                    response.raise_for_status()

            with open(destination, "wb") as f:
                for chunk in response.iter_content(1024 * 1024):
                    if chunk:
                        f.write(chunk)

            if os.path.exists(destination) and os.path.getsize(destination) > 0:
                return destination
        except Exception as e:
            errors.append(str(e))
            try:
                if os.path.exists(destination):
                    os.remove(destination)
            except Exception:
                pass

    raise RuntimeError("Không tải được file Google Drive: " + " | ".join(errors[-2:]))


def _excel_col_letter(idx):
    n = idx + 1
    out = ""
    while n:
        n, rem = divmod(n - 1, 26)
        out = chr(65 + rem) + out
    return out


@st.cache_data(ttl=90, show_spinner=False)
def load_bang_tour_input():
    """V92.0: đọc TourVera XLSM; cache nguồn 90 giây, nút Làm mới có thể clear ngay."""
    temp_file = f"temp_bangtour_{os.getpid()}_{int(time.time())}.xlsm"
    try:
        download_file_from_google_drive(BANG_TOUR_FILE_ID, temp_file)

        # XLSM là gói ZIP. Nếu không phải ZIP thì gần như chắc chắn Google Drive
        # đã trả HTML (đăng nhập/xác nhận quyền truy cập), không phải file Excel.
        if not zipfile.is_zipfile(temp_file):
            preview = ""
            try:
                preview = open(temp_file, 'r', encoding='utf-8', errors='ignore').read(180)
            except Exception:
                pass
            hint = " Google Drive đang trả trang HTML thay vì file XLSM." if '<html' in preview.lower() else ""
            return pd.DataFrame(), (
                "File tải về không phải XLSM hợp lệ." + hint +
                " Hãy đặt quyền file thành 'Bất kỳ ai có đường liên kết' hoặc cấp quyền cho service account."
            )

        # File đã xác nhận là .xlsm nên dùng openpyxl trực tiếp; không dùng pyxlsb.
        raw = pd.read_excel(temp_file, sheet_name="Input", header=None, engine="openpyxl")
        if raw.empty:
            return pd.DataFrame(), "Sheet Input đang trống."

        # Hệ thống Tour Vera dùng dòng 20 làm header và dữ liệu từ dòng 21.
        header_idx = 19 if len(raw) > 19 else 0
        # VBA người dùng gửi có rule đến cột X -> giữ tối đa A:X.
        max_cols = min(24, raw.shape[1])
        raw = raw.iloc[:, :max_cols]
        header_vals = raw.iloc[header_idx].tolist()

        headers = []
        seen = {}
        for i, v in enumerate(header_vals):
            txt = "" if pd.isna(v) else str(v).strip()
            if not txt or txt.lower() == "nan":
                txt = _excel_col_letter(i)
            if txt in seen:
                seen[txt] += 1
                txt = f"{txt} ({_excel_col_letter(i)})"
            else:
                seen[txt] = 1
            headers.append(txt)

        df = raw.iloc[header_idx + 1:].copy()
        df.columns = headers
        df = df.dropna(how="all").reset_index(drop=True)
        df.attrs["excel_header_row"] = header_idx + 1
        # Lưu vị trí cột gốc Excel để việc đổi thứ tự hiển thị không làm sai rule màu.
        df.attrs["excel_col_index"] = {headers[i]: i for i in range(len(headers))}
        return df, ""
    except ValueError as e:
        return pd.DataFrame(), f"Không đọc được sheet Input trong file XLSM: {e}"
    except Exception as e:
        return pd.DataFrame(), f"Lỗi tải/đọc Bảng tour XLSM: {e}"
    finally:
        try:
            if os.path.exists(temp_file):
                os.remove(temp_file)
        except Exception:
            pass


def _tour_text(v):
    if pd.isna(v):
        return ""
    return str(v).strip()


def _tour_num(v):
    try:
        if pd.isna(v) or str(v).strip() == "":
            return None
        return float(str(v).replace(",", "").strip())
    except Exception:
        return None


def _find_tour_col(df, wanted):
    """Tìm tên cột theo kiểu không dấu/không phân biệt hoa thường."""
    wanted_norm = remove_vietnamese_accents(str(wanted)).casefold().strip()
    exact = []
    contains = []
    for c in df.columns:
        norm = remove_vietnamese_accents(str(c)).casefold().strip()
        if norm == wanted_norm:
            exact.append(c)
        elif wanted_norm in norm:
            contains.append(c)
    return exact[0] if exact else (contains[0] if contains else None)


def _find_tour_col_any(df, candidates):
    for wanted in candidates:
        c = _find_tour_col(df, wanted)
        if c is not None:
            return c
    return None


def _tour_duration_to_minutes(v):
    """Đổi Thời lượng từ Excel/string/timedelta sang phút."""
    if v is None:
        return None
    try:
        if pd.isna(v):
            return None
    except Exception:
        pass

    if isinstance(v, pd.Timedelta):
        return float(v.total_seconds() / 60.0)
    if isinstance(v, timedelta):
        return float(v.total_seconds() / 60.0)

    # Excel có thể lưu duration là số phút hoặc fraction của 1 ngày.
    if isinstance(v, numbers.Number) and not isinstance(v, bool):
        n = float(v)
        if 0 < abs(n) < 1:
            return abs(n) * 1440.0
        return abs(n)

    s = str(v).strip()
    if not s or s.casefold() in {"nan", "none", "nat", "<na>"}:
        return None

    # 01:30 / 01:30:00
    m = re.fullmatch(r"\s*(\d{1,3}):(\d{1,2})(?::(\d{1,2}))?\s*", s)
    if m:
        hh = int(m.group(1))
        mm = int(m.group(2))
        ss = int(m.group(3) or 0)
        return hh * 60.0 + mm + ss / 60.0

    # "90", "90 phút", "90 min"
    m = re.search(r"[-+]?\d+(?:[.,]\d+)?", s)
    if m:
        try:
            n = float(m.group(0).replace(",", "."))
            if 0 < abs(n) < 1 and any(x in s.casefold() for x in [":", "day", "ngày"]):
                return abs(n) * 1440.0
            return abs(n)
        except Exception:
            pass
    return None


def _tour_start_to_datetime(v, now_dt, duration_minutes=None):
    """
    Đổi ô TG bắt đầu sang datetime VN.
    Nếu Excel chỉ lưu giờ, ghép với ngày hiện tại; sau 0h có thể suy ra ca bắt đầu từ hôm trước.
    """
    if v is None:
        return None
    try:
        if pd.isna(v):
            return None
    except Exception:
        pass

    explicit_date = False
    t_obj = None
    dt_obj = None

    if isinstance(v, pd.Timestamp):
        dt_obj = v.to_pydatetime()
        explicit_date = True
    elif isinstance(v, datetime):
        dt_obj = v
        explicit_date = True
    elif isinstance(v, time.struct_time):
        t_obj = datetime(
            now_dt.year, now_dt.month, now_dt.day,
            v.tm_hour, v.tm_min, v.tm_sec, tzinfo=VN_TZ
        )
    elif hasattr(v, "hour") and hasattr(v, "minute") and not isinstance(v, date):
        # datetime.time
        try:
            t_obj = datetime(
                now_dt.year, now_dt.month, now_dt.day,
                int(v.hour), int(v.minute), int(getattr(v, "second", 0) or 0),
                tzinfo=VN_TZ
            )
        except Exception:
            t_obj = None
    elif isinstance(v, numbers.Number) and not isinstance(v, bool):
        n = float(v)
        if 0 <= n < 1:
            secs = int(round(n * 86400)) % 86400
            t_obj = datetime(
                now_dt.year, now_dt.month, now_dt.day,
                secs // 3600, (secs % 3600) // 60, secs % 60,
                tzinfo=VN_TZ
            )
        elif n >= 1:
            try:
                # Excel serial date.
                dt_obj = (datetime(1899, 12, 30) + timedelta(days=n))
                explicit_date = True
            except Exception:
                dt_obj = None
    else:
        s = str(v).strip()
        if not s or s.casefold() in {"nan", "none", "nat", "<na>"}:
            return None

        # Có ngày + giờ.
        date_patterns = [
            "%d/%m/%Y %H:%M:%S", "%d/%m/%Y %H:%M",
            "%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M",
        ]
        for fmt in date_patterns:
            try:
                dt_obj = datetime.strptime(s, fmt)
                explicit_date = True
                break
            except Exception:
                pass

        if dt_obj is None:
            # Chỉ giờ.
            for fmt in ["%H:%M:%S", "%H:%M"]:
                try:
                    tt = datetime.strptime(s, fmt)
                    t_obj = datetime(
                        now_dt.year, now_dt.month, now_dt.day,
                        tt.hour, tt.minute, tt.second, tzinfo=VN_TZ
                    )
                    break
                except Exception:
                    pass

        if dt_obj is None and t_obj is None:
            try:
                parsed = pd.to_datetime(s, dayfirst=True, errors="coerce")
                if not pd.isna(parsed):
                    dt_obj = parsed.to_pydatetime()
                    explicit_date = bool(re.search(r"\d{1,4}[/-]\d{1,2}[/-]\d{1,4}", s))
            except Exception:
                pass

    if dt_obj is not None:
        if dt_obj.tzinfo is None:
            dt_obj = dt_obj.replace(tzinfo=VN_TZ)
        else:
            dt_obj = dt_obj.astimezone(VN_TZ)

        # Excel time-only đôi khi thành ngày 1899/1900.
        if dt_obj.year <= 1901 and not explicit_date:
            t_obj = datetime(
                now_dt.year, now_dt.month, now_dt.day,
                dt_obj.hour, dt_obj.minute, dt_obj.second,
                tzinfo=VN_TZ
            )
        elif dt_obj.year <= 1901:
            t_obj = datetime(
                now_dt.year, now_dt.month, now_dt.day,
                dt_obj.hour, dt_obj.minute, dt_obj.second,
                tzinfo=VN_TZ
            )
        else:
            return dt_obj

    if t_obj is None:
        return None

    # Nếu giờ ghép hôm nay đang ở tương lai, thử xem có phải tour bắt đầu tối hôm trước.
    if t_obj > now_dt:
        yesterday = t_obj - timedelta(days=1)
        elapsed_yesterday = (now_dt - yesterday).total_seconds() / 60.0
        plausible_window = max(
            float(duration_minutes or 0) + 240.0,
            8 * 60.0
        )
        if 0 <= elapsed_yesterday <= plausible_window:
            return yesterday

    return t_obj


def apply_live_tour_countdown(df, now_dt=None):
    """
    V91.4 - KHÔNG dùng giá trị 'Thời gian còn lại' từ TourVera.

    1) Yêu cầu rỗng:
       TG bắt đầu thực hiện + Thời lượng.
    2) Yêu cầu = YC:
       TG bắt đầu thực hiện YC + Thời lượng.

    Kết quả = Thời lượng - số phút đã trôi qua.
    """
    if not isinstance(df, pd.DataFrame) or df.empty:
        return df

    out = df.copy()
    out.attrs.update(df.attrs)
    now_dt = now_dt or datetime.now(VN_TZ)

    request_col = _find_tour_col_any(out, [
        "Yêu cầu", "Yeu cau",
    ])
    duration_col = _find_tour_col_any(out, [
        "Thời lượng", "Thoi luong", "Thời lượng (phút)", "Thời lượng phút",
    ])
    start_normal_col = _find_tour_col_any(out, [
        "TG bắt đầu thực hiện",
        "TG bat dau thuc hien",
        "BĐ thực hiện",
        "BD thuc hien",
        "Bắt đầu thực hiện",
    ])
    start_yc_col = _find_tour_col_any(out, [
        "TG bắt đầu thực hiện YC",
        "TG bat dau thuc hien YC",
        "BĐ thực hiện YC",
        "BD thuc hien YC",
        "BĐ YC",
        "BD YC",
        "Bắt đầu thực hiện YC",
    ])
    remain_col = _find_tour_col(out, "Thời gian còn lại")

    if remain_col is None:
        remain_col = "Thời gian còn lại"
        out[remain_col] = ""

    # Nếu thiếu cột cốt lõi thì vẫn xóa dữ liệu remaining nguồn để không vô tình dùng lại.
    if duration_col is None:
        out[remain_col] = ""
        out.attrs["_tour_countdown_error"] = "Không tìm thấy cột Thời lượng."
        return out

    remaining_values = []
    source_modes = []

    for idx, row in out.iterrows():
        req_token = _tour_norm_token(row.get(request_col, "")) if request_col else ""
        duration_min = _tour_duration_to_minutes(row.get(duration_col, ""))

        start_col = None
        mode = ""
        if req_token == "yc":
            start_col = start_yc_col
            mode = "YC"
        elif req_token == "":
            start_col = start_normal_col
            mode = "THƯỜNG"
        else:
            # Theo quy tắc người dùng: chỉ 2 trường hợp rỗng hoặc YC.
            start_col = None
            mode = "KHÁC"

        start_dt = (
            _tour_start_to_datetime(
                row.get(start_col, "") if start_col else None,
                now_dt,
                duration_min
            )
            if start_col else None
        )

        if duration_min is None or start_dt is None:
            remaining_values.append("")
            source_modes.append(mode)
            continue

        elapsed_min = (now_dt - start_dt).total_seconds() / 60.0

        # Nếu thời gian bắt đầu thật sự nằm trong tương lai thì chưa countdown.
        if elapsed_min < 0:
            remaining_values.append("")
            source_modes.append(mode)
            continue

        remaining = float(duration_min) - elapsed_min
        # Hiển thị theo phút nguyên, giảm 1 đơn vị khi một phút thực tế trôi qua.
        remaining_values.append(int(math.ceil(remaining)))
        source_modes.append(mode)

    out[remain_col] = remaining_values
    out.attrs["_tour_countdown_live"] = True
    out.attrs["_tour_countdown_at"] = now_dt.isoformat()
    out.attrs["_tour_countdown_columns"] = {
        "request": request_col,
        "duration": duration_col,
        "start_normal": start_normal_col,
        "start_yc": start_yc_col,
        "remaining": remain_col,
    }
    return out


def reorder_bang_tour_columns(df):
    """
    Chỉ đổi thứ tự HIỂN THỊ:
    Tên Nhân Viên -> Trạng Thái -> Thời gian còn lại -> các cột còn lại.
    Vị trí cột Excel gốc vẫn được giữ trong df.attrs để tô màu đúng.
    """
    if df.empty:
        return df

    name_col = _find_tour_col(df, "Tên nhân viên")
    status_col = _find_tour_col(df, "Trạng thái")
    remain_col = _find_tour_col(df, "Thời gian còn lại")

    cols = list(df.columns)
    moved = [c for c in [status_col, remain_col] if c is not None]
    base = [c for c in cols if c not in moved]

    if name_col and name_col in base:
        pos = base.index(name_col) + 1
        for c in reversed(moved):
            base.insert(pos, c)
    else:
        # Nếu workbook đổi tên cột thì vẫn ưu tiên đưa hai cột này ra đầu.
        base = moved + base

    out = df.loc[:, base].copy()
    out.attrs.update(df.attrs)
    return out


def _tour_norm_token(v):
    """Chuẩn hóa text Tour: không dấu, không phân biệt hoa/thường, bỏ _ và - thừa."""
    txt = remove_vietnamese_accents(_tour_text(v)).casefold()
    txt = txt.replace("_", " ").replace("-", " ")
    return " ".join(txt.split())


def prepare_bang_tour_display(df):
    """
    Chuẩn bị dữ liệu HIỂN THỊ cho Bảng tour sau khi đọc từ file:
    - Tên Nhân Viên -> Trạng Thái -> Thời gian còn lại -> các cột khác.
    - DANG CHO -> Đang chờ; DANG THUC HIEN -> Đang thực hiện.
    - Mọi giá trị số hiển thị dạng SỐ NGUYÊN, không có phần thập phân.
    - None / NaN / NaT / <NA> được đổi thành ô trống thật sự.
    - Thời gian còn lại là countdown do app tự tính; không dùng giá trị nguồn từ TourVera.
    - Thời gian còn lại <= -15 được làm trống trên giao diện.
    - Cột Thời gian: nếu là số âm nhỏ hơn -180 (độ âm vượt 180 phút) thì làm trống trên giao diện.
    """
    out = reorder_bang_tour_columns(df).copy()

    # Ghi nhớ các dòng có thời gian <= -15 trước khi làm trống để không nhầm thành "Đang rảnh".
    expired_indices = set()
    remain_col = _find_tour_col(out, "Thời gian còn lại")
    if remain_col is not None:
        raw_remain = out[remain_col].apply(_tour_num)
        expired_indices = set(raw_remain[raw_remain.apply(lambda x: x is not None and x <= -15)].index.tolist())

        def fmt_remaining(v):
            n = _tour_num(v)
            if n is None or n <= -15:
                return ""
            return str(int(round(n)))

        out[remain_col] = out[remain_col].apply(fmt_remaining)

    # V86.2: cột "Thời gian" có thể chứa số âm bất thường rất lớn
    # (ví dụ -66605391). Nếu độ âm vượt 180 phút thì không hiển thị.
    # Chỉ thay đổi giao diện, không ghi ngược về TourVera.xlsm.
    time_col = _find_tour_col(out, "Thời gian")
    if time_col is not None and time_col != remain_col:
        def fmt_tour_time(v):
            n = _tour_num(v)
            if n is not None:
                if n < -180:
                    return ""
                # Giữ kiểu hiển thị số nguyên giống các cột số khác.
                return str(int(round(n)))
            if pd.isna(v):
                return ""
            s = str(v).strip()
            return "" if s.casefold() in {"nan", "none", "nat", "<na>"} else s

        out[time_col] = out[time_col].apply(fmt_tour_time)

    status_col = _find_tour_col(out, "Trạng thái")
    if status_col is not None:
        def fmt_status(v):
            token = _tour_norm_token(v)
            if token == "dang cho":
                return "Đang chờ"
            if token == "dang thuc hien":
                return "Đang thực hiện"
            if pd.isna(v):
                return ""
            s = str(v).strip()
            return "" if s.casefold() in {"none", "nan", "nat", "<na>"} else s
        out[status_col] = out[status_col].apply(fmt_status)

    def clean_and_integer_tour_value(v):
        # Ẩn hoàn toàn giá trị thiếu thật sự.
        try:
            if pd.isna(v):
                return ""
        except Exception:
            pass

        if isinstance(v, str):
            s = v.strip()
            if s.casefold() in {"none", "nan", "nat", "<na>"}:
                return ""
            # Nếu chuỗi chỉ là một số thì hiển thị thành số nguyên.
            if re.fullmatch(r"[-+]?\d+(?:\.\d+)?", s):
                try:
                    return str(int(round(float(s))))
                except Exception:
                    return s
            return s

        # Giá trị số từ openpyxl/pandas -> số nguyên hiển thị.
        if isinstance(v, bool):
            return v
        try:
            if isinstance(v, numbers.Number):
                return str(int(round(float(v))))
        except Exception:
            pass
        return v

    for c in out.columns:
        out[c] = out[c].apply(clean_and_integer_tour_value)

    out.attrs.update(df.attrs)
    out.attrs["_tour_expired_indices"] = expired_indices
    return out

def calculate_bang_tour_stats(df):
    """Tính bảng thống kê số lượng cho Bảng tour từ dữ liệu gốc vừa tải."""
    if df.empty:
        return pd.DataFrame(columns=["Chỉ số", "Số lượng"])

    status_col = _find_tour_col(df, "Trạng thái")
    remain_col = _find_tour_col(df, "Thời gian còn lại")
    work_col = _find_tour_col(df, "Đi làm")
    shift_col = _find_tour_col(df, "Vào ca")
    break_col = _find_tour_col(df, "Break")

    # Nếu tên cột workbook hơi khác, thử các biến thể thường gặp.
    if break_col is None:
        break_col = _find_tour_col(df, "Breaktime")
    if shift_col is None:
        shift_col = _find_tour_col(df, "Ca")

    blank = pd.Series([""] * len(df), index=df.index, dtype=object)
    status_s = df[status_col].apply(_tour_norm_token) if status_col else blank.copy()
    work_s = df[work_col].apply(_tour_norm_token) if work_col else blank.copy()
    shift_s = df[shift_col].apply(_tour_norm_token) if shift_col else blank.copy()
    break_s = df[break_col].apply(_tour_norm_token) if break_col else blank.copy()
    remain_num = df[remain_col].apply(_tour_num) if remain_col else pd.Series([None] * len(df), index=df.index)
    remain_num = pd.to_numeric(remain_num, errors='coerce')
    status_num = pd.to_numeric(df[status_col], errors='coerce') if status_col else pd.Series([float('nan')] * len(df), index=df.index)

    dang_thuc_hien_mask = status_s.eq("dang thuc hien")
    dang_cho_mask = status_s.eq("dang cho")

    # "Sắp xong": hỗ trợ đúng cả hai trường hợp dữ liệu:
    # - Nếu cột Trạng thái có giá trị số: đếm giá trị <= 30 theo yêu cầu.
    # - Với cấu trúc hiện tại Trạng thái là chữ DANG THUC HIEN: dùng Thời gian còn lại <= 30.
    #   Loại <= -15 vì các giá trị này được làm trống khỏi bảng hiển thị.
    sap_xong_mask = (
        (status_num.notna() & (status_num <= 30))
        | (dang_thuc_hien_mask & remain_num.notna() & (remain_num <= 30) & (remain_num > -15))
    )

    active_shift_mask = shift_s.isin(["ca 1", "ca 2"])
    di_lam_mask = work_s.eq("di lam")
    nghi_phep_mask = work_s.eq("nghi phep")
    idle_time_mask = remain_num.isna() | remain_num.eq(0)
    dang_ranh_mask = idle_time_mask & active_shift_mask & di_lam_mask

    ca1_mask = shift_s.eq("ca 1")
    ca2_mask = shift_s.eq("ca 2")
    break_mask = break_s.eq("break")

    dang_thuc_hien = int(dang_thuc_hien_mask.sum())
    dang_cho = int(dang_cho_mask.sum())
    sap_xong = int(sap_xong_mask.sum())
    dang_ranh = int(dang_ranh_mask.sum())
    co_the_len_tour = sap_xong + dang_ranh

    # V85.1: giao diện Thống kê Bảng tour chỉ hiển thị duy nhất
    # "Có thể lên tour". Vẫn giữ nguyên công thức = Sắp xong + Đang rảnh.
    rows = [
        ("Có thể lên tour", co_the_len_tour),
    ]
    return pd.DataFrame(rows, columns=["Chỉ số", "Số lượng"])


def style_bang_tour(df):
    """
    Tô nguyên dòng Bảng tour theo quy tắc vận hành Vera.
    - Nghỉ phép: nền trắng, chữ mờ.
    - Đi làm: nền trắng, chữ đen.
    - Thời gian >= 15: xanh lá.
    - 0 <= thời gian < 15: vàng.
    - -15 < thời gian < 0: đỏ.
    - Đang rảnh: xanh nhạt + chữ đậm.
    - Break: cam (ưu tiên cao nhất).
    - Header: nền rgb(161,148,140) / #A1948C, chữ đen đậm.
    """
    remain_col = _find_tour_col(df, "Thời gian còn lại")
    work_col = _find_tour_col(df, "Đi làm")
    shift_col = _find_tour_col(df, "Vào ca")
    break_col = _find_tour_col(df, "Break")
    if break_col is None:
        break_col = _find_tour_col(df, "Breaktime")
    if shift_col is None:
        shift_col = _find_tour_col(df, "Ca")

    expired_indices = set(df.attrs.get("_tour_expired_indices", set()))

    def row_style(row):
        work_norm = _tour_norm_token(row.get(work_col, "")) if work_col else ""
        shift_norm = _tour_norm_token(row.get(shift_col, "")) if shift_col else ""
        break_norm = _tour_norm_token(row.get(break_col, "")) if break_col else ""
        remain_num = _tour_num(row.get(remain_col, "")) if remain_col else None

        bg = "#FFFFFF"
        fg = "#000000"
        weight = "400"

        if work_norm == "nghi phep":
            bg, fg, weight = "#FFFFFF", "#A6A6A6", "400"
        elif work_norm == "di lam":
            bg, fg, weight = "#FFFFFF", "#000000", "400"

        # Màu theo thời gian, không ghi đè dòng Nghỉ phép.
        if remain_num is not None and work_norm != "nghi phep":
            if remain_num >= 15:
                bg, fg, weight = "#92D050", "#000000", "600"
            elif 0 <= remain_num < 15:
                bg, fg, weight = "#FFD966", "#000000", "600"
            elif -15 < remain_num < 0:
                bg, fg, weight = "#FF6666", "#000000", "600"

        # Đang rảnh: thời gian trống/0 + Ca 1/Ca 2 + Đi làm; loại trừ dòng <= -15 đã bị làm trống.
        is_idle = (
            row.name not in expired_indices
            and work_norm == "di lam"
            and shift_norm in {"ca 1", "ca 2"}
            and (remain_num is None or remain_num == 0)
        )
        if is_idle:
            bg, fg, weight = "#D9EAD3", "#000000", "700"

        # Break ưu tiên cuối cùng.
        if break_norm == "break":
            bg, fg, weight = "#F4B183", "#000000", "700"

        css = (
            f"background-color:{bg};"
            f"color:{fg};"
            f"font-weight:{weight};"
            "white-space:nowrap;"
        )
        return [css] * len(row)

    styler = df.style.apply(row_style, axis=1).format(na_rep="")
    styler = styler.set_table_styles([
        {
            "selector": "th",
            "props": [
                ("background-color", "#A1948C"),
                ("color", "#000000"),
                ("font-weight", "700"),
                ("text-align", "center"),
                ("white-space", "normal"),
                ("overflow-wrap", "anywhere"),
                ("word-break", "break-word"),
                ("line-height", "1.15"),
            ],
        },
        {"selector": "td", "props": [("white-space", "nowrap")]},
    ])

    status_col = _find_tour_col(df, "Trạng thái")
    if status_col is not None:
        styler = styler.set_properties(
            subset=[status_col],
            **{"white-space": "nowrap", "min-width": "135px", "width": "135px"}
        )
    return styler

def _vera_fragment_every(seconds):
    """Dùng Streamlit fragment nếu phiên bản hiện tại hỗ trợ; fallback không auto-rerun."""
    def decorator(func):
        frag = getattr(st, "fragment", None)
        if callable(frag):
            try:
                return frag(run_every=seconds)(func)
            except Exception:
                pass
        return func
    return decorator


