# V88 - DATA TABLE BUILDER TOÀN HỆ THỐNG
# ==========================================================
DATA_TABLE_UI_KEY = "global_data_table_v88"

def _data_table_default_config():
    def one():
        return {
            "header_bg": "#F1F3F5",
            "header_text": "#222222",
            "header_weight": "700",
            "sticky_header": True,
            "body_bg": "#FFFFFF",
            "body_text": "#222222",
            "zebra_enabled": True,
            "zebra_bg": "#FAFAFA",
            "row_hover_bg": "#EEF5FF",
            "grid_horizontal": True,
            "grid_vertical": False,
            "border_color": "#E5E7EB",
            "border_width": 1,
            "cell_padding_x": 8,
            "cell_padding_y": 6,
            "text_align": "Trái",
            "number_align": "Phải",
            "status_align": "Giữa",
        }
    return {"desktop": one(), "mobile": one()}


def _normalize_data_table_config(raw=None):
    base = _data_table_default_config()
    raw = raw if isinstance(raw, dict) else {}
    for device in ["desktop", "mobile"]:
        incoming = raw.get(device, {}) if isinstance(raw.get(device, {}), dict) else {}
        out = base[device]
        for color_key in ["header_bg","header_text","body_bg","body_text","zebra_bg","row_hover_bg","border_color"]:
            out[color_key] = _valid_theme_hex(incoming.get(color_key), out[color_key])
        weight = str(incoming.get("header_weight", out["header_weight"]))
        out["header_weight"] = weight if weight in UI_THEME_WEIGHT_OPTIONS else out["header_weight"]
        for bool_key in ["sticky_header","zebra_enabled","grid_horizontal","grid_vertical"]:
            out[bool_key] = bool(incoming.get(bool_key, out[bool_key]))
        for num_key, lo, hi in [
            ("border_width",0,5),("cell_padding_x",0,30),("cell_padding_y",0,30)
        ]:
            try: out[num_key] = max(lo, min(hi, int(float(incoming.get(num_key, out[num_key])))))
            except Exception: pass
        for align_key in ["text_align","number_align","status_align"]:
            val = str(incoming.get(align_key, out[align_key]))
            out[align_key] = val if val in UI_THEME_ALIGN_OPTIONS else out[align_key]
    return base


@st.cache_data(ttl=300, show_spinner=False)
def load_data_table_ui_config():
    ws, err = _ensure_ui_theme_storage()
    if err or ws is None:
        return _data_table_default_config(), err
    try:
        vals = _gs_call_with_backoff(ws.get_all_values)
        for row in vals[1:]:
            if row and str(row[0]).strip() == DATA_TABLE_UI_KEY:
                try: raw = json.loads(row[1]) if len(row) > 1 and str(row[1]).strip() else {}
                except Exception: raw = {}
                return _normalize_data_table_config(raw), ""
        return _data_table_default_config(), ""
    except Exception as e:
        return _data_table_default_config(), f"Lỗi đọc Data Table UI: {e}"


def save_data_table_ui_config(config, username):
    ws, err = _ensure_ui_theme_storage()
    if err or ws is None:
        return False, err or "Không mở được sheet cấu hình."
    try:
        cfg = _normalize_data_table_config(config)
        vals = _gs_call_with_backoff(ws.get_all_values)
        row_idx = None
        for idx, row in enumerate(vals[1:], start=2):
            if row and str(row[0]).strip() == DATA_TABLE_UI_KEY:
                row_idx = idx; break
        now = datetime.now(VN_TZ).strftime("%d/%m/%Y %H:%M:%S")
        row = [DATA_TABLE_UI_KEY, json.dumps(cfg, ensure_ascii=False), now, str(username)]
        if row_idx: gspread_update_range(ws, f"A{row_idx}:D{row_idx}", [row])
        else: _gs_call_with_backoff(ws.append_row, row, value_input_option="USER_ENTERED")
        try: load_data_table_ui_config.clear()
        except Exception: pass
        return True, "Đã lưu cấu hình Data Table."
    except Exception as e:
        return False, f"Lỗi lưu Data Table UI: {e}"


def _data_table_css(config=None):
    cfg = _normalize_data_table_config(config)
    blocks = []
    for device, media in [("desktop",""),("mobile","@media (max-width:768px)")]:
        c = cfg[device]
        h_border = f"{c['border_width']}px solid {c['border_color']}" if c["grid_horizontal"] else "none"
        v_border = f"{c['border_width']}px solid {c['border_color']}" if c["grid_vertical"] else "none"
        sticky = "position:sticky!important;top:0!important;z-index:4!important;" if c["sticky_header"] else ""
        body = f"""
table th, [data-testid='stDataFrame'] [role='columnheader'], [data-testid='stDataEditor'] [role='columnheader'] {{
 background:{c['header_bg']}!important;color:{c['header_text']}!important;font-weight:{c['header_weight']}!important;
 padding:{c['cell_padding_y']}px {c['cell_padding_x']}px!important;
 border-bottom:{h_border}!important;border-right:{v_border}!important;{sticky}
}}
table td {{
 background:{c['body_bg']}!important;color:{c['body_text']}!important;
 padding:{c['cell_padding_y']}px {c['cell_padding_x']}px!important;
 border-bottom:{h_border}!important;border-right:{v_border}!important;
 text-align:{_ui_align_css(c['text_align'])}!important;
}}
"""
        if c["zebra_enabled"]:
            body += f"table tbody tr:nth-child(even) td{{background:{c['zebra_bg']}!important;}}\n"
        body += f"table tbody tr:hover td{{background:{c['row_hover_bg']}!important;}}\n"
        if media:
            blocks.append(media + "{\n" + body + "\n}")
        else:
            blocks.append(body)
    return "\n".join(blocks)


def render_data_table_builder():
    if st.session_state.get("current_role") != "admin":
        return
    current, err = load_data_table_ui_config()
    with st.expander("📊 Data Table · Web / Mobile song song", expanded=False):
        st.caption("Mọi thông số Data Table đều có cấu hình Web và Mobile riêng.")
        if err:
            st.warning(err)
        edited = json.loads(json.dumps(current))

        def editor(device, prefix):
            c = dict(edited[device])
            c["header_bg"] = st.text_input("Header nền", c["header_bg"], key=f"{prefix}_hbg")
            c["header_text"] = st.text_input("Header chữ", c["header_text"], key=f"{prefix}_ht")
            c["header_weight"] = st.selectbox(
                "Header Weight", UI_THEME_WEIGHT_OPTIONS,
                index=UI_THEME_WEIGHT_OPTIONS.index(c["header_weight"]), key=f"{prefix}_hw"
            )
            c["sticky_header"] = st.toggle("Sticky Header", value=c["sticky_header"], key=f"{prefix}_sticky")
            c["body_bg"] = st.text_input("Body nền", c["body_bg"], key=f"{prefix}_bbg")
            c["body_text"] = st.text_input("Body chữ", c["body_text"], key=f"{prefix}_bt")
            c["zebra_enabled"] = st.toggle("Zebra Stripes", value=c["zebra_enabled"], key=f"{prefix}_zebra")
            c["zebra_bg"] = st.text_input("Zebra màu", c["zebra_bg"], key=f"{prefix}_zbg")
            c["row_hover_bg"] = st.text_input("Row Hover màu", c["row_hover_bg"], key=f"{prefix}_rh")
            c["grid_horizontal"] = st.toggle("Grid ngang", value=c["grid_horizontal"], key=f"{prefix}_gh")
            c["grid_vertical"] = st.toggle("Grid dọc", value=c["grid_vertical"], key=f"{prefix}_gv")
            c["border_color"] = st.text_input("Màu đường kẻ", c["border_color"], key=f"{prefix}_bc")
            c["border_width"] = st.number_input("Độ dày lưới", 0, 5, int(c["border_width"]), key=f"{prefix}_bw")
            c["cell_padding_x"] = st.number_input("Cell Padding X", 0, 30, int(c["cell_padding_x"]), key=f"{prefix}_px")
            c["cell_padding_y"] = st.number_input("Cell Padding Y", 0, 30, int(c["cell_padding_y"]), key=f"{prefix}_py")
            c["text_align"] = st.selectbox(
                "Text Align", UI_THEME_ALIGN_OPTIONS,
                index=UI_THEME_ALIGN_OPTIONS.index(c["text_align"]), key=f"{prefix}_ta"
            )
            c["number_align"] = st.selectbox(
                "Number/Money Align", UI_THEME_ALIGN_OPTIONS,
                index=UI_THEME_ALIGN_OPTIONS.index(c["number_align"]), key=f"{prefix}_na"
            )
            c["status_align"] = st.selectbox(
                "Status/Icon Align", UI_THEME_ALIGN_OPTIONS,
                index=UI_THEME_ALIGN_OPTIONS.index(c["status_align"]), key=f"{prefix}_sa"
            )
            edited[device] = c

        web_col, mobile_col = st.columns(2)
        with web_col:
            st.markdown("#### 🌐 Web / Desktop")
            editor("desktop", "dt_web_v921")
        with mobile_col:
            st.markdown("#### 📱 Mobile")
            editor("mobile", "dt_mobile_v921")

        x1, x2 = st.columns(2)
        with x1:
            if st.button("💾 Lưu Data Table", use_container_width=True, key="save_dt_v921"):
                ok, msg = save_data_table_ui_config(edited, st.session_state.current_user)
                (st.success if ok else st.error)(msg)
                if ok:
                    rerun_current_view()
        with x2:
            if st.button("♻️ Khôi phục Data Table", use_container_width=True, key="reset_dt_v921"):
                ok, msg = save_data_table_ui_config(_data_table_default_config(), st.session_state.current_user)
                (st.success if ok else st.error)(msg)
                if ok:
                    rerun_current_view()



