def _normalize_compact_admin_preset(raw=None):
    base = _compact_admin_preset_default()
    raw = raw if isinstance(raw, dict) else {}
    color_keys = {
        "header_bg", "header_text", "body_bg", "body_text", "zebra_bg",
        "row_hover_bg", "border_color", "expander_header_bg"
    }
    numeric_limits = {
        "font_size": (8, 24),
        "header_font_size": (8, 24),
        "border_width": (0, 5),
        "cell_padding_x": (0, 20),
        "cell_padding_y": (0, 20),
        "radius": (0, 24),
        "button_height": (28, 80),
        "button_font": (8, 24),
        "input_height": (28, 80),
        "expander_font": (8, 28),
        "metric_font": (10, 36),
    }
    for device in ["desktop", "mobile"]:
        incoming = raw.get(device, {}) if isinstance(raw.get(device, {}), dict) else {}
        for k in color_keys:
            base[device][k] = _valid_theme_hex(incoming.get(k), base[device][k])
        w = str(incoming.get("header_weight", base[device]["header_weight"]))
        base[device]["header_weight"] = w if w in UI_THEME_WEIGHT_OPTIONS else base[device]["header_weight"]
        for k, (lo, hi) in numeric_limits.items():
            try:
                base[device][k] = max(lo, min(hi, int(float(incoming.get(k, base[device][k])))))
            except Exception:
                pass
    return base


@st.cache_data(ttl=300, show_spinner=False)
def load_compact_admin_preset():
    ws, err = _ensure_ui_theme_storage()
    if err or ws is None:
        return _compact_admin_preset_default(), err
    try:
        vals = _gs_call_with_backoff(ws.get_all_values)
        for row in vals[1:]:
            if row and str(row[0]).strip() == COMPACT_ADMIN_PRESET_KEY:
                try:
                    raw = json.loads(row[1]) if len(row) > 1 and str(row[1]).strip() else {}
                except Exception:
                    raw = {}
                return _normalize_compact_admin_preset(raw), ""
        return _compact_admin_preset_default(), ""
    except Exception as e:
        return _compact_admin_preset_default(), f"Lỗi đọc preset Bảng quản trị gọn: {e}"


def save_compact_admin_preset(config, username):
    ws, err = _ensure_ui_theme_storage()
    if err or ws is None:
        return False, err or "Không mở được sheet cấu hình giao diện."
    try:
        cfg = _normalize_compact_admin_preset(config)
        vals = _gs_call_with_backoff(ws.get_all_values)
        row_idx = None
        for idx, row in enumerate(vals[1:], start=2):
            if row and str(row[0]).strip() == COMPACT_ADMIN_PRESET_KEY:
                row_idx = idx
                break
        now = datetime.now(VN_TZ).strftime("%d/%m/%Y %H:%M:%S")
        row = [COMPACT_ADMIN_PRESET_KEY, json.dumps(cfg, ensure_ascii=False), now, str(username)]
        if row_idx:
            gspread_update_range(ws, f"A{row_idx}:D{row_idx}", [row])
        else:
            _gs_call_with_backoff(ws.append_row, row, value_input_option="USER_ENTERED")
        try:
            load_compact_admin_preset.clear()
        except Exception:
            pass
        return True, "Đã lưu preset Bảng quản trị gọn."
    except Exception as e:
        return False, f"Lỗi lưu preset: {e}"


def _compact_preset_to_global_configs(preset):
    """Chuyển preset thành cấu hình Theme + Data Table hiện hành."""
    p = _normalize_compact_admin_preset(preset)
    theme, _ = load_ui_theme_config()
    theme = _normalized_theme_config(theme)
    dt, _ = load_data_table_ui_config()
    dt = _normalize_data_table_config(dt)

    for device in ["desktop", "mobile"]:
        x = p[device]

        # Bảng chung
        theme["table"][device]["font_size"] = x["font_size"]
        theme["table"][device]["padding_x"] = x["cell_padding_x"]
        theme["table"][device]["padding_y"] = x["cell_padding_y"]
        theme["table"][device]["radius"] = x["radius"]
        theme["table"][device]["border_width"] = x["border_width"]
        theme["table"][device]["border_color"] = x["border_color"]
        theme["table"][device]["bg_color"] = x["header_bg"]
        theme["table"][device]["text_color"] = x["body_text"]

        # Nút
        theme["button"][device]["control_height"] = x["button_height"]
        theme["button"][device]["font_size"] = x["button_font"]
        theme["button"][device]["radius"] = min(x["radius"], 10)
        theme["button"][device]["border_width"] = 1
        theme["button"][device]["border_color"] = "#D7DBE0"
        theme["button"][device]["bg_color"] = "#FFFFFF"
        theme["button"][device]["text_color"] = "#2F3337"
        theme["button"][device]["hover_bg"] = "#F3F4F6"
        theme["button"][device]["hover_text"] = "#2F3337"
        theme["button"][device]["box_shadow"] = "Không"

        # Input + Select
        for key in ["input", "select"]:
            theme[key][device]["control_height"] = x["input_height"]
            theme[key][device]["font_size"] = x["button_font"]
            theme[key][device]["radius"] = min(x["radius"], 10)
            theme[key][device]["border_width"] = 1
            theme[key][device]["border_color"] = "#D7DBE0"
            theme[key][device]["bg_color"] = "#FFFFFF"
            theme[key][device]["text_color"] = "#2F3337"
            theme[key][device]["box_shadow"] = "Không"

        # Expander
        theme["expander"][device]["font_size"] = x["expander_font"]
        theme["expander"][device]["font_weight"] = "700"
        theme["expander"][device]["bg_color"] = x["expander_header_bg"]
        theme["expander"][device]["text_color"] = "#2F3337"
        theme["expander"][device]["radius"] = x["radius"]
        theme["expander"][device]["border_width"] = 1
        theme["expander"][device]["border_color"] = x["border_color"]
        theme["expander"][device]["box_shadow"] = "Không"

        # Metric / Card
        theme["metric"][device]["font_size"] = x["metric_font"]
        theme["metric"][device]["bg_color"] = "#FFFFFF"
        theme["metric"][device]["border_width"] = 1
        theme["metric"][device]["border_color"] = "#E1E4E8"
        theme["metric"][device]["radius"] = min(x["radius"], 10)
        theme["metric"][device]["box_shadow"] = "Không"

        theme["card_box"][device]["bg_color"] = "#FFFFFF"
        theme["card_box"][device]["border_width"] = 1
        theme["card_box"][device]["border_color"] = x["border_color"]
        theme["card_box"][device]["radius"] = x["radius"]
        theme["card_box"][device]["box_shadow"] = "Không"

        # Data Table chuyên biệt
        dt[device]["header_bg"] = x["header_bg"]
        dt[device]["header_text"] = x["header_text"]
        dt[device]["header_weight"] = x["header_weight"]
        dt[device]["body_bg"] = x["body_bg"]
        dt[device]["body_text"] = x["body_text"]
        dt[device]["zebra_enabled"] = True
        dt[device]["zebra_bg"] = x["zebra_bg"]
        dt[device]["row_hover_bg"] = x["row_hover_bg"]
        dt[device]["border_color"] = x["border_color"]
        dt[device]["border_width"] = x["border_width"]
        dt[device]["cell_padding_x"] = x["cell_padding_x"]
        dt[device]["cell_padding_y"] = x["cell_padding_y"]
        dt[device]["grid_horizontal"] = True
        dt[device]["grid_vertical"] = True

    return _normalized_theme_config(theme), _normalize_data_table_config(dt)


