            c["input_height"] = st.number_input("Input cao", 28, 80, int(c["input_height"]), key=f"{prefix}_ih")
            c["expander_header_bg"] = st.text_input("Expander nền", c["expander_header_bg"], key=f"{prefix}_ebg")
