SAVE_BUTTON_UI_KEY = "save_button_ui_v89"
SAVE_BUTTON_STYLE_OPTIONS = ["Thường", "Italic"]

def _save_button_default_labels():
    return {
        "generic":"💾 Lưu",
        "confirm_leave":"💾 Xác Nhận Ghi Lịch Nghỉ",
        "save_all":"💾 Lưu tất cả thay đổi",
        "save_default":"💾 Lưu làm mặc định",
        "overwrite":"💾 Ghi đè cập nhật bản lương này",
    }


def _save_button_default_config():
    def one():
        return {
            "font_family":"Roboto", "font_size":14, "font_weight":"700", "font_style":"Thường",
            "text_color":"#173A63", "bg_color":"#DCEBFF", "border_color":"#8CB4E8",
            "border_width":1, "radius":7, "width_px":0, "height_px":40, "shadow":"Nhẹ",
            "hover_bg":"#C7DEFF", "hover_text":"#102E50",
        }
    labels = _save_button_default_labels()
    return {
        "desktop": one(),
        "mobile": one(),
        "labels": {"desktop": dict(labels), "mobile": dict(labels)},
    }


def _normalize_save_button_config(raw=None):
    base = _save_button_default_config()
    raw = raw if isinstance(raw, dict) else {}
    for device in ["desktop","mobile"]:
        incoming = raw.get(device,{}) if isinstance(raw.get(device,{}),dict) else {}
        out = base[device]
        font = str(incoming.get("font_family",out["font_family"]))
        out["font_family"] = font if font in UI_THEME_FONT_OPTIONS else out["font_family"]
        weight = str(incoming.get("font_weight",out["font_weight"]))
        out["font_weight"] = weight if weight in UI_THEME_WEIGHT_OPTIONS else out["font_weight"]
        style = str(incoming.get("font_style",out["font_style"]))
        out["font_style"] = style if style in SAVE_BUTTON_STYLE_OPTIONS else out["font_style"]
        shadow = str(incoming.get("shadow",out["shadow"]))
        out["shadow"] = shadow if shadow in UI_THEME_SHADOW_OPTIONS else out["shadow"]
        for ck in ["text_color","bg_color","border_color","hover_bg","hover_text"]:
            out[ck] = _valid_theme_hex(incoming.get(ck),out[ck])
        for k,(lo,hi) in {
            "font_size":(8,30),"border_width":(0,8),"radius":(0,30),
            "width_px":(0,1200),"height_px":(28,120)
        }.items():
            try:
                out[k] = max(lo,min(hi,int(float(incoming.get(k,out[k])))))
            except Exception:
                pass

    labels_raw = raw.get("labels", {})
    # V89 cũ: labels là dict phẳng -> nhân sang cả Web/Mobile.
    if isinstance(labels_raw, dict) and any(k in labels_raw for k in _save_button_default_labels()):
        labels_raw = {"desktop": labels_raw, "mobile": labels_raw}
    if not isinstance(labels_raw, dict):
        labels_raw = {}
    for device in ("desktop","mobile"):
        incoming_labels = labels_raw.get(device,{}) if isinstance(labels_raw.get(device,{}),dict) else {}
        for key, default_val in _save_button_default_labels().items():
            val = str(incoming_labels.get(key, default_val)).strip()
            base["labels"][device][key] = val or default_val
    return base


@st.cache_data(ttl=300, show_spinner=False)
def load_save_button_ui_config():
    ws,err=_ensure_ui_theme_storage()
    if err or ws is None: return _save_button_default_config(),err
    try:
        vals=_gs_call_with_backoff(ws.get_all_values)
        for row in vals[1:]:
            if row and str(row[0]).strip()==SAVE_BUTTON_UI_KEY:
                try: raw=json.loads(row[1]) if len(row)>1 and str(row[1]).strip() else {}
                except Exception: raw={}
                return _normalize_save_button_config(raw),""
        return _save_button_default_config(),""
    except Exception as e: return _save_button_default_config(),f"Lỗi đọc cấu hình nút Lưu: {e}"

def save_save_button_ui_config(config,username):
    ws,err=_ensure_ui_theme_storage()
    if err or ws is None: return False,err or "Không mở được sheet cấu hình giao diện."
    try:
        cfg=_normalize_save_button_config(config); vals=_gs_call_with_backoff(ws.get_all_values); row_idx=None
        for idx,row in enumerate(vals[1:],start=2):
            if row and str(row[0]).strip()==SAVE_BUTTON_UI_KEY: row_idx=idx; break
        now=datetime.now(VN_TZ).strftime("%d/%m/%Y %H:%M:%S"); row=[SAVE_BUTTON_UI_KEY,json.dumps(cfg,ensure_ascii=False),now,str(username)]
        if row_idx: gspread_update_range(ws,f"A{row_idx}:D{row_idx}",[row])
        else: _gs_call_with_backoff(ws.append_row,row,value_input_option="USER_ENTERED")
        try: load_save_button_ui_config.clear()
        except Exception: pass
        return True,"Đã lưu giao diện nút Lưu / Save."
    except Exception as e: return False,f"Lỗi lưu giao diện nút Lưu: {e}"

