                f"<div style=\"font-family:'{pm['font_family']}';font-size:{pm['font_size']}px;"
                f"color:{pm['text_color']};background:{pm['bg_color']};padding:{pm['padding_y']}px {pm['padding_x']}px;"
                f"border:1px solid #ddd;border-radius:{pm['radius']}px;display:inline-block;\">"
