        c1, c2 = st.columns(2)
        with c1:
            if st.button("💾 Lưu toàn bộ giao diện Web + Mobile", use_container_width=True, key="save_global_theme_v921"):
                ok, msg = save_ui_theme_config(preview_cfg, st.session_state.current_user)
