NOTICE_DISMISS_WORKSHEET = "ThongBaoDaDong"
NOTICE_DISMISS_HEADERS = [
    "Tài khoản", "Mã thông báo", "Notice key", "Nội dung",
    "Ngày đóng", "Giờ đóng"
]


def _get_notice_dismiss_worksheet():
    client = get_gspread_client()
    if not client:
        return None
    # Dùng file cấu hình/lịch nghỉ đang có để không cần tạo thêm spreadsheet mới.
    ss = client.open_by_key(SHEET_DU_PHONG_ID)
    ws = _get_or_create_worksheet(
        ss,
        NOTICE_DISMISS_WORKSHEET,
        rows=3000,
        cols=len(NOTICE_DISMISS_HEADERS),
    )
    try:
        header = _gs_call_with_backoff(ws.row_values, 1)
        if header[:len(NOTICE_DISMISS_HEADERS)] != NOTICE_DISMISS_HEADERS:
            gspread_update_range(
                ws,
                f"A1:F1",
                [NOTICE_DISMISS_HEADERS],
            )
    except Exception:
        pass
    return ws


@st.cache_data(ttl=600, show_spinner=False)
def load_dismissed_notice_ids(username):
    user_key = normalize_login_name(username)
    if not user_key:
        return set()
    try:
        ws = _get_notice_dismiss_worksheet()
        if ws is None:
            return set()
        vals = _gs_call_with_backoff(ws.get_all_values)
        out = set()
        for row in vals[1:]:
            if len(row) < 2:
                continue
            if normalize_login_name(row[0]) == user_key:
                nid = str(row[1]).strip()
                if nid:
                    out.add(nid)
        return out
    except Exception:
        return set()


def _notice_instance_id(username, notice_key, message, page_name):
    """
    Mã close theo đúng tài khoản + thông báo.
    message được đưa vào hash để thông báo tổng hợp có nội dung mới có thể hiện lại.
    """
    raw = "|".join([
        normalize_login_name(username),
        str(notice_key or "").strip(),
        str(page_name or "").strip(),
        str(message or "").strip(),
    ])
    return hashlib.sha1(raw.encode("utf-8")).hexdigest()[:24]


def dismiss_account_notice(username, notice_id, notice_key, message):
    try:
        username = str(username or "").strip()
        notice_id = str(notice_id or "").strip()
        if not username or not notice_id:
            return False, "Không xác định được thông báo cần đóng."

        # Tránh ghi trùng nếu user click nhiều lần.
        existing = load_dismissed_notice_ids(username)
        if notice_id in existing:
            return True, "Đã đóng thông báo."

        ws = _get_notice_dismiss_worksheet()
        if ws is None:
            return False, "Không kết nối được nơi lưu trạng thái thông báo."

        now = datetime.now(VN_TZ)
        row = [
            username,
            notice_id,
            str(notice_key or "").strip(),
            str(message or "").strip(),
            now.strftime("%d/%m/%Y"),
            now.strftime("%H:%M:%S"),
        ]
        _gs_call_with_backoff(
            ws.append_row,
            row,
            value_input_option="USER_ENTERED",
        )
        try:
            load_dismissed_notice_ids.clear()
        except Exception:
            pass
        return True, "Đã đóng thông báo."
    except Exception as e:
        return False, f"Không đóng được thông báo: {e}"


def _reception_leave_notices_for_current_user(limit=5):
    """
    Các lịch nghỉ do tài khoản Lễ tân đăng ký cho chính Nhân viên/Leader đang đăng nhập.
    Nguồn là Sheet lịch nghỉ hiện có nên không cần thêm sheet thông báo riêng.
    Chỉ lấy bản ghi cập nhật trong 30 ngày gần nhất và ngày nghỉ từ hôm nay trở đi.
    """
    role = str(st.session_state.get("current_role", "") or "").strip().lower()
    username = str(st.session_state.get("current_user", "") or "").strip()
    if role not in {"nhanvien", "leader"} or not username:
        return []

    try:
        d = load_backup_sheet_data()
        if not isinstance(d, pd.DataFrame) or d.empty:
            return []
        required = {"Tên nhân viên", "Ngày", "Lý do nghỉ", "Người cập nhật"}
        if not required.issubset(set(d.columns)):
            return []

        creds = load_credentials_recent()
        role_map = {}
        if isinstance(creds, pd.DataFrame) and not creds.empty:
            for _, r in creds.iterrows():
                role_map[normalize_login_name(r.get("Tên nhân viên", ""))] = (
                    str(r.get("Phân quyền", "") or "").strip().lower()
                )

        out = d[
            d["Tên nhân viên"].astype(str).apply(normalize_login_name)
            .eq(normalize_login_name(username))
        ].copy()
        if out.empty:
            return []

        out["__creator_role"] = out["Người cập nhật"].astype(str).apply(
            lambda x: role_map.get(normalize_login_name(x), "")
        )
        out = out[out["__creator_role"].eq("letan")].copy()
        if out.empty:
            return []

        out["__leave_date"] = out["Ngày"].apply(_parse_vn_date)
        today = get_vn_today()
        out = out[
            out["__leave_date"].apply(
                lambda x: isinstance(x, date) and x >= today
            )
        ].copy()
        if out.empty:
            return []

        if "Ngày cập nhật" in out.columns:
            out["__updated_date"] = out["Ngày cập nhật"].apply(_parse_vn_date)
            cutoff = today - timedelta(days=30)
            out = out[
                out["__updated_date"].apply(
                    lambda x: isinstance(x, date) and x >= cutoff
                )
            ].copy()

        # mới nhất trước
        if "Giờ cập nhật" in out.columns:
            out["__sort"] = (
                out.get("Ngày cập nhật", "").astype(str)
                + " "
                + out["Giờ cập nhật"].astype(str)
            )
            out = out.sort_values("__sort", ascending=False, kind="stable")
        else:
            out = out.iloc[::-1]

        notices = []
        for _, r in out.head(max(1, int(limit))).iterrows():
            d0 = r.get("__leave_date")
            day_text = d0.strftime("%d/%m/%Y") if isinstance(d0, date) else str(r.get("Ngày", ""))
            reason = clean_leave_reason_display(r.get("Lý do nghỉ", ""))
            creator = str(r.get("Người cập nhật", "") or "").strip()
            key_raw = "|".join([
                normalize_login_name(username),
                str(day_text),
                normalize_leave_reason(reason),
                normalize_login_name(creator),
            ])
            key = hashlib.sha1(key_raw.encode("utf-8")).hexdigest()[:20]
            notices.append({
                "message": (
                    f"📅 Lễ Tân đã đăng ký lịch nghỉ cho bạn: "
                    f"{day_text} · {reason}"
                    + (f" · Lễ tân: {creator}" if creator else "")
                    + "."
                ),
                "notice_key": f"reception_leave_registered:{key}",
            })
        return notices
    except Exception:
        return []


# ==========================================================
# V91.8 - THÔNG BÁO CLICK ĐỂ MỞ ĐÚNG KHU VỰC, KHÔNG RELOAD TRÌNH DUYỆT
# ==========================================================
def render_clickable_app_notice(message, page_name, notice_key="", kind="warning"):
    """
    V91.8:
    - Dùng st.button để điều hướng NỘI BỘ, không dùng <a href> reload trình duyệt.
    - Giữ nguyên session đăng nhập hiện tại.
    - Nút ✕ đóng riêng cho tài khoản.
    """
    username = str(st.session_state.get("current_user", "")).strip()
    notice_id = _notice_instance_id(username, notice_key, message, page_name)

    if notice_id in load_dismissed_notice_ids(username):
        return False

    safe_kind = str(kind or "warning").strip().lower()
    if safe_kind not in {"warning", "info", "success", "error"}:
        safe_kind = "warning"

    _notice_col, _close_col = st.columns([18, 1], gap="small")

    with _notice_col:
        # Marker chỉ dùng để style đúng nút MỞ thông báo, không ảnh hưởng nút Close.
        st.markdown(
            f"<span class='vera-native-notice-marker vera-native-notice-{safe_kind}' "
            f"style='display:none!important'></span>",
            unsafe_allow_html=True,
        )

        _open_clicked = st.button(
            f"{message}  ›",
            key=f"open_notice_{notice_id}",
            help="Mở thông báo",
            use_container_width=True,
        )

        if _open_clicked:
            if page_name in allowed_pages:
                # Điều hướng trong cùng Streamlit session -> KHÔNG login lại.
                st.session_state.app_page = page_name
                _slug = str(PAGE_SLUGS.get(page_name, "") or "").strip()
                if _slug:
                    st.query_params["page"] = _slug
                if notice_key:
                    st.query_params["notice"] = str(notice_key)
                else:
                    try:
                        st.query_params.pop("notice", None)
                    except Exception:
                        pass
                st.session_state["_vera_collapse_sidebar_once"] = True
                rerun_current_view()
            else:
                st.warning("Tài khoản này không có quyền mở nội dung của thông báo.")

    with _close_col:
        if st.button(
            "✕",
            key=f"close_notice_{notice_id}",
            help="Đóng và xóa thông báo này khỏi tài khoản của bạn",
            use_container_width=True,
        ):
            ok, msg = dismiss_account_notice(
                username,
                notice_id,
                notice_key,
                message,
            )
            if ok:
                rerun_current_view()
            else:
                st.error(msg)

    return True


