def _active_notice_key():
    return str(st.query_params.get("notice", "") or "").strip()


def _clear_notice_query():
    try:
        st.query_params.pop("notice", None)
    except Exception:
        pass


def render_notice_scroll_marker(marker_id):
    """Cuộn browser tới đúng marker sau khi trang đã render."""
    marker_id = re.sub(r"[^A-Za-z0-9_-]+", "-", str(marker_id or "").strip())
    if not marker_id:
        return
    st.markdown(f"<div id='{marker_id}'></div>", unsafe_allow_html=True)
    components.html(
        f"""
        <script>
        (function(){{
          try {{
            const D = window.parent.document;
            setTimeout(function(){{
              const el = D.getElementById({json.dumps(marker_id)});
              if (el) el.scrollIntoView({{behavior:'smooth', block:'start'}});
            }}, 180);
          }} catch(e) {{}}
        }})();
        </script>
        """,
        height=0,
        width=0,
    )


# V90: thông báo nội bộ tới Admin + Quản lý + Lễ tân + Leader.
_ll_notice_role = str(st.session_state.get("current_role", "")).strip().lower()
if _ll_notice_role in {"admin", "quanly", "letan", "leader"}:
    try:
        _pending_notice_df = load_long_leave_requests()
        _pending_notice_df = (
            _pending_notice_df[
                _pending_notice_df["Trạng thái"].astype(str).str.strip()
                .eq(LONG_LEAVE_PENDING)
            ].copy()
            if isinstance(_pending_notice_df, pd.DataFrame) and not _pending_notice_df.empty
            else pd.DataFrame()
        )
        _pending_ll_count = len(_pending_notice_df)
        _pending_latest_id = ""
        if _pending_ll_count > 0:
            if "__row" in _pending_notice_df.columns:
                _pending_notice_df = _pending_notice_df.sort_values("__row", ascending=False)
            _pending_latest_id = str(_pending_notice_df.iloc[0].get("ID", "")).strip()

        if _pending_ll_count > 0 and selected_page != "🏖️ Lịch nghỉ dài hạn":
            if _ll_notice_role == "admin":
                render_clickable_app_notice(
                    f"🔔 Có {_pending_ll_count} đơn xin nghỉ dài hạn đang chờ duyệt. Bấm để mở ngay.",
                    "🏖️ Lịch nghỉ dài hạn",
                    f"long_leave_pending:{_pending_latest_id}",
                    kind="warning",
                )
            else:
                render_clickable_app_notice(
                    f"🔔 Có {_pending_ll_count} đơn xin nghỉ dài hạn đang chờ Admin duyệt. Bấm để xem ngay.",
                    "🏖️ Lịch nghỉ dài hạn",
                    f"long_leave_pending_view:{_pending_latest_id}",
                    kind="warning",
                )
    except Exception:
        pass

# V90.5: Quản lý / Lễ tân / Leader cũng nhận thông báo đơn KHÔNG DUYỆT,
# kèm lý do và click mở đúng nội dung.
if _ll_notice_role in {"quanly", "letan", "leader"}:
    try:
        _ll_rejected_notice_df = _long_leave_rejected_for_notifications(limit=3)
        if (
            isinstance(_ll_rejected_notice_df, pd.DataFrame)
            and not _ll_rejected_notice_df.empty
            and selected_page != "🏖️ Lịch nghỉ dài hạn"
        ):
            for _, _rej in _ll_rejected_notice_df.iterrows():
                _rej_id = str(_rej.get("ID", "")).strip()
                _rej_emp = str(_rej.get("Tên nhân viên", "")).strip()
                _rej_reason = str(_rej.get("Lý do không duyệt", "")).strip()
                render_clickable_app_notice(
                    f"❌ Đơn nghỉ dài hạn {_rej_id} của {_rej_emp} KHÔNG ĐƯỢC DUYỆT"
                    + (f" · Lý do: {_rej_reason}" if _rej_reason else "")
                    + ". Bấm để xem chi tiết.",
                    "🏖️ Lịch nghỉ dài hạn",
                    f"long_leave_rejected_view:{_rej_id}",
                    kind="error",
                )
    except Exception:
        pass


# V92.6.3: Nhân viên/Leader nhận thông báo khi Lễ tân vừa đăng ký lịch nghỉ cho mình.
if _ll_notice_role in {"nhanvien", "leader"}:
    try:
        for _rec_notice in _reception_leave_notices_for_current_user(limit=5):
            render_clickable_app_notice(
                _rec_notice["message"],
                "📅 Đăng ký nghỉ phép",
                _rec_notice["notice_key"],
                kind="info",
            )
    except Exception:
        pass


# V92.6.25: Admin nhận thông báo chi tiết khi Lễ tân/Quản lý sửa hoặc xóa lịch nghỉ.
if _ll_notice_role == "admin":
    try:
        for _audit_notice in load_admin_leave_audit_notices(limit=8):
            _audit_id = str(_audit_notice.get("ID", "") or "").strip()
            if not _audit_id:
                continue
            render_clickable_app_notice(
                _admin_leave_audit_notice_message(_audit_notice),
                "✏️ Quản lý lịch nghỉ",
                f"leave_schedule_audit:{_audit_id}",
                kind="warning",
            )
    except Exception:
        pass


# V90.3: người làm đơn nhận thông báo kết quả xét duyệt.
if _ll_notice_role in EMPLOYEE_LIKE_ROLES:
    try:
        _ll_decision_df = load_long_leave_requests()
        _ll_current_user_key = normalize_login_name(
            st.session_state.get("current_user", "")
        )
        if isinstance(_ll_decision_df, pd.DataFrame) and not _ll_decision_df.empty:
            _ll_my_decisions = _ll_decision_df[
                _ll_decision_df["Tên nhân viên"].astype(str)
                .apply(normalize_login_name).eq(_ll_current_user_key)
                & _ll_decision_df["Trạng thái"].astype(str).str.strip()
                .isin([LONG_LEAVE_APPROVED, LONG_LEAVE_REJECTED])
            ].copy()

            if not _ll_my_decisions.empty and selected_page != "🏖️ Lịch nghỉ dài hạn":
                # Hiển thị tối đa 3 quyết định gần nhất theo dòng sheet / thời điểm cập nhật.
                if "__row" in _ll_my_decisions.columns:
                    _ll_my_decisions = _ll_my_decisions.sort_values(
                        "__row", ascending=False
                    )

                for _, _dec in _ll_my_decisions.head(3).iterrows():
                    _dec_id = str(_dec.get("ID", "")).strip()
                    _dec_status = str(_dec.get("Trạng thái", "")).strip()
                    _dec_from = str(_dec.get("Từ ngày", "")).strip()
                    _dec_to = str(_dec.get("Đến ngày", "")).strip()

                    if _dec_status == LONG_LEAVE_APPROVED:
                        _dec_msg = (
                            f"✅ Đơn nghỉ dài hạn {_dec_id} đã được DUYỆT "
                            f"({_dec_from} → {_dec_to}). Bấm để xem chi tiết."
                        )
                        _dec_kind = "success"
                    else:
                        _dec_reason = str(
                            _dec.get("Lý do không duyệt", "")
                        ).strip()
                        _dec_msg = (
                            f"❌ Đơn nghỉ dài hạn {_dec_id} KHÔNG ĐƯỢC DUYỆT"
                            + (f" · Lý do: {_dec_reason}" if _dec_reason else "")
                            + ". Bấm để xem chi tiết."
                        )
                        _dec_kind = "error"

                    render_clickable_app_notice(
                        _dec_msg,
                        "🏖️ Lịch nghỉ dài hạn",
                        f"long_leave_decision:{_dec_id}",
                        kind=_dec_kind,
                    )
    except Exception:
        pass


# V90: nhắc trực tiếp Nhân viên/Leader nếu Admin đã yêu cầu bổ sung tài liệu.
if _ll_notice_role in EMPLOYEE_LIKE_ROLES:
    try:
        _ll_mine_notice = load_long_leave_requests()
        if isinstance(_ll_mine_notice, pd.DataFrame) and not _ll_mine_notice.empty:
            _mine_warn = _ll_mine_notice[
                _ll_mine_notice["Tên nhân viên"].astype(str).apply(normalize_login_name)
                .eq(normalize_login_name(st.session_state.get("current_user", "")))
                & _ll_mine_notice["Nhắc tải tài liệu"].astype(str).str.strip().ne("")
            ].copy()
            _need_docs = []
            for _, _rr in _mine_warn.iterrows():
                if not _parse_long_leave_documents(_rr.get("Tài liệu JSON", "")):
                    _need_docs.append(str(_rr.get("ID", "")).strip())
            if _need_docs and selected_page != "🏖️ Lịch nghỉ dài hạn":
                _first_need_doc = _need_docs[0]
                _suffix = (
                    f" và {len(_need_docs)-1} đơn khác"
                    if len(_need_docs) > 1 else ""
                )
                render_clickable_app_notice(
                    f"🔔 Admin đang nhắc bạn tải tài liệu cho đơn {_first_need_doc}{_suffix}. Bấm để mở ngay.",
                    "🏖️ Lịch nghỉ dài hạn",
                    f"long_leave_docs:{_first_need_doc}",
                    kind="warning",
                )
    except Exception:
        pass


def render_global_unsaved_changes_guard(page_labels):
    """V70: cảnh báo khi rời trang trong lúc form/data editor còn thay đổi chưa lưu.

    Chạy phía trình duyệt nên vẫn phát hiện được thay đổi bên trong st.form trước khi
    Streamlit gửi dữ liệu về Python. Áp dụng chung cho các vùng chỉnh dữ liệu của hệ thống.
    """
    labels_json = json.dumps([str(x) for x in (page_labels or [])], ensure_ascii=False)
    components.html(f"""
<script>
(function() {{
  try {{
    const W = window.parent, D = W.document;
    const NAV_LABELS = {labels_json};
    if (W.__veraUnsavedGuardV70) {{
      W.__veraUnsavedGuardV70.setNavLabels(NAV_LABELS);
      return;
    }}

    let dirty = false;
    let navLabels = NAV_LABELS.slice();
    const bannerId = 'vera-unsaved-banner-v70';

    function ensureBanner() {{
      let b = D.getElementById(bannerId);
      if (!b) {{
        b = D.createElement('div');
        b.id = bannerId;
        b.style.cssText = 'position:fixed;left:50%;top:8px;transform:translateX(-50%);z-index:2147483647;background:#fff3cd;color:#664d03;border:1px solid #D9D9D9;border-radius:8px;padding:8px 14px;font:600 13px Arial,sans-serif;box-shadow:0 2px 10px rgba(0,0,0,.12);display:none;max-width:92vw;text-align:center;';
        b.textContent = '⚠️ Có thay đổi chưa lưu. Hãy bấm Lưu trước khi chuyển trang hoặc thoát.';
        D.body.appendChild(b);
      }}
      return b;
    }}
    function setDirty() {{ dirty = true; ensureBanner().style.display = 'block'; }}
    function clearDirty() {{ dirty = false; const b = D.getElementById(bannerId); if (b) b.style.display='none'; }}
    function isEditableArea(t) {{
      if (!t || !t.closest) return false;
      if (t.closest('[data-testid="stDataEditor"]')) return true;

      const form = t.closest('[data-testid="stForm"]');
      if (form) {{
        const txt = (form.innerText || '').toLowerCase();
        return /lưu|cập nhật|ghi đè|xóa|xoá|thêm nhân viên|chỉnh sửa|thiết lập|save/.test(txt);
      }}

      // Các màn hình cũ chưa dùng st.form: chỉ đánh dấu dirty khi input nằm trong
      // một khối có nút ghi dữ liệu, đồng thời bỏ qua các ô chỉ dùng để lọc/tìm kiếm.
      const widget = t.closest('[data-testid="stTextInput"],[data-testid="stNumberInput"],[data-testid="stSelectbox"],[data-testid="stCheckbox"],[data-testid="stDateInput"],[data-testid="stTextArea"],[data-testid="stFileUploader"]');
      if (!widget) return false;
      const widgetText = (widget.innerText || '').toLowerCase();
      if (/lọc|tìm kiếm|tìm theo|search|chọn khoảng thời gian|chọn ngày:|lọc thời gian|chọn bảng cần tùy chỉnh/.test(widgetText)) return false;
      let block = widget.closest('[data-testid="stVerticalBlock"]');
      let hops = 0;
      while (block && hops < 4) {{
        const txt = (block.innerText || '').toLowerCase();
        if (/💾|lưu|cập nhật|ghi đè|xóa|xoá|thêm nhân viên|chỉnh sửa hồ sơ|thiết lập|save/.test(txt)) return true;
        block = block.parentElement ? block.parentElement.closest('[data-testid="stVerticalBlock"]') : null;
        hops += 1;
      }}
      return false;
    }}
    function isEditEventTarget(t) {{
      if (!isEditableArea(t)) return false;
      const tag = (t.tagName || '').toLowerCase();
      return ['input','textarea','select'].includes(tag) || (t.getAttribute && (t.getAttribute('role') === 'checkbox' || t.getAttribute('contenteditable') === 'true'));
    }}
    function markFromEvent(e) {{ if (isEditEventTarget(e.target)) setDirty(); }}
    D.addEventListener('input', markFromEvent, true);
    D.addEventListener('change', markFromEvent, true);
    D.addEventListener('keydown', function(e) {{
      if (isEditableArea(e.target) && !['Shift','Control','Alt','Meta','Tab','Escape','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)) setDirty();
    }}, true);

    D.addEventListener('click', function(e) {{
      const btn = e.target && e.target.closest ? e.target.closest('button') : null;
      if (!btn) return;
      const text = (btn.innerText || btn.textContent || '').trim();
      const low = text.toLowerCase();

      // Các nút thực hiện ghi/xóa dữ liệu: form sẽ gửi ngay sau click nên bỏ cờ cảnh báo.
      if (/lưu|ghi đè|xóa|xoá|cập nhật hồ sơ|cập nhật nhân viên|thêm nhân viên|save/.test(low)) {{
        clearDirty();
        return;
      }}

      const inSidebar = !!btn.closest('[data-testid="stSidebar"]');
      const isNav = inSidebar || navLabels.some(x => text === x) || /đăng xuất/i.test(text);
      if (dirty && isNav) {{
        const ok = W.confirm('Bạn đang có thay đổi CHƯA LƯU.\n\nNhấn HỦY để quay lại và bấm LƯU bản cập nhật.\nNhấn OK nếu muốn rời trang và BỎ các thay đổi chưa lưu.');
        if (!ok) {{
          e.preventDefault(); e.stopPropagation(); e.stopImmediatePropagation();
          return false;
        }}
        clearDirty();
      }}
    }}, true);

    W.addEventListener('beforeunload', function(e) {{
      if (!dirty) return;
      e.preventDefault();
      e.returnValue = '';
    }});

    W.__veraUnsavedGuardV70 = {{
      setDirty, clearDirty,
      isDirty: () => dirty,
      setNavLabels: (xs) => {{ navLabels = Array.isArray(xs) ? xs.slice() : []; }}
    }};
  }} catch (err) {{}}
}})();
</script>
""", height=0, width=0)


render_global_unsaved_changes_guard(allowed_pages)


# ==========================================================
# V87.5 - GHI NHỚ TAB ĐANG MỞ TRÊN TOÀN HỆ THỐNG
# Streamlit st.tabs() mặc định quay về tab đầu sau rerun.
# Script này ghi nhớ tab người dùng bấm trong sessionStorage và tự mở lại
# đúng tab sau rerun. Áp dụng cho mọi nhóm st.tabs trong app.
# ==========================================================
components.html(r"""
<script>
(function () {
  try {
    const W = window.parent;
    const D = W.document;
    const STORE_PREFIX = 'vera_active_tab_v875:';

    function currentPageKey() {
      try {
        const u = new URL(W.location.href);
        return u.searchParams.get('page') || W.location.pathname || 'default';
      } catch (e) {
        return 'default';
      }
    }

    function cleanText(value) {
      return String(value || '').replace(/\s+/g, ' ').trim();
    }

    function tabGroups() {
      return Array.from(D.querySelectorAll('[data-testid="stTabs"]'));
    }

    function buttonsOf(group) {
      return Array.from(group.querySelectorAll('[role="tab"]'));
    }

    function storageKey(group, groupIndex) {
      const labels = buttonsOf(group).map(b => cleanText(b.innerText || b.textContent));
      return STORE_PREFIX + currentPageKey() + ':' + groupIndex + ':' + labels.join('|');
    }

    function activeLabel(group) {
      const buttons = buttonsOf(group);
      const active = buttons.find(b =>
        b.getAttribute('aria-selected') === 'true' ||
        b.getAttribute('data-state') === 'active'
      );
      return active ? cleanText(active.innerText || active.textContent) : '';
    }

    let restoring = false;
    let restoreTimer = null;

    function bindAndRestore() {
      if (restoring) return;

      const groups = tabGroups();
      groups.forEach((group, groupIndex) => {
        const buttons = buttonsOf(group);
        if (!buttons.length) return;

        const key = storageKey(group, groupIndex);

        // Luôn gắn listener vào DOM mới sau mỗi rerun.
        buttons.forEach(btn => {
          if (btn.dataset.veraTabPersistV875 === '1') return;
          btn.dataset.veraTabPersistV875 = '1';

          btn.addEventListener('click', function () {
            try {
              const label = cleanText(btn.innerText || btn.textContent);
              if (label) W.sessionStorage.setItem(key, label);
            } catch (e) {}
          }, true);
        });

        let saved = '';
        try {
          saved = cleanText(W.sessionStorage.getItem(key));
        } catch (e) {}

        if (!saved) {
          // Lần đầu vào trang: nhớ tab mặc định hiện tại.
          const current = activeLabel(group);
          if (current) {
            try { W.sessionStorage.setItem(key, current); } catch (e) {}
          }
          return;
        }

        const current = activeLabel(group);
        if (current === saved) return;

        const target = buttons.find(
          btn => cleanText(btn.innerText || btn.textContent) === saved
        );
        if (!target) return;

        restoring = true;
        setTimeout(() => {
          try {
            target.click();
          } catch (e) {}
          restoring = false;
        }, 30);
      });
    }

    function scheduleRestore() {
      clearTimeout(restoreTimer);
      restoreTimer = setTimeout(bindAndRestore, 80);
    }

    // Singleton observer để không nhân nhiều listener qua các rerun.
    if (!W.__veraPersistentTabsV875) {
      const observer = new MutationObserver(scheduleRestore);
      observer.observe(D.body, { childList: true, subtree: true });
      W.__veraPersistentTabsV875 = {
        observer: observer,
        restore: bindAndRestore
      };
      W.addEventListener('pageshow', scheduleRestore);
      W.addEventListener('popstate', scheduleRestore);
    } else {
      W.__veraPersistentTabsV875.restore = bindAndRestore;
    }

    // Một số widget render chậm: thử phục hồi vài nhịp.
    setTimeout(bindAndRestore, 50);
    setTimeout(bindAndRestore, 180);
    setTimeout(bindAndRestore, 500);
  } catch (e) {
    console.debug('Vera persistent tabs V87.5:', e);
  }
})();
</script>
""", height=0, width=0)


# V90.8 - ĐÃ LOẠI BỎ HOÀN TOÀN NÚT LƯU / SAVE NỔI.
# Chỉ giữ cleanup để xóa floater V72 còn tồn tại trong DOM/session của trình duyệt
# sau khi người dùng cập nhật app mà chưa đóng tab.
components.html(r"""
<script>
(function () {
  try {
    const W = window.parent;
    const D = W.document;

    const oldFloat = D.getElementById('vera-global-floating-save-v72');
    if (oldFloat) oldFloat.remove();

    const oldStyle = D.getElementById('vera-global-floating-save-style-v72');
    if (oldStyle) oldStyle.remove();

    try {
      if (W.__veraFloatingSaveObserverV72) {
        W.__veraFloatingSaveObserverV72.disconnect();
        W.__veraFloatingSaveObserverV72 = null;
      }
    } catch(e) {}

    try {
      if (W.__veraFloatingSaveIntervalV72) {
        W.clearInterval(W.__veraFloatingSaveIntervalV72);
        W.__veraFloatingSaveIntervalV72 = null;
      }
    } catch(e) {}

    W.__veraFloatingSaveBoundV72 = false;

    // Phòng trường hợp DOM cũ tái xuất hiện trong vài trăm ms.
    [50, 250, 800, 1600].forEach(function(ms){
      setTimeout(function(){
        const x = D.getElementById('vera-global-floating-save-v72');
        if (x) x.remove();
      }, ms);
    });
  } catch(e) {}
})();
</script>
""", height=0, width=0)


def open_app_page(page_name):
    if page_name not in allowed_pages:
        return
    st.session_state.app_page = page_name
    st.query_params["page"] = PAGE_SLUGS[page_name]
    st.session_state["_vera_collapse_sidebar_once"] = True
    rerun_current_view()


def collapse_sidebar_after_navigation_once():
    """Sau khi chọn xong một mục MENU CHỨC NĂNG, tự thu gọn sidebar một lần."""
    if not st.session_state.pop("_vera_collapse_sidebar_once", False):
        return
    components.html(r"""
    <script>
    (function(){
      try {
        const doc = window.parent.document;
        const clickCollapse = () => {
          const collapsedControl =
            doc.querySelector('[data-testid="collapsedControl"]')
            || doc.querySelector('[data-testid="stSidebarCollapsedControl"]');
          if (collapsedControl && collapsedControl.offsetParent !== null) return;
          const sidebar = doc.querySelector('[data-testid="stSidebar"]');
          if (!sidebar) return;
          const candidates = [
            doc.querySelector('[data-testid="stSidebarCollapseButton"] button'),
            doc.querySelector('[data-testid="stSidebarCollapseButton"]'),
            doc.querySelector('[data-testid="stSidebarHeader"] button'),
            sidebar.querySelector('button[aria-label="Close sidebar"]'),
            sidebar.querySelector('button[aria-label*="sidebar" i]'),
            sidebar.querySelector('button[kind="header"]')
          ].filter(Boolean);
          const btn = candidates.find(x => !x.disabled);
          if (btn) btn.click();
        };
        setTimeout(clickCollapse, 80);
        setTimeout(clickCollapse, 260);
      } catch (e) {}
    })();
    </script>
    """, height=0, width=0)

